/* ============================================================
   StormzQuiz — questions.js
   Question banks for every board/subject. Each question has
   exactly 4 options and exactly 1 correct `answer` (zero-based
   index), plus an explanation. window.BOARDS (built at the
   bottom of this file) nests everything by board -> subject.
   ============================================================ */

const MATH_QUESTIONS = [
  { question: "Solve for x: 3x - 7 = 20.", options: ["7", "8", "9", "11"], answer: 2, explanation: "Add 7 to both sides: 3x = 27. Divide by 3: x = 9." },
  { question: "If 2(x + 5) = 3x - 4, what is the value of x?", options: ["10", "12", "14", "16"], answer: 2, explanation: "Distribute: 2x + 10 = 3x - 4. Subtract 2x: 10 = x - 4. Add 4: x = 14." },
  { question: "Solve the inequality: -3x + 5 > 20.", options: ["x < -5", "x > -5", "x < 5", "x > 5"], answer: 0, explanation: "Subtract 5: -3x > 15. Divide by -3 and flip the inequality: x < -5." },
  { question: "Solve the inequality: 2x + 3 ≤ 15.", options: ["x ≤ 6", "x ≥ 6", "x ≤ 9", "x ≥ 9"], answer: 0, explanation: "Subtract 3: 2x ≤ 12. Divide by 2: x ≤ 6." },
  { question: "A taxi charges a $3.00 flat fee plus $0.25 per fifth of a mile. If a ride costs $9.50, how many miles was the ride?", options: ["4.8", "5.0", "5.2", "5.5"], answer: 2, explanation: "The fare above the flat fee is $6.50. Dividing by $0.25 gives 26 fifths of a mile, which is 26 × 0.2 = 5.2 miles." },
  { question: "If x + y = 10 and x - y = 2, what is the value of x?", options: ["4", "5", "6", "7"], answer: 2, explanation: "Adding the two equations eliminates y: 2x = 12, so x = 6." },
  { question: "If 2x + 3y = 12 and x = y + 1, what is the value of x?", options: ["2", "3", "4", "5"], answer: 1, explanation: "Substitute x = y + 1: 2(y+1) + 3y = 12 → 5y + 2 = 12 → y = 2. Then x = y + 1 = 3." },
  { question: "How many solutions does the system 4x - 2y = 8 and 6x - 3y = 12 have?", options: ["0", "1", "2", "Infinitely many"], answer: 3, explanation: "Multiplying the first equation by 1.5 gives 6x - 3y = 12, identical to the second equation, so every point on the line is a solution." },
  { question: "What is the sum of the solutions to x² - 5x + 6 = 0?", options: ["1", "5", "6", "-5"], answer: 1, explanation: "The equation factors as (x-2)(x-3) = 0, giving roots 2 and 3. Their sum is 5." },
  { question: "What is the product of the solutions to x² - 9 = 0?", options: ["-9", "9", "3", "-3"], answer: 0, explanation: "The solutions are x = 3 and x = -3. Their product is 3 × (-3) = -9." },
  { question: "What are the solutions to 2x² + 3x - 5 = 0?", options: ["x = 1 and x = -5/2", "x = -1 and x = 5/2", "x = 1 and x = 5/2", "x = -1 and x = -5/2"], answer: 0, explanation: "The equation factors as (2x + 5)(x - 1) = 0, giving x = 1 or x = -5/2." },
  { question: "What is the minimum value of f(x) = (x - 3)² + 4?", options: ["3", "4", "-3", "-4"], answer: 1, explanation: "The function is in vertex form with vertex (3, 4). Since the parabola opens upward, the minimum value is 4." },
  { question: "A ball's height in feet is modeled by h(t) = -16t² + 64t, where t is seconds. At what time does the ball reach its maximum height?", options: ["1", "2", "3", "4"], answer: 1, explanation: "The vertex occurs at t = -b/(2a) = -64/(2 × -16) = 2 seconds." },
  { question: "Simplify: (2x³)(3x⁵).", options: ["5x⁸", "6x⁸", "6x¹⁵", "5x¹⁵"], answer: 1, explanation: "Multiply coefficients (2 × 3 = 6) and add exponents (3 + 5 = 8): 6x⁸." },
  { question: "Simplify: (x⁴)³ / x⁵.", options: ["x⁷", "x¹²", "x¹⁷", "x²"], answer: 0, explanation: "(x⁴)³ = x¹². Dividing by x⁵ subtracts exponents: x¹² / x⁵ = x⁷." },
  { question: "If 3^(2x) = 81, what is the value of x?", options: ["1", "2", "4", "8"], answer: 1, explanation: "81 = 3⁴, so 2x = 4, which gives x = 2." },
  { question: "Simplify: √50.", options: ["5√2", "10√2", "25√2", "2√5"], answer: 0, explanation: "50 = 25 × 2, so √50 = √25 × √2 = 5√2." },
  { question: "Solve: √(x + 3) = 5.", options: ["2", "16", "22", "28"], answer: 2, explanation: "Square both sides: x + 3 = 25, so x = 22." },
  { question: "Simplify: √72 / √2.", options: ["6", "36", "6√2", "3√2"], answer: 0, explanation: "√72 / √2 = √(72/2) = √36 = 6." },
  { question: "If f(x) = 2x² - 3x + 1, what is f(-2)?", options: ["9", "11", "15", "17"], answer: 2, explanation: "f(-2) = 2(4) - 3(-2) + 1 = 8 + 6 + 1 = 15." },
  { question: "If f(x) = x² - 4, what is the sum of all values of x for which f(x) = 0?", options: ["-2", "0", "2", "4"], answer: 1, explanation: "x² - 4 = 0 gives x = 2 or x = -2. Their sum is 0." },
  { question: "If g(x) = 3x + 2 and g(f(x)) = 3x² + 2, what is f(x)?", options: ["x²", "x²/3", "3x²", "x² + 2"], answer: 0, explanation: "g(f(x)) = 3·f(x) + 2. Setting this equal to 3x² + 2 gives 3·f(x) = 3x², so f(x) = x²." },
  { question: "The graph of y = f(x) passes through the point (2, 5). Which point must lie on the graph of y = f(x) + 3?", options: ["(2, 8)", "(5, 3)", "(2, 2)", "(-2, 5)"], answer: 0, explanation: "Adding 3 to f(x) shifts every point up 3 units, so (2, 5) becomes (2, 8)." },
  { question: "40 is what percent of 160?", options: ["20%", "25%", "30%", "40%"], answer: 1, explanation: "40/160 = 0.25 = 25%." },
  { question: "A $50 shirt is discounted 20%, and then the new price is discounted an additional 10%. What is the final price?", options: ["$30", "$35", "$36", "$40"], answer: 2, explanation: "After 20% off: 50 × 0.8 = $40. After 10% more off: 40 × 0.9 = $36." },
  { question: "A value increases from 80 to 100. What is the percent increase?", options: ["20%", "25%", "30%", "40%"], answer: 1, explanation: "The increase is 20. 20/80 = 0.25 = 25%." },
  { question: "A recipe requires a flour-to-sugar ratio of 5:2. If 15 cups of flour are used, how much sugar is needed?", options: ["4 cups", "5 cups", "6 cups", "7.5 cups"], answer: 2, explanation: "15 cups of flour is 3 times the ratio unit (15/5 = 3), so sugar is 3 × 2 = 6 cups." },
  { question: "If 3 pencils cost $1.50, how much do 8 pencils cost at the same rate?", options: ["$3.00", "$4.00", "$4.50", "$5.00"], answer: 1, explanation: "Each pencil costs $0.50. Eight pencils cost 8 × $0.50 = $4.00." },
  { question: "A car travels 240 miles in 4 hours at a constant speed. At the same rate, how far does it travel in 6.5 hours?", options: ["360", "375", "390", "400"], answer: 2, explanation: "The rate is 240/4 = 60 mph. In 6.5 hours: 60 × 6.5 = 390 miles." },
  { question: "Machine A fills 20 bottles per minute and Machine B fills 30 bottles per minute. Working together, how many minutes will it take to fill 500 bottles?", options: ["8", "10", "12", "15"], answer: 1, explanation: "Combined rate is 50 bottles per minute. 500/50 = 10 minutes." },
  { question: "Twice a number decreased by 7 is 15. What is the number?", options: ["9", "10", "11", "12"], answer: 2, explanation: "2x - 7 = 15 → 2x = 22 → x = 11." },
  { question: "The sum of three consecutive integers is 72. What is the largest of the three integers?", options: ["23", "24", "25", "26"], answer: 2, explanation: "Let the integers be n, n+1, n+2. Then 3n + 3 = 72, so n = 23, and the largest is 25." },
  { question: "John is twice as old as Mary. In 5 years, the sum of their ages will be 40. How old is Mary now?", options: ["8", "9", "10", "12"], answer: 2, explanation: "Let Mary's age be m and John's be 2m. (m+5) + (2m+5) = 40 → 3m + 10 = 40 → m = 10." },
  { question: "In a survey of 200 people, 120 said they prefer tea over coffee, and everyone else prefers coffee. What percent prefer coffee?", options: ["30%", "35%", "40%", "45%"], answer: 2, explanation: "80 people prefer coffee. 80/200 = 0.40 = 40%." },
  { question: "A scatterplot shows a strong negative linear association between hours of TV watched per week and test scores. Which statement best describes this relationship?", options: ["As TV hours increase, scores tend to increase", "As TV hours increase, scores tend to decrease", "There is no relationship between TV hours and scores", "Scores are constant regardless of TV hours"], answer: 1, explanation: "A negative association means the two variables move in opposite directions: as one increases, the other tends to decrease." },
  { question: "Find the mean of the data set: 4, 8, 8, 10, 15.", options: ["8", "8.5", "9", "10"], answer: 2, explanation: "The sum is 45. Dividing by 5 values gives a mean of 9." },
  { question: "Find the median of the data set: 3, 7, 9, 12, 20, 25.", options: ["9", "10", "10.5", "12"], answer: 2, explanation: "With 6 values, the median is the average of the 3rd and 4th values: (9 + 12)/2 = 10.5." },
  { question: "A bag contains 5 red, 3 blue, and 2 green marbles. What is the probability of drawing a blue marble at random?", options: ["1/5", "3/10", "1/2", "3/5"], answer: 1, explanation: "There are 3 blue marbles out of 10 total, giving a probability of 3/10." },
  { question: "Two fair coins are flipped. What is the probability that both land on heads?", options: ["1/2", "1/3", "1/4", "1/8"], answer: 2, explanation: "Each coin independently has a 1/2 chance of heads. 1/2 × 1/2 = 1/4." },
  { question: "In a triangle, the three angles measure x, 2x, and 3x degrees. What is the value of x?", options: ["20", "25", "30", "36"], answer: 2, explanation: "The angles of a triangle sum to 180°: x + 2x + 3x = 180 → 6x = 180 → x = 30." },
  { question: "In triangle ABC, angle A = 50° and angle B = 70°. What is the measure of angle C?", options: ["50°", "60°", "70°", "80°"], answer: 1, explanation: "The angles sum to 180°: 180 - 50 - 70 = 60°." },
  { question: "A rectangle has a length of 12 and a width of 7. What is its area?", options: ["19", "38", "84", "168"], answer: 2, explanation: "Area = length × width = 12 × 7 = 84." },
  { question: "A triangle has a base of 10 and a height of 6. What is its area?", options: ["16", "30", "60", "120"], answer: 1, explanation: "Area = (1/2) × base × height = (1/2) × 10 × 6 = 30." },
  { question: "A rectangular prism has dimensions 4, 5, and 6. What is its volume?", options: ["60", "90", "120", "140"], answer: 2, explanation: "Volume = 4 × 5 × 6 = 120." },
  { question: "A cylinder has a radius of 3 and a height of 10. What is its volume, in terms of π?", options: ["30π", "60π", "90π", "120π"], answer: 2, explanation: "Volume = πr²h = π(3²)(10) = 90π." },
  { question: "What is the circumference of a circle with radius 7, in terms of π?", options: ["7π", "14π", "49π", "28π"], answer: 1, explanation: "Circumference = 2πr = 2π(7) = 14π." },
  { question: "What is the area of a circle with diameter 10, in terms of π?", options: ["10π", "25π", "50π", "100π"], answer: 1, explanation: "The radius is 5. Area = πr² = π(5²) = 25π." },
  { question: "A circle has the equation (x - 2)² + (y + 3)² = 16. What is its radius?", options: ["2", "4", "8", "16"], answer: 1, explanation: "In the form (x-h)² + (y-k)² = r², r² = 16, so r = 4." },
  { question: "A right triangle has legs of length 6 and 8. What is the length of the hypotenuse?", options: ["9", "10", "12", "14"], answer: 1, explanation: "By the Pythagorean theorem: √(6² + 8²) = √(36 + 64) = √100 = 10." },
  { question: "A right triangle has a hypotenuse of 13 and one leg of length 5. What is the length of the other leg?", options: ["10", "11", "12", "13"], answer: 2, explanation: "By the Pythagorean theorem: √(13² - 5²) = √(169 - 25) = √144 = 12." },
  { question: "In a right triangle, angle θ has an opposite side of length 3 and a hypotenuse of length 5. What is sin θ?", options: ["3/4", "3/5", "4/5", "5/3"], answer: 1, explanation: "sin θ = opposite/hypotenuse = 3/5." },
  { question: "In a right triangle, cos θ = 4/5. What is sin θ?", options: ["3/5", "4/5", "1", "3/4"], answer: 0, explanation: "With adjacent = 4 and hypotenuse = 5, the opposite side is √(25-16) = 3, so sin θ = 3/5." },
  { question: "What is the distance between the points (1, 2) and (4, 6)?", options: ["4", "5", "6", "7"], answer: 1, explanation: "Distance = √[(4-1)² + (6-2)²] = √(9 + 16) = √25 = 5." },
  { question: "What is the midpoint of the segment connecting (2, -3) and (8, 5)?", options: ["(5, 1)", "(4, 2)", "(5, 2)", "(6, 1)"], answer: 0, explanation: "Midpoint = ((2+8)/2, (-3+5)/2) = (5, 1)." },
  { question: "What is the slope of the line through (2, 3) and (6, 11)?", options: ["1", "2", "3", "4"], answer: 1, explanation: "Slope = (11-3)/(6-2) = 8/4 = 2." },
  { question: "A line has a slope of -2 and passes through (0, 5). What is its equation?", options: ["y = -2x + 5", "y = 2x + 5", "y = -2x - 5", "y = 5x - 2"], answer: 0, explanation: "Using slope-intercept form y = mx + b with m = -2 and b = 5 (the y-intercept) gives y = -2x + 5." },
  { question: "How do the lines y = 3x + 2 and y = 3x - 5 relate to each other?", options: ["Parallel", "Perpendicular", "They intersect at exactly one point", "They are identical"], answer: 0, explanation: "Both lines have slope 3 but different y-intercepts, so they are parallel and never intersect." },
  { question: "What is the slope of a line perpendicular to y = (1/3)x + 4?", options: ["1/3", "-1/3", "3", "-3"], answer: 3, explanation: "A perpendicular slope is the negative reciprocal of 1/3, which is -3." },
  { question: "An arithmetic sequence has a first term of 4 and a common difference of 5. What is the 10th term?", options: ["44", "45", "49", "54"], answer: 2, explanation: "aₙ = a₁ + (n-1)d = 4 + 9(5) = 49." },
  { question: "A geometric sequence has a first term of 3 and a common ratio of 2. What is the 5th term?", options: ["24", "36", "48", "96"], answer: 2, explanation: "aₙ = a₁ · r^(n-1) = 3 · 2⁴ = 3 × 16 = 48." },
  { question: "A sequence is defined by a₁ = 2 and aₙ = a₍ₙ₋₁₎ + 3. What is a₄?", options: ["8", "11", "14", "17"], answer: 1, explanation: "a₁=2, a₂=5, a₃=8, a₄=11." },
  { question: "A population grows according to P(t) = 500(1.05)^t, where t is measured in years. What does 1.05 represent?", options: ["A 5% annual growth rate", "A 5% annual decay rate", "A 50% growth rate", "The initial population of 500"], answer: 0, explanation: "A growth factor of 1.05 corresponds to a 5% increase each year (1 + 0.05)." },
  { question: "A cost function is C(x) = 200 + 15x, where x is the number of items produced. What does the 200 represent?", options: ["The fixed cost", "The cost per item", "The total cost for 15 items", "The number of items produced"], answer: 0, explanation: "The 200 is added regardless of x, so it represents a fixed cost incurred before any items are produced." },
  { question: "A car's value depreciates according to V(t) = 25000(0.88)^t. What is the annual percent decrease in value?", options: ["8%", "12%", "88%", "25%"], answer: 1, explanation: "A decay factor of 0.88 means the value retains 88% each year, a decrease of 100% - 88% = 12%." },
  { question: "Solve for y: 5y - 3 = 2y + 12.", options: ["3", "4", "5", "6"], answer: 2, explanation: "Subtract 2y: 3y - 3 = 12. Add 3: 3y = 15. Divide by 3: y = 5." },
  { question: "Solve the compound inequality: -4 < 2x - 6 < 10.", options: ["1 < x < 8", "-1 < x < 8", "1 < x < 16", "-5 < x < 2"], answer: 0, explanation: "Add 6 to all parts: 2 < 2x < 16. Divide by 2: 1 < x < 8." },
  { question: "If 3x + y = 7 and 2x - y = 3, what is the value of y?", options: ["0", "1", "2", "3"], answer: 1, explanation: "Adding the equations eliminates y-terms incorrectly; instead add to get 5x = 10, so x = 2. Substituting into 3(2) + y = 7 gives y = 1." },
  { question: "At how many points does the graph of y = x² - 6x + 9 touch the x-axis?", options: ["0", "1", "2", "Infinitely many"], answer: 1, explanation: "The discriminant is 6² - 4(1)(9) = 36 - 36 = 0, meaning there is exactly one (repeated) real root, so the parabola touches the x-axis once." },
  { question: "Factor completely: x² + 7x + 12.", options: ["(x + 3)(x + 4)", "(x + 2)(x + 6)", "(x + 1)(x + 12)", "(x - 3)(x - 4)"], answer: 0, explanation: "We need two numbers that multiply to 12 and add to 7: 3 and 4. So x² + 7x + 12 = (x+3)(x+4)." },
  { question: "Simplify: (4x²y³)².", options: ["8x⁴y⁶", "16x⁴y⁶", "16x²y³", "8x²y⁶"], answer: 1, explanation: "Square each factor: 4² = 16, (x²)² = x⁴, (y³)² = y⁶, giving 16x⁴y⁶." },
  { question: "Evaluate: 5⁰ + 5⁻¹.", options: ["0", "1", "6/5", "5"], answer: 2, explanation: "5⁰ = 1 and 5⁻¹ = 1/5. Their sum is 1 + 1/5 = 6/5." },
  { question: "Simplify: √20 + √45.", options: ["5√5", "√65", "7√5", "5√13"], answer: 0, explanation: "√20 = 2√5 and √45 = 3√5. Adding: 2√5 + 3√5 = 5√5." },
  { question: "The function h(x) = -2x + 8 has a zero at what value of x?", options: ["2", "4", "6", "8"], answer: 1, explanation: "Set -2x + 8 = 0: -2x = -8, so x = 4." },
  { question: "What value must be excluded from the domain of f(x) = x/(x - 2)?", options: ["x ≠ 0", "x ≠ 2", "x ≠ -2", "No values are excluded"], answer: 1, explanation: "The denominator cannot equal 0, so x - 2 ≠ 0, meaning x ≠ 2." },
  { question: "A population of 4,000 increases by 8% in one year. What is the population after that year?", options: ["4,080", "4,320", "4,400", "4,800"], answer: 1, explanation: "4,000 × 1.08 = 4,320." },
  { question: "The ratio of boys to girls in a class is 3:4. If there are 28 students total, how many are boys?", options: ["9", "12", "15", "16"], answer: 1, explanation: "The ratio has 7 total parts, so each part is 28/7 = 4 students. Boys = 3 × 4 = 12." },
  { question: "A printer prints 45 pages in 3 minutes at a constant rate. How many pages does it print in 8 minutes?", options: ["100", "110", "120", "135"], answer: 2, explanation: "The rate is 45/3 = 15 pages per minute. In 8 minutes: 15 × 8 = 120 pages." },
  { question: "A number increased by 25% equals 60. What is the number?", options: ["45", "46", "48", "50"], answer: 2, explanation: "1.25x = 60, so x = 60/1.25 = 48." },
  { question: "The average of 5 numbers is 20. If one number is removed, the average of the remaining 4 numbers is 18. What was the value of the removed number?", options: ["22", "26", "28", "30"], answer: 2, explanation: "The sum of all 5 numbers is 100. The sum of the remaining 4 is 72. The removed number is 100 - 72 = 28." },
  { question: "A line graph shows temperature rising steadily from 8 a.m. to 12 p.m., then falling steadily until 6 p.m. During which interval was the temperature increasing?", options: ["8 a.m. to 12 p.m.", "12 p.m. to 6 p.m.", "8 a.m. to 6 p.m.", "The temperature never increased"], answer: 0, explanation: "The graph rises during the 8 a.m. to 12 p.m. interval, indicating increasing temperature." },
  { question: "Find the mode of the data set: 2, 2, 3, 5, 8.", options: ["2", "3", "5", "8"], answer: 0, explanation: "The mode is the value that appears most often. 2 appears twice, more than any other value." },
  { question: "A jar has 4 red and 6 blue marbles. Two marbles are drawn without replacement. What is the probability that both are red?", options: ["1/5", "2/15", "4/25", "2/9"], answer: 1, explanation: "P(first red) = 4/10. P(second red | first red) = 3/9. Multiplying: (4/10)(3/9) = 12/90 = 2/15." },
  { question: "The mean of six numbers is 15. Five of the numbers are 10, 12, 14, 16, and 18. What is the sixth number?", options: ["18", "19", "20", "22"], answer: 2, explanation: "The sum of all 6 numbers is 90. The sum of the given 5 is 70. The sixth number is 90 - 70 = 20." },
  { question: "What is the sum of the interior angles of a regular hexagon?", options: ["540°", "600°", "720°", "900°"], answer: 2, explanation: "Interior angle sum = (n - 2) × 180°. For a hexagon, n = 6: (6-2) × 180° = 720°." },
  { question: "What is the measure of each interior angle of a regular pentagon?", options: ["90°", "100°", "108°", "120°"], answer: 2, explanation: "The interior angle sum is (5-2) × 180° = 540°. Dividing by 5 sides: 540°/5 = 108°." },
  { question: "A trapezoid has parallel sides of length 8 and 12, and a height of 5. What is its area?", options: ["40", "45", "50", "60"], answer: 2, explanation: "Area = (1/2)(b₁ + b₂)(h) = (1/2)(8 + 12)(5) = (1/2)(20)(5) = 50." },
  { question: "A cone has a radius of 3 and a height of 8. What is its volume, in terms of π?", options: ["24π", "72π", "8π", "216π"], answer: 0, explanation: "Volume = (1/3)πr²h = (1/3)π(9)(8) = 24π." },
  { question: "An arc subtends a central angle of 60° in a circle with radius 6. What is the length of the arc, in terms of π?", options: ["π", "2π", "3π", "6π"], answer: 1, explanation: "Arc length = (60/360) × 2πr = (1/6) × 2π(6) = 2π." },
  { question: "A 15-foot ladder leans against a wall, reaching 12 feet up the wall. How far is the base of the ladder from the wall?", options: ["7", "8", "9", "10"], answer: 2, explanation: "By the Pythagorean theorem: √(15² - 12²) = √(225 - 144) = √81 = 9 feet." },
  { question: "In a right triangle, tan θ = 5/12. What is the length of the hypotenuse if the two legs are 5 and 12?", options: ["11", "12", "13", "14"], answer: 2, explanation: "√(5² + 12²) = √(25 + 144) = √169 = 13." },
  { question: "A line passes through (-2, 4) and is parallel to y = 5x - 1. What is its equation?", options: ["y = 5x + 14", "y = 5x - 14", "y = 5x + 6", "y = 5x - 6"], answer: 0, explanation: "Parallel lines share a slope of 5. Using point-slope form: y - 4 = 5(x + 2), which simplifies to y = 5x + 14." },
  { question: "What is the y-intercept of the line 4x + 2y = 12?", options: ["3", "4", "6", "12"], answer: 2, explanation: "Set x = 0: 2y = 12, so y = 6." },
  { question: "In an arithmetic sequence, a₃ = 11 and a₇ = 27. What is the common difference?", options: ["2", "3", "4", "5"], answer: 2, explanation: "From a₃ to a₇ is 4 steps: (27 - 11)/4 = 4." },
  { question: "A geometric sequence has a₁ = 5 and r = 3. Which term is the first to exceed 300?", options: ["3rd term", "4th term", "5th term", "6th term"], answer: 2, explanation: "The terms are 5, 15, 45, 135, 405. The 5th term, 405, is the first to exceed 300." },
  { question: "A tank starts with 800 gallons and drains at a constant rate, emptying completely after 20 minutes. Which equation models gallons remaining, g, after m minutes?", options: ["g = 800 - 40m", "g = 800 - 20m", "g = 40 - 800m", "g = 800 + 40m"], answer: 0, explanation: "The drain rate is 800/20 = 40 gallons per minute, so g = 800 - 40m." },
  { question: "Two trains leave the same station traveling in opposite directions, one at 60 mph and the other at 75 mph. After how many hours will they be 405 miles apart?", options: ["2", "2.5", "3", "3.5"], answer: 2, explanation: "Their combined separation rate is 60 + 75 = 135 mph. Time = 405/135 = 3 hours." },
  { question: "A store marks up a wholesale price of $40 by 35% to set the retail price. What is the retail price?", options: ["$50", "$52", "$54", "$56"], answer: 2, explanation: "40 × 1.35 = $54." },
  { question: "If x is 30% of 90 and y is 60% of 40, what is x + y?", options: ["48", "50", "51", "54"], answer: 2, explanation: "x = 0.30 × 90 = 27. y = 0.60 × 40 = 24. Sum: 27 + 24 = 51." },
  { question: "A student's first four quiz scores are 85, 90, 78, and 95. What score is needed on a fifth quiz to achieve an average of 88?", options: ["88", "90", "92", "95"], answer: 2, explanation: "To average 88 over 5 quizzes, the total must be 440. The current total is 348, so the fifth score must be 440 - 348 = 92." },
  { question: "If f(x) = 3x - 1 and f(a) = 11, what is the value of a?", options: ["3", "4", "5", "6"], answer: 1, explanation: "3a - 1 = 11 → 3a = 12 → a = 4." }
];

const ENGLISH_QUESTIONS = [
  { passage: "Coral reefs, though they cover less than 1% of the ocean floor, support roughly a quarter of all known marine species. This disproportionate richness stems from the reef's complex structure, which offers countless niches for organisms to feed, hide, and reproduce.", question: "Which choice best states the main idea of the text?", options: ["Coral reefs are shrinking rapidly due to ocean warming.", "Coral reefs support an outsized share of marine biodiversity relative to their size.", "Marine species prefer reefs over open ocean habitats.", "Reefs are the largest ecosystems in the ocean."], answer: 1, explanation: "The passage's central claim is that reefs, despite their small footprint, support a huge proportion of marine species — a point about disproportionate biodiversity." },
  { passage: "The invention of the printing press did not merely speed up the copying of texts; it restructured who could participate in intellectual life. Ideas that once traveled slowly among a literate elite could now reach merchants, craftsmen, and eventually ordinary readers.", question: "The text most strongly suggests that the printing press", options: ["was invented primarily for religious purposes", "had a greater social effect than simply making copying faster", "was rejected by the literate elite", "made intellectual life less complex"], answer: 1, explanation: "The passage explicitly says the press 'did not merely speed up copying' but changed who could participate in intellectual life, implying a broader social effect." },
  { passage: "Migratory birds rely on an internal magnetic sense to navigate thousands of miles each year. Remarkably, cloudy skies and unfamiliar terrain rarely throw them off course, suggesting their magnetic compass functions independently of visual landmarks.", question: "Based on the text, what can be reasonably inferred about migratory birds' navigation?", options: ["It depends entirely on the position of the sun.", "It is disrupted by any change in weather.", "It does not require clear visual cues to work.", "It only works during the day."], answer: 2, explanation: "The passage states that cloudy skies and unfamiliar terrain rarely throw the birds off course, implying their navigation works without relying on clear visual landmarks." },
  { passage: "A researcher studying urban traffic found that adding a single new road to a congested network sometimes increased average commute times rather than reducing them, a counterintuitive result now known as Braess's paradox.", question: "Which statement is best supported by the text?", options: ["Adding roads always reduces congestion.", "Braess's paradox shows that adding a road can worsen traffic under certain conditions.", "Urban planners no longer build new roads.", "Commute times are unrelated to road networks."], answer: 1, explanation: "The passage directly describes a case where adding a road increased commute times, which is the definition of Braess's paradox given in the text." },
  { passage: "Octopuses possess a distributed nervous system, with roughly two-thirds of their neurons located in their arms rather than their central brain. This arrangement allows each arm to process sensory information and initiate movement with a striking degree of independence.", question: "The main purpose of the text is to", options: ["argue that octopuses are more intelligent than humans", "describe how an octopus's arms process information somewhat independently of its brain", "explain why octopuses have eight arms", "compare octopus nervous systems to those of fish"], answer: 1, explanation: "The passage focuses on describing the distributed nervous system and the resulting independence of the arms — its main purpose is explanatory, not comparative or argumentative." },
  { passage: "Economists have long debated whether minimum wage increases reduce employment. Recent studies using more precise regional data have found effects that are smaller, and sometimes statistically indistinguishable from zero, compared to earlier, broader analyses.", question: "Which choice best describes the relationship between the two types of studies mentioned in the text?", options: ["The recent studies confirm the earlier findings exactly.", "The recent studies, using more precise data, tend to find smaller employment effects than earlier analyses.", "The recent studies ignore regional data entirely.", "The earlier analyses used more precise data than the recent studies."], answer: 1, explanation: "The text states the recent, more precise studies found smaller (sometimes negligible) effects compared to the earlier, broader analyses." },
  { passage: "In 1969, the Apollo 11 mission relied on onboard computers with less processing power than a modern pocket calculator, yet the mission successfully navigated to the Moon and back, a testament to the ingenuity of the software engineers who wrote highly efficient code.", question: "Which choice best states the main purpose of the text?", options: ["To criticize outdated 1960s technology", "To highlight the skill of the engineers who made a low-power computer succeed at a complex task", "To argue that modern calculators are more capable than they need to be", "To describe the physical design of the Apollo spacecraft"], answer: 1, explanation: "The text emphasizes that despite limited processing power, the mission succeeded, crediting the engineers' efficient code — this is a tribute to their ingenuity." },
  { passage: "The word \"ubiquitous\" comes from the Latin \"ubique,\" meaning \"everywhere.\" In modern usage, it describes something that seems to appear in every context imaginable, from technology to fashion trends.", question: "As used in the text, the word \"ubiquitous\" most nearly means", options: ["rare", "outdated", "present everywhere", "expensive"], answer: 2, explanation: "The passage defines the word directly: it describes something that appears in every context, meaning it is present everywhere." },
  { question: "In the sentence \"The novel's plot, though convoluted, was ultimately ______, rewarding readers who paid close attention,\" which word most logically completes the sentence?", options: ["coherent", "chaotic", "forgettable", "predictable"], answer: 0, explanation: "The sentence contrasts 'convoluted' with a positive outcome for attentive readers, so 'coherent' (making sense in the end) fits best." },
  { question: "In context, which word best replaces \"meticulous\" in the sentence \"The archivist was meticulous, cataloguing every document down to its exact date and condition\"?", options: ["careless", "painstaking", "hurried", "indifferent"], answer: 1, explanation: "'Meticulous' means showing great attention to detail, which matches 'painstaking.'" },
  { question: "Which choice completes the text with the most logical transition? \"The bridge was closed for repairs for six months. ______, traffic on the surrounding streets increased significantly.\"", options: ["However,", "As a result,", "For example,", "In contrast,"], answer: 1, explanation: "The increase in nearby traffic is a direct consequence of the bridge closure, so a cause-and-effect transition like 'As a result' is correct." },
  { question: "Which choice completes the text with the most logical transition? \"The committee reviewed hundreds of applications. ______, only twelve candidates were selected for interviews.\"", options: ["Similarly,", "Ultimately,", "For instance,", "Nevertheless,"], answer: 1, explanation: "The sentence describes the final outcome of the review process, which 'Ultimately' signals appropriately." },
  { question: "Which choice completes the text with the most logical transition? \"Researchers expected the drug to lower blood pressure significantly. ______, the clinical trial showed only a marginal effect.\"", options: ["Therefore,", "However,", "Similarly,", "In addition,"], answer: 1, explanation: "The trial result contradicts the expectation, so a contrast transition like 'However' is needed." },
  { question: "Which choice completes the text with the most logical transition? \"The company invested heavily in employee training. ______, productivity rose by nearly 20 percent within a year.\"", options: ["Consequently,", "Otherwise,", "Meanwhile,", "Regardless,"], answer: 0, explanation: "The productivity increase follows from the investment in training, making 'Consequently' the logical cause-effect transition." },
  { question: "Which choice completes the text with the most logical transition? \"Many students find statistics intimidating at first. ______, with consistent practice, most develop real confidence in the subject.\"", options: ["Yet,", "Likewise,", "For example,", "As a result,"], answer: 0, explanation: "The sentence shifts from initial intimidation to eventual confidence, a contrast best signaled by 'Yet.'" },
  { question: "Which choice completes the text with the most logical transition? \"The museum's new wing features interactive exhibits for children. ______, the original galleries remain unchanged, preserving their classic layout.\"", options: ["Similarly,", "In addition,", "By contrast,", "Therefore,"], answer: 2, explanation: "The sentence contrasts the new, interactive wing with the unchanged original galleries, so 'By contrast' fits best." },
  { question: "Which choice completes the text with the most logical transition? \"The film received lukewarm reviews from critics. ______, it became a major box office success.\"", options: ["Nonetheless,", "Similarly,", "Specifically,", "Because of this,"], answer: 0, explanation: "The box office success is surprising given the lukewarm reviews, so a contrast transition like 'Nonetheless' is appropriate." },
  { question: "Which choice completes the text with the most logical transition? \"The recipe calls for fresh basil. ______, dried basil can be substituted in a pinch, though the flavor will be milder.\"", options: ["Alternatively,", "Similarly,", "Therefore,", "In particular,"], answer: 0, explanation: "The sentence offers a substitute option, which 'Alternatively' correctly signals." },
  { question: "Which choice best fixes the sentence boundary error? \"The storm knocked out power across the city, residents relied on generators for nearly a week.\"", options: ["No change", "city; residents", "city. Residents,", "city, residents,"], answer: 1, explanation: "The original is a comma splice joining two independent clauses. A semicolon correctly joins them without a conjunction." },
  { question: "Which choice best fixes the sentence boundary error? \"Maria studied for weeks she still felt unprepared for the exam.\"", options: ["No change", "weeks, she", "weeks; she", "weeks she,"], answer: 2, explanation: "Two independent clauses are fused together with no punctuation. A semicolon correctly separates them." },
  { question: "Which choice best fixes the sentence boundary error? \"The experiment failed twice, the third attempt finally succeeded.\"", options: ["No change", "twice; the third attempt", "twice the third attempt", "twice, and the third, attempt"], answer: 1, explanation: "This is a comma splice joining two independent clauses; a semicolon fixes the error correctly." },
  { question: "Which choice best fixes the sentence boundary error? \"Because the flight was delayed. We missed our connection in Chicago.\"", options: ["No change", "Because the flight was delayed, we missed our connection in Chicago.", "Because the flight was delayed; we missed our connection in Chicago.", "Because the flight was delayed we missed, our connection in Chicago."], answer: 1, explanation: "The first part is a dependent clause and should be joined to the independent clause with a comma, not punctuated as its own sentence." },
  { question: "Which choice correctly punctuates the sentence? \"After finishing the marathon, Jake, exhausted but proud, called his family.\"", options: ["No change", "After finishing the marathon Jake, exhausted but proud, called his family.", "After finishing the marathon, Jake exhausted but proud called his family.", "After finishing the marathon, Jake, exhausted but proud called his family."], answer: 0, explanation: "The introductory phrase is correctly set off with a comma, and the nonessential appositive 'exhausted but proud' is correctly enclosed in commas on both sides." },
  { question: "Which choice correctly uses commas? \"The chef prepared a dish with fresh basil, ripe tomatoes, and imported olive oil.\"", options: ["No change", "fresh basil ripe tomatoes, and imported olive oil.", "fresh basil, ripe tomatoes and, imported olive oil.", "fresh basil, ripe tomatoes, and, imported olive oil."], answer: 0, explanation: "This is a correctly punctuated series of three items, each separated by a comma, including the Oxford comma before 'and.'" },
  { question: "Which choice correctly punctuates the sentence? \"My sister, who lives in Denver, is visiting next week.\"", options: ["No change", "My sister who lives in Denver, is visiting next week.", "My sister, who lives in Denver is visiting next week.", "My sister who lives in Denver is visiting, next week."], answer: 0, explanation: "The nonessential clause 'who lives in Denver' is correctly set off with commas on both sides." },
  { question: "Which choice correctly punctuates the sentence? \"Although it was raining we decided to go for a hike.\"", options: ["No change", "Although it was raining, we decided to go for a hike.", "Although, it was raining we decided to go for a hike.", "Although it was raining, we, decided to go for a hike."], answer: 1, explanation: "An introductory dependent clause should be followed by a comma before the independent clause begins." },
  { question: "Which choice correctly punctuates the sentence? \"The professor's argument, compelling as it seemed was ultimately based on flawed data.\"", options: ["No change", "The professor's argument, compelling as it seemed, was ultimately based on flawed data.", "The professor's argument compelling, as it seemed, was ultimately based on flawed data.", "The professor's argument, compelling as it, seemed was ultimately based on flawed data."], answer: 1, explanation: "The interrupting phrase 'compelling as it seemed' needs a comma on both sides to be correctly set off." },
  { question: "Which choice correctly punctuates the sentence? \"We packed sunscreen umbrellas and folding chairs for the beach.\"", options: ["No change", "We packed sunscreen, umbrellas, and folding chairs for the beach.", "We packed sunscreen, umbrellas and, folding chairs for the beach.", "We packed, sunscreen umbrellas, and folding chairs for the beach."], answer: 1, explanation: "This is a list of three items and requires commas separating each item, including before 'and.'" },
  { question: "Which choice correctly uses a colon? \"The recipe requires just three ingredients: flour, water, and salt.\"", options: ["No change", "requires just three ingredients, flour, water, and salt.", "requires just three ingredients; flour, water, and salt.", "requires just three ingredients flour, water, and salt."], answer: 0, explanation: "A colon correctly introduces a list following an independent clause." },
  { question: "Which choice correctly uses a semicolon? \"The lecture ran long; students began packing their bags before it ended.\"", options: ["No change", "The lecture ran long, students began packing their bags before it ended.", "The lecture ran long: students began packing their bags before it ended.", "The lecture ran long students began packing their bags before it ended."], answer: 0, explanation: "A semicolon correctly joins two closely related independent clauses without a conjunction." },
  { question: "Which choice correctly completes the sentence? \"She had only one goal for the summer ______ finish writing her novel.\"", options: ["; to", ": to", ", to", ". To"], answer: 1, explanation: "A colon correctly introduces the single goal that follows an independent clause." },
  { question: "Which choice correctly completes the sentence? \"The team faced a difficult choice ______ delay the launch or release an unfinished product.\"", options: ["; to", ": to", ", to", "to"], answer: 1, explanation: "A colon is used to introduce an explanation or elaboration following a complete independent clause." },
  { question: "Which choice correctly joins the two independent clauses? \"The engineers redesigned the bridge ______ the original had failed to withstand heavy winds.\"", options: ["because", ", because", "; because", "however"], answer: 0, explanation: "Because 'because' introduces a subordinate clause explaining the reason, no comma is needed before it in this construction." },
  { question: "Which choice correctly uses a semicolon to join two related ideas? \"The negotiations stalled for months; both sides refused to compromise on the key terms.\"", options: ["No change", "The negotiations stalled for months, both sides refused to compromise on the key terms.", "The negotiations stalled for months: both sides refused to compromise on the key terms.", "The negotiations stalled for months both sides refused to compromise on the key terms."], answer: 0, explanation: "A semicolon correctly links two independent clauses that are closely related in meaning." },
  { question: "Which choice correctly completes the sentence? \"Each of the students ______ required to submit a final project.\"", options: ["are", "is", "were", "have been"], answer: 1, explanation: "'Each' is a singular subject, so it takes the singular verb 'is,' even though 'students' is plural." },
  { question: "Which choice correctly completes the sentence? \"The collection of rare coins ______ displayed at the museum every summer.\"", options: ["are", "is", "were", "have"], answer: 1, explanation: "'Collection' is the singular subject, so the singular verb 'is' agrees, regardless of the plural noun 'coins' within the prepositional phrase." },
  { question: "Which choice correctly completes the sentence? \"Neither the manager nor the employees ______ aware of the policy change.\"", options: ["was", "is", "were", "has been"], answer: 2, explanation: "With 'neither...nor,' the verb agrees with the nearer subject, which is the plural 'employees,' so 'were' is correct." },
  { question: "Which choice correctly completes the sentence? \"The data ______ that the new treatment is more effective than the old one.\"", options: ["suggest", "suggests", "has suggested", "is suggesting"], answer: 0, explanation: "'Data' is technically the plural of 'datum' and, in formal SAT-style usage, takes the plural verb 'suggest.'" },
  { question: "Which choice correctly completes the sentence? \"Every one of the applicants ______ submitted a portfolio.\"", options: ["have", "has", "were", "are"], answer: 1, explanation: "'Every one' functions as a singular subject, requiring the singular verb 'has.'" },
  { question: "Which choice correctly completes the sentence? \"The committee, along with several outside consultants, ______ reviewing the proposal.\"", options: ["are", "is", "were", "have been"], answer: 1, explanation: "The subject is the singular 'committee'; the phrase 'along with several outside consultants' does not change the verb's number, so 'is' is correct." },
  { question: "Which choice correctly completes the sentence? \"Each student must bring ______ own laptop to class.\"", options: ["their", "his or her", "they're", "there"], answer: 1, explanation: "'Each student' is singular, so the pronoun should be singular ('his or her') to agree in formal usage; 'they're' and 'there' are also the wrong words entirely." },
  { question: "Which choice correctly completes the sentence? \"The company announced that ______ profits had increased for the third straight quarter.\"", options: ["its", "it's", "their", "there"], answer: 0, explanation: "The possessive pronoun for the singular noun 'company' is 'its,' not the contraction 'it's' or the plural 'their.'" },
  { question: "Which choice correctly completes the sentence? \"Between you and ______, I think the proposal needs more work.\"", options: ["I", "me", "myself", "mine"], answer: 1, explanation: "'Between' is a preposition and requires the object pronoun 'me,' not the subject pronoun 'I.'" },
  { question: "Which choice correctly completes the sentence? \"The award was given to the two researchers ______ discovery changed the field.\"", options: ["who's", "whose", "who", "which"], answer: 1, explanation: "The possessive pronoun 'whose' is needed to show that the discovery belongs to the researchers." },
  { question: "Which choice correctly completes the sentence? \"Neither of the twins has decided what ______ will study in college.\"", options: ["they", "he or she", "we", "them"], answer: 1, explanation: "'Neither' is singular, so the pronoun referring to it should be singular: 'he or she.'" },
  { question: "Which choice correctly completes the sentence? \"By the time the fire department arrived, the flames ______ already spread to the neighboring building.\"", options: ["have", "had", "has", "will have"], answer: 1, explanation: "The past perfect 'had spread' correctly shows an action completed before another past event (the department's arrival)." },
  { question: "Which choice correctly completes the sentence? \"Yesterday, the scientist ______ the results before publishing her paper.\"", options: ["double-checks", "double-checked", "will double-check", "double-checking"], answer: 1, explanation: "The sentence is set in the past ('Yesterday'), so the simple past tense 'double-checked' is correct." },
  { question: "Which choice correctly completes the sentence? \"By next year, the researchers ______ the study for over a decade.\"", options: ["conduct", "conducted", "will have conducted", "are conducting"], answer: 2, explanation: "The future perfect 'will have conducted' correctly describes an action that will be completed by a specific future point." },
  { question: "Which choice correctly completes the sentence? \"While she ______ dinner, the phone rang three times.\"", options: ["cooks", "was cooking", "cooked", "will cook"], answer: 1, explanation: "The past progressive 'was cooking' correctly shows an ongoing past action interrupted by another past event." },
  { question: "Which choice correctly completes the sentence? \"The museum ______ several new exhibits since it reopened last spring.\"", options: ["adds", "added", "has added", "will add"], answer: 2, explanation: "The present perfect 'has added' correctly connects a past action (reopening) to its continuing relevance now." },
  { question: "Which choice correctly fixes the modifier error? \"Walking through the museum, the paintings amazed the visitors.\"", options: ["No change", "Walking through the museum, the visitors were amazed by the paintings.", "Walking through the museum, the paintings, amazed, visited the visitors.", "The paintings, walking through the museum, amazed the visitors."], answer: 1, explanation: "The introductory phrase 'Walking through the museum' should modify the visitors, not the paintings, so the subject must be 'the visitors.'" },
  { question: "Which choice correctly fixes the modifier error? \"At the age of six, my grandmother taught me how to bake bread.\"", options: ["No change", "At the age of six, I was taught by my grandmother how to bake bread.", "My grandmother, at the age of six, taught me how to bake bread.", "At the age of six, bread baking was taught to me by my grandmother."], answer: 1, explanation: "The original sentence implies the grandmother was six. Rephrasing so 'I' is the subject connected to the introductory phrase fixes the dangling modifier." },
  { question: "Which choice correctly fixes the modifier error? \"Covered in dust, Maria found the old photographs in the attic.\"", options: ["No change", "Maria found the old photographs, covered in dust, in the attic.", "Covered in dust, the attic had old photographs found by Maria.", "In the attic, Maria, covered in dust, found the old photographs."], answer: 1, explanation: "The original implies Maria was covered in dust. Moving the modifier next to 'photographs' correctly shows what was actually covered in dust." },
  { question: "Which choice correctly fixes the modifier error? \"Having studied all night, the exam felt manageable to Sam.\"", options: ["No change", "Having studied all night, Sam found the exam manageable.", "The exam, having studied all night, felt manageable to Sam.", "Having studied all night Sam's exam felt manageable."], answer: 1, explanation: "The phrase 'Having studied all night' should modify Sam, not the exam, so 'Sam' must immediately follow the introductory phrase." },
  { question: "Which choice correctly fixes the modifier error? \"Nearly finished with dinner, the smoke alarm suddenly went off.\"", options: ["No change", "Nearly finished with dinner, we were startled when the smoke alarm suddenly went off.", "The smoke alarm, nearly finished with dinner, suddenly went off.", "Nearly finished, dinner and the smoke alarm went off."], answer: 1, explanation: "The introductory phrase should modify a person, not the smoke alarm, so the subject must be changed to 'we.'" },
  { question: "Which choice best maintains parallel structure? \"The manager's responsibilities include hiring staff, scheduling shifts, and to manage inventory.\"", options: ["No change", "managing inventory", "the management of inventory", "inventory management"], answer: 1, explanation: "The list should use the same grammatical form throughout: 'hiring,' 'scheduling,' and 'managing' are all gerunds." },
  { question: "Which choice best maintains parallel structure? \"She enjoys hiking, painting, and to read on weekends.\"", options: ["No change", "reading", "the reading of books", "she reads"], answer: 1, explanation: "To match 'hiking' and 'painting,' the final item in the list should also be a gerund: 'reading.'" },
  { question: "Which choice best maintains parallel structure? \"The report was thorough, well-organized, and it persuaded the board.\"", options: ["No change", "persuasive", "it was persuasive", "persuading everyone"], answer: 1, explanation: "The list of adjectives describing the report ('thorough, well-organized') should continue with another adjective: 'persuasive.'" },
  { question: "Which choice best maintains parallel structure? \"The coach told the players to warm up, to stretch, and running drills.\"", options: ["No change", "to run drills", "running some drills", "they should run drills"], answer: 1, explanation: "The infinitive form used in 'to warm up' and 'to stretch' should continue: 'to run drills.'" },
  { question: "Which choice best maintains parallel structure? \"Good leaders listen carefully, communicate clearly, and they are able to adapt quickly.\"", options: ["No change", "adapt quickly", "adapting quickly is important", "being able to adapt quickly"], answer: 1, explanation: "The list of present-tense verbs ('listen,' 'communicate') should continue in the same form: 'adapt quickly.'" },
  { passage: "The author includes a detailed description of the abandoned factory's rusted machinery and broken windows before introducing the workers who once operated it.", question: "Why does the author most likely include this description before introducing the workers?", options: ["To emphasize how advanced the factory's technology once was", "To establish a sense of decay and loss that contrasts with the factory's past productivity", "To criticize the workers for abandoning the factory", "To provide technical specifications of the machinery"], answer: 1, explanation: "Describing rust and broken windows before the workers sets a tone of decline, which is meant to contrast with the factory's earlier, productive era." },
  { passage: "In her essay, the author opens with a personal anecdote about losing her grandmother's recipe book before shifting to a broader discussion of how families preserve cultural traditions.", question: "What is the most likely purpose of opening with a personal anecdote?", options: ["To criticize modern families for not cooking traditional meals", "To provide a relatable, concrete entry point into a broader, more abstract topic", "To prove that recipe books are more reliable than oral traditions", "To argue that the author's family is unique"], answer: 1, explanation: "Personal anecdotes are commonly used to ground abstract topics in something relatable before broadening the discussion, which matches the essay's structure here." },
  { passage: "The scientist begins her article by listing several failed experiments before explaining the breakthrough that finally worked.", question: "What is the most likely rhetorical purpose of listing the failed experiments first?", options: ["To discourage readers from pursuing similar research", "To highlight the difficulty of the problem and make the eventual breakthrough more impactful", "To prove that the scientist's methods were flawed", "To provide a complete history of the field"], answer: 1, explanation: "Listing failures before the success is a common rhetorical strategy to emphasize the difficulty of the problem, making the breakthrough feel more significant." },
  { passage: "The historian pauses in the middle of her narrative about the battle to explain the economic conditions that led to the war.", question: "What is the most likely purpose of this pause in the narrative?", options: ["To provide context that helps readers understand the underlying causes of the battle", "To distract readers from the main story", "To argue that economics is more important than military strategy", "To criticize the historians who came before her"], answer: 0, explanation: "Pausing a narrative to explain background causes is a common technique to give readers context needed to understand the events that follow." },
  { passage: "The essayist ends his piece with a question rather than a firm conclusion, asking readers to consider what they would have done in the same situation.", question: "What is the most likely effect of ending with a question?", options: ["It signals that the essayist has no opinion on the topic.", "It invites readers to actively reflect on the issue rather than passively accept a conclusion.", "It suggests the essay is incomplete.", "It proves the essayist's argument is weak."], answer: 1, explanation: "Ending with a direct question to the reader is a technique used to prompt active reflection rather than simply delivering a closed conclusion." },
  { passage: "[1] The city built its first public library in 1889. [2] It was funded largely by a wealthy industrialist. [3] Within a decade, three more branches opened across the growing city. [4] The original building still stands today as a historic landmark.", question: "Which sequence of sentences most logically presents the information in chronological order?", options: ["1, 2, 3, 4", "2, 1, 3, 4", "1, 3, 2, 4", "4, 1, 2, 3"], answer: 0, explanation: "The sentences already progress logically: the library's founding (1), its funding (2), its expansion (3), and its present status (4)." },
  { passage: "[1] First, the researchers collected water samples from twelve different lakes. [2] They filtered each sample to isolate microplastic particles. [3] Finally, they compared particle counts across lakes with different levels of nearby development. [4] Next, they measured the size and type of each particle under a microscope.", question: "Which revision most logically orders the steps of the process?", options: ["No change", "1, 4, 2, 3", "1, 2, 4, 3", "4, 1, 2, 3"], answer: 2, explanation: "The logical order is: collect samples (1), filter to isolate particles (2), measure them (4), then compare results (3) — matching the sequence 1, 2, 4, 3." },
  { passage: "The paragraph currently reads: \"The bakery opens at 6 a.m. Its sourdough sells out by 8 a.m. most mornings. The owner has considered baking a second batch.\" Which sentence, if added at the end, most logically completes the paragraph?", question: "Which choice most logically completes the paragraph?", options: ["The bakery also sells pastries and coffee.", "So far, though, she has decided the single batch keeps the bread's quality consistent.", "The bakery is located downtown.", "Sourdough requires a long fermentation process."], answer: 1, explanation: "The paragraph builds toward the owner's consideration of a second batch, so a sentence explaining her decision on that specific point completes it most logically." },
  { question: "Which choice most effectively combines the two sentences while maintaining the same meaning? \"The bridge was built in 1932. It has undergone three major renovations since then.\"", options: ["The bridge was built in 1932, and it has undergone three major renovations since then.", "The bridge, built in 1932, has undergone three major renovations since then.", "The bridge was built in 1932 having undergone three major renovations since then.", "Built in 1932 the bridge has, undergone three major renovations since then."], answer: 1, explanation: "This choice concisely combines both ideas using an appositive phrase, avoiding redundancy while preserving the original meaning." },
  { question: "Which choice most effectively combines the two sentences? \"The novel was praised by critics. It was largely ignored by readers.\"", options: ["The novel was praised by critics, but it was largely ignored by readers.", "The novel was praised by critics it was largely ignored by readers.", "The novel, praised by critics, and largely ignored by readers.", "Praised by critics the novel was largely, ignored by readers."], answer: 0, explanation: "The two ideas contrast with each other, so joining them with a comma and the coordinating conjunction 'but' correctly signals that contrast." },
  { question: "Which revision most improves the conciseness of the sentence? \"Due to the fact that the weather was extremely cold, the game was postponed.\"", options: ["No change", "Because the weather was extremely cold, the game was postponed.", "Due to the fact of extremely cold weather, the game was postponed.", "Owing to the fact that it was cold weather, the game was postponed."], answer: 1, explanation: "'Due to the fact that' is a wordy phrase; 'because' expresses the same meaning far more concisely." },
  { question: "Which revision most improves the conciseness of the sentence? \"At this point in time, the committee has not yet reached a final decision.\"", options: ["No change", "Currently, the committee has not yet reached a final decision.", "At this point in time currently, the committee has not reached a decision.", "As of this current point in time, the committee has not decided."], answer: 1, explanation: "'At this point in time' is redundant wordiness for 'currently,' which conveys the same meaning more concisely." },
  { question: "Which revision most improves the conciseness of the sentence? \"The reason why the experiment failed was because the samples were contaminated.\"", options: ["No change", "The experiment failed because the samples were contaminated.", "The reason the experiment failed was due to the fact the samples were contaminated.", "Because the samples were contaminated is the reason why the experiment failed."], answer: 1, explanation: "'The reason why...was because' is redundant; stating the cause directly is more concise and grammatically cleaner." },
  { question: "Which revision most improves the conciseness of the sentence? \"In spite of the fact that ticket prices increased, attendance remained high.\"", options: ["No change", "Although ticket prices increased, attendance remained high.", "In spite of the fact of increased ticket prices, attendance remained high.", "Despite the fact that, ticket prices increased, attendance remained high."], answer: 1, explanation: "'In spite of the fact that' can be replaced with the single word 'although' without losing any meaning." },
  { question: "Which revision most improves the conciseness of the sentence? \"The new policy, which was implemented by the school, in an effort to reduce the amount of food waste, has been effective.\"", options: ["No change", "The new policy, implemented to reduce food waste, has been effective.", "The new policy, which was put in place by the school in an effort to try to reduce food waste amounts, has been effective.", "The policy, implemented by the school, for the purpose of reducing the amount of food that is wasted, has worked."], answer: 1, explanation: "This choice removes unnecessary words ('which was,' 'in an effort to,' 'the amount of') while preserving the sentence's full meaning." },
  { passage: "Study A found that participants who exercised in the morning reported higher energy levels throughout the day. Study B, using a larger and more diverse sample, found no significant difference in energy levels based on exercise timing.", question: "Which choice best describes the logical relationship between the findings of Study A and Study B?", options: ["Study B confirms Study A's findings using a larger sample.", "Study B's results complicate or contradict the conclusion suggested by Study A.", "Study A and Study B measured completely unrelated variables.", "Study B was conducted before Study A."], answer: 1, explanation: "Study B, with a larger and more diverse sample, found no significant effect, which contradicts or complicates the effect Study A found." },
  { passage: "The theory predicted that the material would become more conductive at lower temperatures. Subsequent experiments confirmed this prediction across a wide range of test conditions.", question: "Which choice best describes the logical relationship between the theory and the experiments?", options: ["The experiments disproved the theory's central prediction.", "The experiments were unrelated to the theory being tested.", "The experimental results support and are consistent with the theory's prediction.", "The theory was developed after the experiments were conducted."], answer: 2, explanation: "The passage states the experiments 'confirmed' the prediction, meaning the results are consistent with and support the theory." },
  { passage: "Critics initially dismissed the artist's work as derivative. Decades later, art historians reassessed the same paintings as pioneering examples of a new movement.", question: "Which choice best describes how the historians' view relates to the critics' original view?", options: ["The historians' view is identical to the critics' original assessment.", "The historians' later assessment directly reverses the critics' original judgment.", "The historians ignored the paintings entirely.", "The critics and historians agreed the paintings were unremarkable."], answer: 1, explanation: "The critics called the work derivative, while historians later called it pioneering — a direct reversal of the original judgment." },
  { passage: "Paragraph 1 introduces a common belief about a topic. Paragraph 2 presents evidence that challenges this belief. Paragraph 3 offers a revised explanation that accounts for the new evidence.", question: "Which choice best describes the overall structure of the text?", options: ["A belief is introduced, challenged with evidence, and then revised in light of that evidence.", "A series of unrelated anecdotes are presented in chronological order.", "A single argument is repeated three times with increasing intensity.", "Three competing theories are presented with no resolution."], answer: 0, explanation: "This structure — belief, challenge, revision — matches exactly what the passage describes across its three paragraphs." },
  { passage: "The article begins by describing a specific patient's experience with a rare disease, then broadens to discuss the disease's prevalence, and concludes with an overview of current research into treatments.", question: "Which choice best describes the overall structure of the text?", options: ["It moves from a specific case to broader context to future outlook.", "It presents statistics first, followed by a single case study.", "It argues against current medical research.", "It compares two different rare diseases."], answer: 0, explanation: "The passage moves from one patient's specific story, to general prevalence, to research outlook — a specific-to-general-to-future structure." },
  { passage: "A study found that students who took brief study breaks every 25 minutes scored higher on retention tests than students who studied continuously for 90 minutes without breaks.", question: "Which finding, if true, would most directly support the study's conclusion?", options: ["Students who took breaks reported feeling more tired by the end of the session.", "A follow-up study found that break-takers recalled 15% more material one week later.", "The continuous-study group finished their study session faster.", "Both groups reported enjoying the study session equally.", ], answer: 1, explanation: "Since the original claim is about better retention with breaks, a follow-up showing better long-term recall for break-takers most directly supports that conclusion." },
  { passage: "A nutritionist claims that eating breakfast is essential for maintaining a healthy metabolism throughout the day.", question: "Which piece of evidence would most directly weaken the nutritionist's claim?", options: ["A study showing no significant metabolic difference between breakfast-eaters and those who skip breakfast.", "A survey showing most people prefer eating breakfast.", "A study on the nutritional content of common breakfast foods.", "An article about the history of breakfast in different cultures."], answer: 0, explanation: "A study directly showing no metabolic difference between the two groups would undercut the specific claim that breakfast is essential for metabolism." },
  { passage: "A city official argues that building a new highway will reduce traffic congestion by giving drivers an alternative route.", question: "Which finding would most directly undermine the official's argument?", options: ["A survey showing most residents support the new highway.", "Data from a similar city showing that a new highway led to increased overall traffic due to induced demand.", "A report on the estimated construction cost of the highway.", "An analysis of the highway's environmental impact on air quality."], answer: 1, explanation: "Evidence of 'induced demand' — where a new highway leads to more overall traffic rather than less — directly contradicts the official's congestion-reduction argument." },
  { passage: "A teacher believes that allowing students to choose their own reading material increases overall reading engagement.", question: "Which piece of evidence would most directly support the teacher's belief?", options: ["A classroom survey showing students spend more time reading when allowed to choose their own books.", "A report on the total number of books in the school library.", "A study on the reading levels of students in different grades.", "An analysis of which genres are most popular among adults."], answer: 0, explanation: "Evidence directly linking student choice to increased reading time most directly supports the specific claim about engagement." },
  { question: "Which choice correctly completes the sentence? \"One of the biggest challenges facing the team ______ a lack of funding.\"", options: ["are", "is", "were", "have been"], answer: 1, explanation: "The subject is the singular 'one,' not the plural 'challenges,' so the singular verb 'is' is correct." },
  { question: "Which choice correctly completes the sentence? \"Either the manager or the employees ______ responsible for locking up at night.\"", options: ["is", "are", "was", "has been"], answer: 1, explanation: "With 'either...or,' the verb agrees with the nearer subject, the plural 'employees,' so 'are' is correct." },
  { question: "Which choice correctly completes the sentence? \"The students, along with their teacher, ______ preparing for the science fair.\"", options: ["is", "are", "was", "has been"], answer: 1, explanation: "The subject is the plural 'students'; the phrase 'along with their teacher' doesn't change the verb, so 'are' is correct." },
  { question: "Which choice correctly fixes the pronoun error? \"When a customer calls, make sure you get their order number before transferring the call.\" (Formal SAT-style revision)", options: ["No change", "make sure you get the customer's order number", "make sure you get his order number", "make sure you get theirselves order number"], answer: 1, explanation: "Replacing the vague pronoun with 'the customer's' removes the singular/plural mismatch and any ambiguity about who 'their' refers to." },
  { question: "Which choice correctly fixes the pronoun error? \"If a student forgets their homework, they should email the teacher immediately.\" (Formal SAT-style revision)", options: ["No change", "If a student forgets his or her homework, he or she should email the teacher immediately.", "If a student forgets there homework, they're should email the teacher immediately.", "If students forgets their homework, they should email the teacher immediately."], answer: 1, explanation: "In formal usage, the singular subject 'a student' requires singular pronouns 'his or her' and 'he or she' rather than the plural 'their' and 'they.'" },
  { question: "Which choice correctly completes the sentence? \"The two companies signed a contract that outlined ______ respective responsibilities.\"", options: ["it's", "its", "their", "there"], answer: 2, explanation: "'The two companies' is plural, so the plural possessive pronoun 'their' correctly agrees." },
  { question: "Which choice correctly completes the sentence? \"The award went to the scientist ______ research reshaped the field of genetics.\"", options: ["who's", "whose", "who", "which"], answer: 1, explanation: "The possessive pronoun 'whose' correctly shows that the research belongs to the scientist." },
  { question: "Which choice correctly completes the sentence? \"By the time the movie started, we ______ already eaten all our popcorn.\"", options: ["have", "has", "had", "will have"], answer: 2, explanation: "The past perfect 'had eaten' correctly shows an action completed before another past event (the movie starting)." },
  { question: "Which choice correctly completes the sentence? \"Right now, the technicians ______ the server for the software update.\"", options: ["prepare", "prepared", "are preparing", "will have prepared"], answer: 2, explanation: "The phrase 'Right now' signals an action in progress, requiring the present progressive 'are preparing.'" },
  { question: "Which choice correctly completes the sentence? \"By the time she turns thirty, she ______ to over forty countries.\"", options: ["travels", "traveled", "will have traveled", "is traveling"], answer: 2, explanation: "The future perfect 'will have traveled' correctly describes an action that will be completed before a specific future point." },
  { question: "Which choice correctly fixes the modifier error? \"Exhausted from the long flight, the hotel bed looked especially inviting to Priya.\"", options: ["No change", "Exhausted from the long flight, Priya found the hotel bed especially inviting.", "The hotel bed, exhausted from the long flight, looked especially inviting to Priya.", "Exhausted from the long flight the bed of the hotel looked, especially inviting to Priya."], answer: 1, explanation: "The modifier 'Exhausted from the long flight' should describe Priya, not the bed, so Priya must be the subject following the introductory phrase." },
  { question: "Which choice best maintains parallel structure? \"The workshop will teach participants to write clearly, to edit efficiently, and revising thoroughly.\"", options: ["No change", "to revise thoroughly", "revision that is thorough", "how they should revise thoroughly"], answer: 1, explanation: "To match the infinitives 'to write' and 'to edit,' the final item should also be an infinitive: 'to revise thoroughly.'" },
  { question: "Which revision most improves the conciseness of the sentence? \"It is important to note that the results of the survey indicate that most respondents are, in fact, satisfied.\"", options: ["No change", "The survey indicates most respondents are satisfied.", "It is important to note that, in fact, the survey results indicate satisfaction among respondents.", "Notably, it should be noted that survey results indicate respondent satisfaction."], answer: 1, explanation: "This choice removes filler phrases like 'It is important to note' and 'in fact' while preserving the core meaning concisely." },
  { passage: "The author dedicates an entire paragraph to describing the silence of the empty stadium before shifting to a flashback of its roaring crowds on opening day.", question: "Why does the author most likely include the description of silence before the flashback?", options: ["To criticize the stadium's current state of disrepair", "To create a contrast that heightens the impact of the memory of the crowded stadium", "To provide architectural details about the stadium", "To argue that the stadium should be demolished"], answer: 1, explanation: "Establishing quiet emptiness first sets up a contrast that makes the subsequent memory of a lively crowd feel more vivid and emotionally resonant." },
  { passage: "[1] The company launched its first product in 2005. [2] Sales were modest for the first three years. [3] A viral marketing campaign in 2009 caused sales to triple almost overnight. [4] The company has maintained steady growth ever since.", question: "Which choice best identifies the sentence that explains a turning point in the passage?", options: ["Sentence 1", "Sentence 2", "Sentence 3", "Sentence 4"], answer: 2, explanation: "Sentence 3 describes the viral campaign that caused sales to triple, marking the clear turning point between the modest early years and later steady growth." },
  { passage: "A city council debates whether a proposed park would benefit the community. Supporters cite increased green space; opponents cite the cost of maintenance.", question: "Which choice best describes the overall structure of the passage?", options: ["It presents both sides of a debate without resolving it.", "It argues exclusively in favor of the park.", "It provides a historical account of the park's construction.", "It compares two different parks in different cities."], answer: 0, explanation: "The passage lays out both the supporters' and opponents' points without indicating which side is correct, presenting a balanced, unresolved debate." }
];


/* ---------------- IGCSE ---------------- */

const IGCSE_MATH_QUESTIONS = [
  { question: "Write 4,500,000 in standard form.", options: ["4.5 × 10⁶", "45 × 10⁵", "4.5 × 10⁵", "0.45 × 10⁷"], answer: 0, explanation: "4,500,000 = 4.5 × 1,000,000 = 4.5 × 10⁶." },
  { question: "Find the simple interest earned on $2000 at 5% per annum for 3 years.", options: ["$200", "$250", "$300", "$350"], answer: 2, explanation: "Simple interest = PRT/100 = (2000 × 5 × 3)/100 = $300." },
  { question: "$1000 is invested at 10% per annum compound interest for 2 years. Find the total amount.", options: ["$1180", "$1200", "$1210", "$1221"], answer: 2, explanation: "Amount = 1000 × (1.10)² = 1000 × 1.21 = $1210." },
  { question: "Share $360 in the ratio 2:3:4. What is the largest share?", options: ["$120", "$140", "$160", "$180"], answer: 2, explanation: "There are 9 total parts, so each part is $40. The largest share is 4 × $40 = $160." },
  { question: "y is directly proportional to x. When x = 4, y = 20. Find y when x = 7.", options: ["28", "30", "35", "40"], answer: 2, explanation: "y = kx, so k = 20/4 = 5. When x = 7, y = 5 × 7 = 35." },
  { question: "y is inversely proportional to x. When x = 3, y = 12. Find y when x = 6.", options: ["3", "6", "9", "12"], answer: 1, explanation: "y = k/x, so k = 3 × 12 = 36. When x = 6, y = 36/6 = 6." },
  { question: "The bearing of point B from point A is 070°. What is the bearing of A from B?", options: ["070°", "110°", "250°", "290°"], answer: 2, explanation: "The back bearing is found by adding 180° (since 070° + 180° = 250° is less than 360°)." },
  { question: "Two similar triangles have corresponding sides in the ratio 2:5. If the area of the smaller triangle is 8 cm², find the area of the larger triangle.", options: ["20 cm²", "40 cm²", "50 cm²", "100 cm²"], answer: 2, explanation: "The area ratio is (5/2)² = 25/4. Larger area = 8 × 25/4 = 50 cm²." },
  { question: "Find the volume of a cone with radius 6 cm and height 10 cm. (Use π ≈ 3.14)", options: ["226.1 cm³", "376.8 cm³", "452.2 cm³", "1130.4 cm³"], answer: 1, explanation: "V = (1/3)πr²h = (1/3)(3.14)(36)(10) ≈ 376.8 cm³." },
  { question: "If A = {1,2,3,4} and B = {3,4,5,6}, find A ∩ B.", options: ["{1, 2}", "{3, 4}", "{5, 6}", "{1, 2, 3, 4, 5, 6}"], answer: 1, explanation: "A ∩ B contains only the elements in both sets: 3 and 4." },
  { question: "If A = {1,2,3,4} and B = {3,4,5,6}, find A ∪ B.", options: ["{1, 2}", "{3, 4}", "{5, 6}", "{1, 2, 3, 4, 5, 6}"], answer: 3, explanation: "A ∪ B contains every element that appears in either set." },
  { question: "A bag has 3 red and 2 blue balls. Two balls are drawn without replacement. Find the probability both are red.", options: ["1/5", "3/10", "2/5", "3/5"], answer: 1, explanation: "P(both red) = (3/5) × (2/4) = 6/20 = 3/10." },
  { question: "Simplify: (2 × 10³) × (3 × 10⁴).", options: ["6 × 10⁷", "6 × 10¹²", "5 × 10⁷", "6 × 10⁻¹"], answer: 0, explanation: "Multiply the coefficients (2 × 3 = 6) and add the powers of ten (3 + 4 = 7): 6 × 10⁷." },
  { question: "Solve: 3(x - 2) = 2x + 4.", options: ["8", "9", "10", "11"], answer: 2, explanation: "3x - 6 = 2x + 4. Subtract 2x: x - 6 = 4. Add 6: x = 10." },
  { question: "Factorise: x² - 49.", options: ["(x - 7)(x + 7)", "(x - 7)²", "(x + 7)²", "(x - 49)(x + 1)"], answer: 0, explanation: "This is a difference of two squares: x² - 49 = (x - 7)(x + 7)." },
  { question: "Solve simultaneously: 2x + y = 11 and x - y = 1. Find x.", options: ["3", "4", "5", "6"], answer: 1, explanation: "Adding both equations eliminates y: 3x = 12, so x = 4." },
  { question: "A television is reduced in price from $500 to $400. Find the percentage decrease.", options: ["15%", "20%", "25%", "30%"], answer: 1, explanation: "The decrease is $100. (100/500) × 100 = 20%." },
  { question: "A car travels 150 km in 2.5 hours. Find its average speed.", options: ["50 km/h", "55 km/h", "60 km/h", "65 km/h"], answer: 2, explanation: "Speed = distance/time = 150/2.5 = 60 km/h." },
  { question: "Vector a = (3, 4). Find the magnitude of a.", options: ["3", "4", "5", "7"], answer: 2, explanation: "|a| = √(3² + 4²) = √25 = 5." },
  { question: "The point (2, 3) is reflected in the x-axis. Find the coordinates of the image.", options: ["(2, -3)", "(-2, 3)", "(-2, -3)", "(3, 2)"], answer: 0, explanation: "Reflecting in the x-axis keeps the x-coordinate the same and negates the y-coordinate." },
  { question: "Given matrix A = [[1,2],[3,4]], find its determinant.", options: ["-2", "2", "10", "14"], answer: 0, explanation: "det(A) = (1×4) - (2×3) = 4 - 6 = -2." },
  { question: "Write 0.00035 in standard form.", options: ["3.5 × 10⁻⁴", "3.5 × 10⁻³", "35 × 10⁻⁵", "0.35 × 10⁻³"], answer: 0, explanation: "0.00035 = 3.5 × 10⁻⁴, since the decimal moves 4 places to reach 3.5." },
  { question: "Find the sum of the interior angles of a pentagon.", options: ["360°", "540°", "720°", "900°"], answer: 1, explanation: "Interior angle sum = (n - 2) × 180° = (5-2) × 180° = 540°." },
  { question: "A chord subtends an angle of 80° at the centre of a circle. Find the angle subtended at the circumference by the same chord (on the major arc).", options: ["40°", "80°", "100°", "160°"], answer: 0, explanation: "The angle at the centre is twice the angle at the circumference subtended by the same arc, so the circumference angle is 80°/2 = 40°." },
  { question: "Find the range of the data set: 12, 15, 9, 22, 18.", options: ["9", "10", "13", "22"], answer: 2, explanation: "Range = highest value - lowest value = 22 - 9 = 13." },
  { question: "Solve: 7x + 2 = 4x + 17.", options: ["3", "4", "5", "6"], answer: 2, explanation: "Subtract 4x: 3x + 2 = 17. Subtract 2: 3x = 15, so x = 5." },
  { question: "Simplify: 5(2x - 3) - 3(x + 4).", options: ["7x - 27", "7x - 3", "7x + 27", "13x - 27"], answer: 0, explanation: "Expand: 10x - 15 - 3x - 12 = 7x - 27." },
  { question: "Solve: (x + 3)/2 = 5.", options: ["5", "6", "7", "8"], answer: 2, explanation: "Multiply both sides by 2: x + 3 = 10, so x = 7." },
  { question: "A number x is tripled and then 4 is subtracted to give 20. Find x.", options: ["6", "7", "8", "9"], answer: 2, explanation: "3x - 4 = 20, so 3x = 24, giving x = 8." },
  { question: "Expand: (x + 4)(x - 4).", options: ["x² - 16", "x² + 16", "x² - 8x - 16", "x² + 8x - 16"], answer: 0, explanation: "This is a difference of two squares: (x+4)(x-4) = x² - 16." },
  { question: "Factorise fully: 2x² + 8x.", options: ["2x(x + 4)", "x(2x + 8)", "2(x² + 4x)", "2x(x + 8)"], answer: 0, explanation: "The highest common factor is 2x, giving 2x(x + 4)." },
  { question: "Find the sum of the two solutions of x² - 7x + 12 = 0.", options: ["5", "6", "7", "8"], answer: 2, explanation: "The equation factors as (x-3)(x-4)=0, giving roots 3 and 4, which sum to 7." },
  { question: "A sequence has nth term 2n² - 1. Find the 4th term.", options: ["27", "29", "31", "33"], answer: 2, explanation: "Substituting n=4: 2(16) - 1 = 31." },
  { question: "The sequence 2, 5, 10, 17, 26, ... has nth term n² + 1. Find the 6th term.", options: ["35", "36", "37", "38"], answer: 2, explanation: "Substituting n=6: 6² + 1 = 37." },
  { question: "Convert 5/6 to a decimal, to 3 decimal places.", options: ["0.816", "0.833", "0.850", "0.866"], answer: 1, explanation: "5 ÷ 6 = 0.8333..., which rounds to 0.833." },
  { question: "A car's value depreciates by 12% per year. If it is worth $18,000 now, what will it be worth after 1 year, to the nearest dollar?", options: ["$15,200", "$15,600", "$15,840", "$16,000"], answer: 2, explanation: "18,000 × 0.88 = $15,840." },
  { question: "After a 10% increase, a price is $88. What was the original price?", options: ["$76", "$78", "$80", "$82"], answer: 2, explanation: "The original price × 1.1 = 88, so original = 88/1.1 = $80." },
  { question: "A number is decreased by 30% to give 63. Find the original number.", options: ["85", "88", "90", "93"], answer: 2, explanation: "x × 0.7 = 63, so x = 63/0.7 = 90." },
  { question: "Simplify: 3/4 + 5/6.", options: ["19/12", "8/10", "4/5", "3/2"], answer: 0, explanation: "Using a common denominator of 12: 9/12 + 10/12 = 19/12." },
  { question: "Solve: 2x/5 = 3/10.", options: ["0.5", "0.6", "0.75", "0.8"], answer: 2, explanation: "Cross-multiplying: 20x = 15, so x = 0.75." },
  { question: "A right-angled triangle has one angle of 90° and another of 35°. Find the third angle.", options: ["45°", "50°", "55°", "60°"], answer: 2, explanation: "Angles in a triangle sum to 180°: 180 - 90 - 35 = 55°." },
  { question: "In a right triangle, the side opposite angle θ is 5 and the hypotenuse is 13. Find sin θ.", options: ["5/13", "12/13", "5/12", "13/5"], answer: 0, explanation: "sin θ = opposite/hypotenuse = 5/13." },
  { question: "In a right triangle, the adjacent side to angle θ is 8 and the hypotenuse is 17. Find cos θ.", options: ["8/17", "15/17", "8/15", "17/8"], answer: 0, explanation: "cos θ = adjacent/hypotenuse = 8/17." },
  { question: "In a right triangle, the opposite side to angle θ is 9 and the adjacent side is 12. Find tan θ.", options: ["3/4", "4/3", "9/15", "12/15"], answer: 0, explanation: "tan θ = opposite/adjacent = 9/12 = 3/4." },
  { question: "A ladder 10 m long leans against a wall, making an angle of 60° with the ground. How high up the wall does it reach, to 1 decimal place?", options: ["5.0 m", "7.1 m", "8.7 m", "9.4 m"], answer: 2, explanation: "Height = 10 × sin(60°) ≈ 10 × 0.866 = 8.7 m." },
  { question: "Find the length of the hypotenuse of a right triangle with legs 9 cm and 12 cm.", options: ["13 cm", "14 cm", "15 cm", "16 cm"], answer: 2, explanation: "√(9² + 12²) = √(81 + 144) = √225 = 15 cm." },
  { question: "A triangle has sides 5, 12, and 13. Is it right-angled?", options: ["Yes, it's right-angled", "No", "Cannot be determined", "Only if the angle is given"], answer: 0, explanation: "Since 5² + 12² = 25 + 144 = 169 = 13², the triangle satisfies the Pythagorean theorem and is right-angled." },
  { question: "Find the area of a circle with radius 7 cm. (Use π = 22/7)", options: ["144 cm²", "150 cm²", "154 cm²", "160 cm²"], answer: 2, explanation: "Area = πr² = (22/7)(49) = 154 cm²." },
  { question: "Find the perimeter of a semicircle with radius 7 cm. (Use π = 22/7)", options: ["30 cm", "33 cm", "36 cm", "39 cm"], answer: 2, explanation: "Perimeter = πr + 2r = 22 + 14 = 36 cm." },
  { question: "A cuboid has a volume of 240 cm³ and a base area of 40 cm². Find its height.", options: ["4 cm", "5 cm", "6 cm", "7 cm"], answer: 2, explanation: "Height = volume ÷ base area = 240/40 = 6 cm." },
  { question: "Find the surface area of a sphere with radius 3 cm, in terms of π. (SA = 4πr²)", options: ["12π cm²", "24π cm²", "36π cm²", "48π cm²"], answer: 2, explanation: "SA = 4π(3²) = 4π(9) = 36π cm²." },
  { question: "Find the volume of a sphere with radius 3 cm, in terms of π. (V = 4/3πr³)", options: ["27π cm³", "36π cm³", "48π cm³", "108π cm³"], answer: 1, explanation: "V = (4/3)π(3³) = (4/3)π(27) = 36π cm³." },
  { question: "Two similar cylinders have heights in the ratio 2:3. Find the ratio of their volumes.", options: ["4:9", "8:27", "2:3", "6:9"], answer: 1, explanation: "Volume ratio is the cube of the length ratio: 2³:3³ = 8:27." },
  { question: "A map has a scale of 1:25,000. Find the actual area, in km², of a region shown as 4 cm² on the map.", options: ["0.1 km²", "0.25 km²", "0.5 km²", "1 km²"], answer: 1, explanation: "1 cm on the map = 250 m actual, so 1 cm² = 0.0625 km². For 4 cm²: 4 × 0.0625 = 0.25 km²." },
  { question: "Solve simultaneously: 3x + 2y = 16 and x - y = 2. Find y.", options: ["1", "2", "3", "4"], answer: 1, explanation: "From the second equation, x = y+2. Substituting: 3(y+2) + 2y = 16 → 5y + 6 = 16 → y = 2." },
  { question: "A number, when doubled and then increased by 10%, gives 44. Find the number.", options: ["18", "19", "20", "22"], answer: 2, explanation: "2x × 1.1 = 44, so 2.2x = 44, giving x = 20." },
  { question: "Find x if 5ˣ = 125.", options: ["2", "3", "4", "5"], answer: 1, explanation: "125 = 5³, so x = 3." },
  { question: "Simplify: (x⁻²)(x⁵).", options: ["x³", "x⁻³", "x⁷", "x⁻⁷"], answer: 0, explanation: "Adding the exponents: -2 + 5 = 3, giving x³." },
  { question: "Evaluate: 4^(1/2) × 9^(1/2).", options: ["4", "6", "9", "13"], answer: 1, explanation: "√4 × √9 = 2 × 3 = 6." },
  { question: "Rationalise the denominator: 1/√3.", options: ["√3/3", "1/3", "3/√3", "√3"], answer: 0, explanation: "Multiplying numerator and denominator by √3 gives √3/3." },
  { question: "Find x if log₁₀(x) = 2.", options: ["10", "20", "100", "200"], answer: 2, explanation: "log₁₀(x) = 2 means x = 10² = 100." },
  { question: "Find the mean of this frequency table: value 2 (frequency 3), value 4 (frequency 5), value 6 (frequency 2).", options: ["3.5", "3.8", "4.0", "4.2"], answer: 1, explanation: "Mean = (2×3 + 4×5 + 6×2) / (3+5+2) = 38/10 = 3.8." },
  { question: "On a cumulative frequency diagram, what does the median correspond to?", options: ["The value at 50% of the cumulative frequency", "The highest value", "The lowest value", "The mode"], answer: 0, explanation: "The median is read off at the point corresponding to half of the total cumulative frequency." },
  { question: "Find the interquartile range if Q1 = 12 and Q3 = 28.", options: ["12", "14", "16", "18"], answer: 2, explanation: "IQR = Q3 - Q1 = 28 - 12 = 16." },
  { question: "A fair die is rolled twice. Find the probability that the two rolls total 7.", options: ["1/12", "1/9", "1/6", "1/4"], answer: 2, explanation: "There are 6 combinations that sum to 7 out of 36 total outcomes: 6/36 = 1/6." },
  { question: "A spinner has 4 equal sections: red, blue, green, yellow. It is spun twice. Find the probability of red both times.", options: ["1/16", "1/8", "1/4", "1/2"], answer: 0, explanation: "P(red) = 1/4 each spin. For two independent spins: (1/4)×(1/4) = 1/16." },
  { question: "Two mutually exclusive events A and B have P(A) = 0.3 and P(B) = 0.4. Find P(A or B).", options: ["0.12", "0.7", "0.1", "1.0"], answer: 1, explanation: "For mutually exclusive events, P(A or B) = P(A) + P(B) = 0.3 + 0.4 = 0.7." },
  { question: "Two independent events A and B have P(A) = 0.5 and P(B) = 0.6. Find P(A and B).", options: ["0.11", "0.3", "0.5", "1.1"], answer: 1, explanation: "For independent events, P(A and B) = P(A) × P(B) = 0.5 × 0.6 = 0.3." },
  { question: "Vector a = (5, -2) and b = (-3, 4). Find a - b.", options: ["(8, -6)", "(2, 2)", "(-8, 6)", "(8, 6)"], answer: 0, explanation: "Subtracting component-wise: (5-(-3), -2-4) = (8, -6)." },
  { question: "Find 3a for a = (2, -1).", options: ["(6, -3)", "(5, 2)", "(6, 3)", "(2, -3)"], answer: 0, explanation: "Multiplying each component by 3: (6, -3)." },
  { question: "A translation is given by the vector (4, -2). Find the image of the point (1, 5) after this translation.", options: ["(5, 3)", "(3, 7)", "(-3, 7)", "(5, 7)"], answer: 0, explanation: "Adding the vector: (1+4, 5-2) = (5, 3)." },
  { question: "A shape is enlarged by scale factor 3 from centre (0,0). Find the image of the point (2, 1).", options: ["(6, 3)", "(5, 4)", "(2, 3)", "(6, 1)"], answer: 0, explanation: "Each coordinate is multiplied by the scale factor: (2×3, 1×3) = (6, 3)." },
  { question: "A rotation of 90° clockwise about the origin maps the point (x, y) to which point?", options: ["(y, -x)", "(-y, x)", "(x, -y)", "(-x, -y)"], answer: 0, explanation: "A 90° clockwise rotation about the origin maps (x, y) to (y, -x)." },
  { question: "Find the equation of a line parallel to y = 4x - 1 that passes through (0, 3).", options: ["y = 4x + 3", "y = 4x - 3", "y = -4x + 3", "y = 4x + 1"], answer: 0, explanation: "Parallel lines share the same gradient, 4. With y-intercept 3: y = 4x + 3." },
  { question: "Find the point of intersection of the lines y = x + 2 and y = -x + 6.", options: ["(2, 4)", "(4, 2)", "(1, 3)", "(3, 1)"], answer: 0, explanation: "Setting equal: x + 2 = -x + 6 → 2x = 4 → x = 2, and y = 2 + 2 = 4." },
  { question: "A bag has 8 balls: 3 red and 5 blue. Two balls are drawn with replacement. Find the probability both are red.", options: ["3/32", "9/64", "3/16", "9/32"], answer: 1, explanation: "With replacement, P(red) = 3/8 each time: (3/8) × (3/8) = 9/64." },
  { question: "Solve: 3(x - 1) + 2(x + 2) = 21.", options: ["3", "4", "5", "6"], answer: 1, explanation: "Expand: 3x - 3 + 2x + 4 = 21 → 5x + 1 = 21 → 5x = 20 → x = 4." },
  { question: "The angles of a quadrilateral are x, x+10, x+20, and x+30. Find x.", options: ["65°", "70°", "75°", "80°"], answer: 2, explanation: "Angles of a quadrilateral sum to 360°: 4x + 60 = 360 → 4x = 300 → x = 75." },
  { question: "Find the size of one exterior angle of a regular 9-sided polygon (nonagon).", options: ["30°", "35°", "40°", "45°"], answer: 2, explanation: "Exterior angles of a regular polygon sum to 360°: 360/9 = 40°." },
  { question: "A cylinder has volume 500 cm³ and height 10 cm. Find its radius, to 1 decimal place.", options: ["3.5 cm", "3.7 cm", "4.0 cm", "4.5 cm"], answer: 2, explanation: "r² = V/(πh) = 500/(π×10) ≈ 15.9, so r ≈ 4.0 cm." },
  { question: "Simplify fully: (12x²y)/(4xy).", options: ["3x", "3xy", "3x²", "3y"], answer: 0, explanation: "Dividing coefficients (12/4=3) and simplifying variables (x²/x=x, y/y=1) gives 3x." },
  { question: "Solve: 2^(x+1) = 16.", options: ["2", "3", "4", "5"], answer: 1, explanation: "16 = 2⁴, so x+1 = 4, giving x = 3." },
  { question: "A geometric sequence has first term 2 and common ratio 3. Find the sum of the first 4 terms.", options: ["70", "74", "78", "80"], answer: 3, explanation: "The terms are 2, 6, 18, 54. Their sum is 2+6+18+54 = 80." },
  { question: "Find the value of y = 2⁰ + 3⁰ + 4⁰.", options: ["0", "1", "3", "9"], answer: 2, explanation: "Any nonzero number raised to the power 0 equals 1, so 1+1+1 = 3." },
  { question: "A jacket costs $85 after a 15% increase. What was the original price, to the nearest dollar?", options: ["$70", "$72", "$74", "$76"], answer: 2, explanation: "original × 1.15 = 85, so original = 85/1.15 ≈ $74." },
  { question: "Simplify: √8 × √2.", options: ["2", "4", "6", "8"], answer: 1, explanation: "√8 × √2 = √16 = 4." },
  { question: "Find x: x/3 + x/4 = 7.", options: ["10", "11", "12", "13"], answer: 2, explanation: "Multiplying through by 12: 4x + 3x = 84 → 7x = 84 → x = 12." },
  { question: "The ratio of eggs to cups of flour in a recipe is 2:5. If 10 cups of flour are used, how many eggs are needed?", options: ["3", "4", "5", "6"], answer: 1, explanation: "10 cups is 2 times the ratio unit of 5, so eggs = 2 × 2 = 4." },
  { question: "A cone has a base radius of 5 cm and a slant height of 13 cm. Find its vertical height.", options: ["10 cm", "11 cm", "12 cm", "13 cm"], answer: 2, explanation: "By Pythagoras: h = √(13² - 5²) = √(169-25) = √144 = 12 cm." },
  { question: "Find the curved surface area of a cone with radius 5 cm and slant height 13 cm, in terms of π. (CSA = πrl)", options: ["60π cm²", "65π cm²", "70π cm²", "75π cm²"], answer: 1, explanation: "CSA = π(5)(13) = 65π cm²." },
  { question: "In a class of 30 students, 18 study French, 12 study Spanish, and 5 study both. How many study neither?", options: ["3", "4", "5", "6"], answer: 2, explanation: "Studying at least one: 18+12-5=25. Neither: 30-25=5." },
  { question: "A number is chosen at random from 1 to 20. Find the probability it is a multiple of 3.", options: ["1/4", "3/10", "1/3", "2/5"], answer: 1, explanation: "The multiples of 3 from 1-20 are 3,6,9,12,15,18 — 6 numbers. P = 6/20 = 3/10." },
  { question: "Find x if the mean of 4, 7, x, 10, and 14 is 9.", options: ["8", "9", "10", "11"], answer: 2, explanation: "The sum must be 45. 4+7+10+14=35, so x=45-35=10." },
  { question: "A car's odometer reads 45,231 km. After a journey it reads 45,589 km. How far was traveled?", options: ["348 km", "352 km", "358 km", "362 km"], answer: 2, explanation: "45,589 - 45,231 = 358 km." },
  { question: "Find the value of (2x - 3)² when x = 4.", options: ["16", "20", "25", "30"], answer: 2, explanation: "2(4) - 3 = 5, and 5² = 25." },
  { question: "A shop increases all prices by 8%, then decreases the new prices by 8%. Is the final price the same as the original?", options: ["Yes, exactly the same", "No, slightly higher", "No, slightly lower", "Cannot be determined"], answer: 2, explanation: "The 8% decrease is applied to a larger amount than the original, so the final price ends up slightly below the original." },
  { question: "Solve: 4x² = 100.", options: ["x = 5 only", "x = ±5", "x = 25", "x = 10"], answer: 1, explanation: "x² = 25, so x = 5 or x = -5." },
  { question: "A rectangular field has length (x+5) m and width x m. If its area is 84 m², find x.", options: ["6", "7", "8", "9"], answer: 1, explanation: "x(x+5) = 84 → x² + 5x - 84 = 0 → (x+12)(x-7) = 0. Since x must be positive, x = 7." },
  { question: "Find the gradient of a line perpendicular to a line with gradient -2/3.", options: ["-3/2", "2/3", "3/2", "-2/3"], answer: 2, explanation: "The perpendicular gradient is the negative reciprocal of -2/3, which is 3/2." },
  { question: "A sequence is generated by the formula 3n + 2 for n = 1, 2, 3, .... Find the 20th term.", options: ["59", "60", "61", "62"], answer: 3, explanation: "Substituting n=20: 3(20) + 2 = 62." }
];

