  { question: "Choose the correctly capitalized sentence.", options: ["We traveled through Asia, Europe, and africa.", "We traveled through asia, europe, and Africa.", "We traveled through Asia, Europe, and Africa.", "we traveled through Asia, Europe, and Africa."], answer: 2, explanation: "Continents are proper nouns and must be capitalized, along with the first word of the sentence." },
  { question: "Choose the word that means \"to praise highly.\"", options: ["criticize", "extol", "dismiss", "ignore"], answer: 1, explanation: "'Extol' means to praise someone or something enthusiastically." },
  { question: "Choose the correct form: \"Either of the answers ______ acceptable.\"", options: ["is", "are", "were", "have been"], answer: 0, explanation: "'Either' is a singular subject, taking the singular verb 'is.'" },
  { question: "Identify the type of sentence: \"What an incredible performance that was!\"", options: ["Declarative", "Interrogative", "Imperative", "Exclamatory"], answer: 3, explanation: "This sentence expresses strong emotion and ends with an exclamation mark, making it exclamatory." },
  { question: "Choose the correct word: \"The team played ______ than expected.\"", options: ["good", "well", "best", "better"], answer: 3, explanation: "'Better' is the correct comparative adverb form, comparing performance against expectation." },
  { question: "Choose the word closest in meaning to \"futile.\"", options: ["useful", "pointless", "urgent", "successful"], answer: 1, explanation: "'Futile' means having no useful result, close in meaning to 'pointless.'" },
  { passage: "The recipe called for exact measurements, but the chef, relying on decades of experience, simply estimated the quantities by eye — and the dish turned out perfectly.", question: "What does this passage suggest about the chef?", options: ["The chef always follows recipes exactly", "The chef's experience allowed successful improvisation", "The dish was a failure", "The chef refused to cook without a recipe"], answer: 1, explanation: "Estimating quantities by eye and still succeeding shows the chef's experience enabled confident improvisation." },
  { question: "Choose the correct preposition: \"The cat jumped ______ the fence.\"", options: ["over", "in", "on", "at"], answer: 0, explanation: "'Over' correctly describes movement above and across the fence." },
  { question: "Choose the correctly spelled word.", options: ["occured", "occurred", "ocurred", "occureed"], answer: 1, explanation: "The correct spelling is 'occurred,' with double 'r.'" },
  { question: "Identify the figure of speech: \"I've told you a million times to clean your room.\"", options: ["Simile", "Metaphor", "Hyperbole", "Onomatopoeia"], answer: 2, explanation: "Saying 'a million times' is an obvious exaggeration, making this hyperbole." },
  { question: "Choose the correct verb form: \"If it rains tomorrow, the match ______ cancelled.\"", options: ["is", "will be", "was", "would be"], answer: 1, explanation: "This is a first conditional sentence, using 'will be' in the main clause to describe a likely future result." },
  { question: "Choose the word that means \"to state something with confidence.\"", options: ["doubt", "assert", "question", "hesitate"], answer: 1, explanation: "'Assert' means to state something confidently and firmly." },
  { question: "Identify the part of speech of \"however\" in \"The plan was risky; however, it succeeded.\"", options: ["Noun", "Conjunction/connective adverb", "Adjective", "Preposition"], answer: 1, explanation: "'However' connects two contrasting ideas, functioning as a connective (conjunctive) adverb." },
  { question: "Choose the correct form: \"Both of the answers ______ correct.\"", options: ["is", "are", "was", "has been"], answer: 1, explanation: "'Both' refers to two items, taking the plural verb 'are.'" },
  { passage: "Historians disagree about the exact causes of the empire's decline, but most point to a combination of economic strain, political instability, and external invasions.", question: "According to the passage, how do historians generally view the empire's decline?", options: ["As caused by a single clear factor", "As resulting from multiple combined factors", "As entirely accidental", "As caused only by invasions"], answer: 1, explanation: "The passage lists three combined factors — economic, political, and military — that historians generally point to." },
  { question: "Choose the correct word: \"She is the ______ candidate for the job.\"", options: ["ideally", "ideal", "idealize", "idealization"], answer: 1, explanation: "An adjective is needed to describe 'candidate,' making 'ideal' correct." },
  { question: "Choose the correctly punctuated sentence.", options: ["My brothers car is in the garage.", "My brother's car is in the garage.", "My brothers' car is in the garage.", "My brother's, car is in the garage."], answer: 1, explanation: "The apostrophe before the 's' shows singular possession by one brother." },
  { question: "Identify the figure of speech: \"The old machine groaned and creaked with every movement.\"", options: ["Simile", "Personification", "Metaphor", "Alliteration"], answer: 1, explanation: "Describing the machine as 'groaning' gives it human-like qualities, making this personification." },
  { question: "Choose the word closest in meaning to \"tedious.\"", options: ["exciting", "boring", "brief", "confusing"], answer: 1, explanation: "'Tedious' means tiresomely long or dull, close in meaning to 'boring.'" },
  { question: "Choose the correct form: \"Not only the manager but also the employees ______ invited.\"", options: ["was", "were", "is", "has been"], answer: 1, explanation: "With 'not only...but also,' the verb agrees with the nearer subject, the plural 'employees.'" },
  { passage: "The bridge's engineers built in a small amount of flexibility, allowing it to sway slightly in high winds rather than resist the force rigidly, which paradoxically makes it stronger overall.", question: "What does the passage suggest about the bridge's design?", options: ["Rigidity makes structures stronger in all cases", "Some flexibility can make a structure stronger, not weaker", "The bridge is poorly designed", "Wind has no effect on the bridge"], answer: 1, explanation: "The passage explicitly states that allowing slight flexibility, rather than rigid resistance, makes the bridge stronger — a paradox highlighted directly in the text." },
  { question: "Choose the correct preposition: \"He is responsible ______ managing the budget.\"", options: ["for", "of", "with", "at"], answer: 0, explanation: "'Responsible for' is the correct fixed preposition pairing." },
  { question: "Choose the word that means \"to combine into a single unit.\"", options: ["divide", "unify", "separate", "isolate"], answer: 1, explanation: "'Unify' means to bring together or combine into one." },
  { question: "Identify the type of sentence: \"Turn off the lights before you leave.\"", options: ["Declarative", "Interrogative", "Imperative", "Exclamatory"], answer: 2, explanation: "This sentence gives a command, making it imperative." },
  { question: "Choose the correct comparative form: \"This exam was ______ than the last one.\"", options: ["difficult", "more difficult", "most difficult", "difficultest"], answer: 1, explanation: "Multi-syllable adjectives like 'difficult' use 'more' to form the comparative, rather than an '-er' ending." },
  { question: "Choose the word closest in meaning to \"prudent.\"", options: ["reckless", "careful", "wasteful", "impulsive"], answer: 1, explanation: "'Prudent' means acting with careful thought for the future, close in meaning to 'careful.'" },
  { question: "Choose the correct word: \"He arrived ______ than everyone else.\"", options: ["early", "earlier", "earliest", "more early"], answer: 1, explanation: "The comparative 'earlier' is used to compare his arrival time against everyone else." },
  { question: "Identify the figure of speech: \"The thunder roared across the valley.\"", options: ["Simile", "Personification", "Onomatopoeia", "Hyperbole"], answer: 1, explanation: "Describing thunder as 'roaring,' an animal-like action, gives it human or animal qualities, making this personification." },
  { question: "Choose the correct preposition: \"She excels ______ mathematics.\"", options: ["at", "of", "for", "with"], answer: 0, explanation: "'Excel at' is the correct fixed preposition pairing." },
  { question: "Choose the word closest in meaning to \"resilient.\"", options: ["fragile", "tough", "timid", "careless"], answer: 1, explanation: "'Resilient' means able to recover quickly from difficulties, close in meaning to 'tough.'" },
  { question: "Choose the correct form: \"The information ______ presented clearly in the report.\"", options: ["was", "were", "have been", "are"], answer: 0, explanation: "'Information' is an uncountable noun and takes the singular verb 'was.'" },
  { question: "Identify the type of sentence: \"The train departs at 9 a.m.\"", options: ["Declarative", "Interrogative", "Imperative", "Exclamatory"], answer: 0, explanation: "This sentence simply states a fact, making it declarative." }
