const ALEVEL_MATH_QUESTIONS = [
  { question: "Differentiate y = 3x⁴ - 5x² + 7 with respect to x.", options: ["12x³ - 10x", "12x³ - 5x", "3x³ - 10x", "12x² - 10x"], answer: 0, explanation: "d/dx(3x⁴) = 12x³ and d/dx(-5x²) = -10x, so dy/dx = 12x³ - 10x." },
  { question: "Integrate ∫(4x³ - 2x) dx.", options: ["x⁴ - x² + C", "4x⁴ - 2x² + C", "x⁴ - 2x² + C", "12x² - 2 + C"], answer: 0, explanation: "∫4x³dx = x⁴ and ∫-2x dx = -x², giving x⁴ - x² + C." },
  { question: "Find dy/dx if y = sin(2x).", options: ["cos(2x)", "2cos(2x)", "-2cos(2x)", "2sin(2x)"], answer: 1, explanation: "Using the chain rule, the derivative of sin(2x) is 2cos(2x)." },
  { question: "Find dy/dx if y = e^(3x).", options: ["e^(3x)", "3e^(3x)", "3xe^(3x-1)", "e^(3x)/3"], answer: 1, explanation: "The derivative of e^(kx) is k·e^(kx), so the derivative here is 3e^(3x)." },
  { question: "Evaluate ∫₀² 3x² dx.", options: ["4", "6", "8", "12"], answer: 2, explanation: "∫3x²dx = x³, so [x³]₀² = 8 - 0 = 8." },
  { question: "Solve: log₂(x) = 5.", options: ["10", "16", "25", "32"], answer: 3, explanation: "log₂(x) = 5 means x = 2⁵ = 32." },
  { question: "Simplify: sin²θ + cos²θ.", options: ["0", "1", "2", "tan θ"], answer: 1, explanation: "This is the Pythagorean trigonometric identity, which always equals 1." },
  { question: "Find the derivative of y = ln(x).", options: ["x", "1/x", "ln(x)", "e^x"], answer: 1, explanation: "The derivative of the natural logarithm ln(x) is 1/x." },
  { question: "For what value of x does f(x) = x² - 6x + 5 have a minimum?", options: ["2", "3", "4", "5"], answer: 1, explanation: "The vertex of the parabola occurs at x = -b/2a = 6/2 = 3." },
  { question: "If a = (2, 3) and b = (4, -1), find a + b.", options: ["(6, 2)", "(2, 4)", "(-2, 4)", "(6, -2)"], answer: 0, explanation: "Adding corresponding components: (2+4, 3+(-1)) = (6, 2)." },
  { question: "Find |a| for a = (3, 4).", options: ["3", "4", "5", "7"], answer: 2, explanation: "|a| = √(3² + 4²) = √25 = 5." },
  { question: "Find the sum of the first 10 terms of the arithmetic series with a = 3, d = 4.", options: ["195", "200", "210", "220"], answer: 2, explanation: "Sₙ = n/2[2a + (n-1)d] = 5[6 + 36] = 5(42) = 210." },
  { question: "Find the sum to infinity of the geometric series with a = 8, r = 1/2.", options: ["8", "12", "16", "24"], answer: 2, explanation: "S∞ = a/(1-r) = 8/0.5 = 16." },
  { question: "Differentiate y = (2x + 1)³ using the chain rule.", options: ["3(2x+1)²", "6(2x+1)²", "(2x+1)²", "6(2x+1)"], answer: 1, explanation: "dy/dx = 3(2x+1)² × 2 = 6(2x+1)²." },
  { question: "Find the equation of the tangent to y = x² at the point (2, 4).", options: ["y = 4x - 4", "y = 2x", "y = 4x + 4", "y = 2x - 4"], answer: 0, explanation: "dy/dx = 2x, giving gradient 4 at x=2. Using point-slope form: y - 4 = 4(x-2), so y = 4x - 4." },
  { question: "Solve the equation 2sinθ = 1 for 0° ≤ θ ≤ 360°.", options: ["30° and 150°", "30° and 210°", "60° and 120°", "45° and 135°"], answer: 0, explanation: "sinθ = 0.5 gives θ = 30° or θ = 180° - 30° = 150°." },
  { question: "Find the discriminant of 2x² - 4x + 5 = 0 and state the nature of its roots.", options: ["No real roots", "Two equal real roots", "Two distinct real roots", "Cannot be determined"], answer: 0, explanation: "Discriminant = b² - 4ac = 16 - 40 = -24, which is negative, so there are no real roots." },
  { question: "Find the radius of the circle x² + y² - 6x + 4y - 12 = 0.", options: ["3", "4", "5", "6"], answer: 2, explanation: "Completing the square gives (x-3)² + (y+2)² = 12 + 9 + 4 = 25, so the radius is 5." },
  { question: "Differentiate y = x²sin(x) using the product rule.", options: ["2x sin(x) + x² cos(x)", "2x cos(x) + x² sin(x)", "2x sin(x) - x² cos(x)", "x² cos(x)"], answer: 0, explanation: "Product rule: dy/dx = (2x)(sin x) + (x²)(cos x)." },
  { question: "Find the derivative of y = cos(x)/x using the quotient rule.", options: ["(-x sin x - cos x)/x²", "(x sin x - cos x)/x²", "(-x sin x + cos x)/x²", "(x cos x - sin x)/x²"], answer: 0, explanation: "Quotient rule: dy/dx = [(-sin x)(x) - (cos x)(1)]/x² = (-x sin x - cos x)/x²." },
  { question: "Find the coefficient of x³ in the binomial expansion of (1+x)⁵.", options: ["5", "10", "15", "20"], answer: 1, explanation: "The coefficient is given by 5C3 = 10." },
  { question: "Find the modulus of the complex number z = 3 + 4i.", options: ["3", "4", "5", "7"], answer: 2, explanation: "|z| = √(3² + 4²) = √25 = 5." },
  { question: "Solve for x: eˣ = 20, giving your answer to 2 decimal places.", options: ["2.30", "3.00", "4.00", "20.00"], answer: 1, explanation: "x = ln(20) ≈ 2.996, which rounds to 3.00." },
  { question: "Find the equation of a line perpendicular to y = 2x + 3, passing through (0, -1).", options: ["y = -½x - 1", "y = 2x - 1", "y = -2x - 1", "y = ½x - 1"], answer: 0, explanation: "The perpendicular gradient is the negative reciprocal of 2, which is -½. Using y-intercept -1: y = -½x - 1." },
  { question: "A curve has dy/dx = 6x - 4, and y = 5 when x = 1. Find the value of y when x = 2.", options: ["8", "9", "10", "12"], answer: 2, explanation: "Integrating gives y = 3x² - 4x + C. At x=1, y=5: 5 = 3 - 4 + C, so C = 6. At x=2: y = 12 - 8 + 6 = 10." },
  { question: "Differentiate y = 5x⁶ - 3x⁴ + 2x.", options: ["30x⁵ - 12x³ + 2", "30x⁵ - 12x³", "6x⁵ - 4x³ + 2", "30x⁴ - 12x³ + 2"], answer: 0, explanation: "d/dx(5x⁶)=30x⁵, d/dx(-3x⁴)=-12x³, d/dx(2x)=2, giving 30x⁵-12x³+2." },
  { question: "Integrate ∫(6x⁵ - 4x³) dx.", options: ["x⁶ - x⁴ + C", "6x⁶ - 4x⁴ + C", "30x⁴ - 12x² + C", "x⁵ - x³ + C"], answer: 0, explanation: "∫6x⁵dx = x⁶ and ∫-4x³dx = -x⁴, giving x⁶ - x⁴ + C." },
  { question: "Find dy/dx for y = cos(3x).", options: ["-3sin(3x)", "3sin(3x)", "-sin(3x)", "sin(3x)/3"], answer: 0, explanation: "Using the chain rule, the derivative of cos(3x) is -3sin(3x)." },
  { question: "Find dy/dx for y = tan(2x).", options: ["2sec²(2x)", "sec²(2x)", "-2sec²(2x)", "2tan(2x)sec(2x)"], answer: 0, explanation: "The derivative of tan(kx) is k·sec²(kx), so here it's 2sec²(2x)." },
  { question: "What is the derivative of a constant function, y = c?", options: ["0", "1", "c", "cx"], answer: 0, explanation: "A constant function has zero rate of change, so its derivative is 0." },
  { question: "Find the equation of the normal to y = x² at the point (1, 1).", options: ["y = -½x + 3/2", "y = 2x - 1", "y = ½x + 1/2", "y = -2x + 3"], answer: 0, explanation: "The tangent gradient at x=1 is 2, so the normal gradient is -½. Using point-slope form: y - 1 = -½(x-1), giving y = -½x + 3/2." },
  { question: "Find the x-coordinates of the stationary points of y = x³ - 3x² + 2.", options: ["x = 0 and x = 2", "x = 0 and x = 3", "x = 1 and x = 2", "x = -1 and x = 2"], answer: 0, explanation: "dy/dx = 3x² - 6x = 3x(x-2) = 0, giving x = 0 or x = 2." },
  { question: "For y = x³ - 3x² + 2, use the second derivative test to determine the nature of the stationary point at x = 0.", options: ["Maximum", "Minimum", "Point of inflection", "Cannot be determined"], answer: 0, explanation: "y'' = 6x - 6. At x=0, y'' = -6, which is negative, indicating a maximum." },
  { question: "Solve 2sin(x) = √3 for 0° ≤ x ≤ 360°.", options: ["x = 60° and x = 120°", "x = 60° and x = 240°", "x = 30° and x = 150°", "x = 45° and x = 135°"], answer: 0, explanation: "sin(x) = √3/2, giving x = 60° or x = 180° - 60° = 120°." },
  { question: "Solve cos(x) = 0.5 for 0° ≤ x ≤ 360°.", options: ["x = 60° and x = 300°", "x = 60° and x = 120°", "x = 30° and x = 330°", "x = 45° and x = 315°"], answer: 0, explanation: "cos(x) = 0.5 gives x = 60° or x = 360° - 60° = 300°." },
  { question: "Simplify: sin(x)/cos(x).", options: ["tan(x)", "cot(x)", "sec(x)", "csc(x)"], answer: 0, explanation: "By definition, sin(x)/cos(x) = tan(x)." },
  { question: "Which identity is equivalent to 1 + tan²θ?", options: ["sec²θ", "csc²θ", "cos²θ", "sin²θ"], answer: 0, explanation: "This is one of the standard Pythagorean trigonometric identities: 1 + tan²θ = sec²θ." },
  { question: "Express 2sin(x)cos(x) as a single trigonometric function.", options: ["sin(2x)", "cos(2x)", "2sin(x)", "tan(2x)"], answer: 0, explanation: "This is the double angle identity: sin(2x) = 2sin(x)cos(x)." },
  { question: "Solve e^(2x) = 50, giving x to 2 decimal places.", options: ["1.76", "1.96", "2.16", "3.91"], answer: 1, explanation: "Taking natural logs: 2x = ln(50) ≈ 3.912, so x ≈ 1.96." },
  { question: "Solve 3^x = 2^(x+1), giving x to 2 decimal places.", options: ["1.41", "1.55", "1.71", "1.89"], answer: 2, explanation: "Taking logs: x·ln(3) = (x+1)·ln(2), so x(ln3-ln2) = ln2, giving x ≈ 0.693/0.4055 ≈ 1.71." },
  { question: "Find the sum to infinity of a geometric series with a = 12 and r = 1/3.", options: ["16", "18", "20", "24"], answer: 1, explanation: "S∞ = a/(1-r) = 12/(2/3) = 18." },
  { question: "A geometric series has a = 5 and S∞ = 20. Find the common ratio.", options: ["0.5", "0.6", "0.75", "0.8"], answer: 2, explanation: "20 = 5/(1-r), so 1-r = 0.25, giving r = 0.75." },
  { question: "Vectors a = (3, 4) and b = (4, -3). Find the angle between them using the dot product.", options: ["0°", "45°", "90°", "180°"], answer: 2, explanation: "a·b = (3×4)+(4×-3) = 12-12 = 0. A zero dot product means the vectors are perpendicular (90°)." },
  { question: "Find the vector equation of the line through (1, 2) with direction vector (3, -1).", options: ["r = (1,2) + t(3,-1)", "r = (3,-1) + t(1,2)", "r = (1,2) + t(1,2)", "r = (2,1) + t(3,-1)"], answer: 0, explanation: "The vector equation uses a known point and the direction vector: r = (1,2) + t(3,-1)." },
  { question: "For the parametric equations x = t², y = 2t, find dy/dx in terms of t.", options: ["1/t", "t", "2t", "2/t"], answer: 0, explanation: "dx/dt = 2t and dy/dt = 2, so dy/dx = (dy/dt)/(dx/dt) = 2/(2t) = 1/t." },
  { question: "Solve the differential equation dy/dx = 3x², given that y = 5 when x = 0.", options: ["y = x³ + 5", "y = 3x³ + 5", "y = x³", "y = x² + 5"], answer: 0, explanation: "Integrating gives y = x³ + C. Using y(0)=5 gives C=5, so y = x³ + 5." },
  { question: "What is the general solution to the differential equation dy/dx = ky, describing exponential growth?", options: ["y = Ae^(kt)", "y = kt + A", "y = At^k", "y = Ak^t"], answer: 0, explanation: "This differential equation describes exponential growth or decay, with general solution y = Ae^(kt)." },
  { question: "If X ~ B(10, 0.3), find P(X = 3), to 2 decimal places.", options: ["0.09", "0.27", "0.35", "0.12"], answer: 1, explanation: "Using the binomial formula, P(X=3) = C(10,3)(0.3)³(0.7)⁷ ≈ 0.267, which rounds to 0.27." },
  { question: "If X ~ B(20, 0.25), find the mean of X.", options: ["4", "5", "6", "15"], answer: 1, explanation: "The mean of a binomial distribution is np = 20 × 0.25 = 5." },
  { question: "If X ~ B(20, 0.25), find the variance of X.", options: ["2.5", "3.75", "5", "15"], answer: 1, explanation: "The variance of a binomial distribution is np(1-p) = 20 × 0.25 × 0.75 = 3.75." },
  { question: "According to the empirical rule for a normal distribution, approximately what percentage of data lies within 1 standard deviation of the mean?", options: ["50%", "68%", "95%", "99.7%"], answer: 1, explanation: "For a normal distribution, approximately 68% of data lies within one standard deviation of the mean." },
  { question: "If Z ~ N(0, 1), find P(Z < 0).", options: ["0", "0.25", "0.5", "1"], answer: 2, explanation: "The standard normal distribution is symmetric about 0, so exactly half the probability lies below 0." },
  { question: "A correlation coefficient of r = 0.9 indicates what kind of relationship?", options: ["Strong positive correlation", "Strong negative correlation", "No correlation", "Weak positive correlation"], answer: 0, explanation: "Values of r close to +1 indicate a strong positive linear relationship." },
  { question: "What does a correlation coefficient of r = -1 indicate?", options: ["No correlation", "A perfect positive correlation", "A perfect negative correlation", "A random relationship"], answer: 2, explanation: "A correlation coefficient of exactly -1 indicates a perfect negative linear relationship." },
  { question: "Using v = u + at, a particle starts at 5 m/s and accelerates at 2 m/s² for 4 seconds. Find its final velocity.", options: ["9 m/s", "11 m/s", "13 m/s", "15 m/s"], answer: 2, explanation: "v = u + at = 5 + (2×4) = 13 m/s." },
  { question: "Using s = ut + ½at², a particle starts from rest and accelerates at 4 m/s² for 3 seconds. Find the distance traveled.", options: ["12 m", "16 m", "18 m", "24 m"], answer: 2, explanation: "s = 0 + ½(4)(3²) = ½(4)(9) = 18 m." },
  { question: "Using v² = u² + 2as, a particle starts from rest and accelerates at 5 m/s² over 20 m. Find its final velocity, to 2 decimal places.", options: ["10.00 m/s", "12.25 m/s", "14.14 m/s", "16.50 m/s"], answer: 2, explanation: "v² = 0 + 2(5)(20) = 200, so v = √200 ≈ 14.14 m/s." },
  { question: "A particle experiences two perpendicular forces of 8 N and 6 N. Find the magnitude of the resultant force.", options: ["7 N", "8 N", "10 N", "14 N"], answer: 2, explanation: "By Pythagoras: √(8² + 6²) = √(64+36) = √100 = 10 N." },
  { question: "A resultant force of 10 N acts on a mass of 4 kg. Find the acceleration produced.", options: ["1.5 m/s²", "2 m/s²", "2.5 m/s²", "4 m/s²"], answer: 2, explanation: "a = F/m = 10/4 = 2.5 m/s²." },
  { question: "A 5 kg object on a frictionless surface has a 15 N force applied to it. Find its acceleration.", options: ["1 m/s²", "2 m/s²", "3 m/s²", "5 m/s²"], answer: 2, explanation: "a = F/m = 15/5 = 3 m/s²." },
  { question: "Two forces act on an object: 10 N east and 10 N north. Find the magnitude of the resultant force, to 2 decimal places.", options: ["10.00 N", "14.14 N", "20.00 N", "17.32 N"], answer: 1, explanation: "By Pythagoras: √(10² + 10²) = √200 ≈ 14.14 N." },
  { question: "For the previous scenario (10 N east and 10 N north), find the direction of the resultant force from east.", options: ["30°", "45°", "60°", "90°"], answer: 1, explanation: "Since the two perpendicular components are equal, the resultant bisects the angle between them, at 45°." },
  { question: "A beam pivoted at its centre has a clockwise moment of 30 Nm and an anticlockwise moment of 30 Nm acting on it. Is the beam in equilibrium?", options: ["Yes, the moments balance", "No, it will rotate clockwise", "No, it will rotate anticlockwise", "Cannot be determined"], answer: 0, explanation: "Equal and opposite moments (30 Nm each way) balance, satisfying the condition for rotational equilibrium." },
  { question: "An arithmetic sequence has a₁ = 7 and d = -2. Find the 10th term.", options: ["-9", "-11", "-13", "11"], answer: 1, explanation: "a₁₀ = 7 + 9(-2) = 7 - 18 = -11." },
  { question: "Find the sum of the first 20 terms of the arithmetic sequence with a₁ = 7 and d = -2.", options: ["-220", "-240", "-260", "-280"], answer: 1, explanation: "S₂₀ = (20/2)[2(7) + 19(-2)] = 10[14 - 38] = 10(-24) = -240." },
  { question: "A geometric sequence has a₁ = 4 and r = 2. Find the 7th term.", options: ["128", "192", "256", "512"], answer: 2, explanation: "a₇ = 4 × 2⁶ = 4 × 64 = 256." },
  { question: "The numbers 4, x, 16 form a geometric sequence. Find the positive value of x.", options: ["6", "8", "10", "12"], answer: 1, explanation: "For a geometric sequence, x² = 4 × 16 = 64, so x = 8 (taking the positive root)." },
  { question: "If f(x) = 2x + 3 and g(x) = x², find fg(x) (i.e., f(g(x))).", options: ["2x² + 3", "4x² + 12x + 9", "2x² + 6x", "x² + 2x + 3"], answer: 0, explanation: "fg(x) = f(g(x)) = f(x²) = 2x² + 3." },
  { question: "If f(x) = 2x + 3 and g(x) = x², find gf(x) (i.e., g(f(x))).", options: ["2x² + 3", "4x² + 12x + 9", "2x² + 6x", "x² + 2x + 3"], answer: 1, explanation: "gf(x) = g(f(x)) = g(2x+3) = (2x+3)² = 4x² + 12x + 9." },
  { question: "Find the inverse of f(x) = 3x - 4.", options: ["f⁻¹(x) = (x+4)/3", "f⁻¹(x) = (x-4)/3", "f⁻¹(x) = 3x+4", "f⁻¹(x) = (x+3)/4"], answer: 0, explanation: "Setting y = 3x-4 and solving for x: x = (y+4)/3, so f⁻¹(x) = (x+4)/3." },
  { question: "Find the domain of f(x) = √(x - 5).", options: ["x ≥ 5", "x ≤ 5", "x > 5", "All real numbers"], answer: 0, explanation: "The expression under the square root must be non-negative: x - 5 ≥ 0, so x ≥ 5." },
  { question: "Find the range of f(x) = x² + 2 for all real x.", options: ["y ≥ 0", "y ≥ 2", "y > 2", "All real numbers"], answer: 1, explanation: "Since x² ≥ 0 for all real x, the minimum value of f(x) is 2, giving a range of y ≥ 2." },
  { question: "Using the remainder theorem, find the remainder when x³ - 2x² + x - 5 is divided by (x - 2).", options: ["-5", "-3", "-1", "1"], answer: 1, explanation: "By the remainder theorem, the remainder equals f(2) = 8 - 8 + 2 - 5 = -3." },
  { question: "Using the factor theorem, is (x - 1) a factor of x³ - 6x² + 11x - 6?", options: ["Yes, since f(1) = 0", "No, since f(1) ≠ 0", "Cannot be determined", "Only for x > 1"], answer: 0, explanation: "f(1) = 1 - 6 + 11 - 6 = 0, so by the factor theorem, (x-1) is a factor." },
  { question: "Given that (x - 1) is a factor of x³ - 6x² + 11x - 6, find all three roots of the equation.", options: ["x = 1, 2, 3", "x = 1, -2, 3", "x = -1, 2, 3", "x = 1, 2, -3"], answer: 0, explanation: "Factoring out (x-1) leaves x² - 5x + 6 = (x-2)(x-3), giving roots x = 1, 2, and 3." },
  { question: "Express 1/((x-1)(x+2)) in partial fractions: A/(x-1) + B/(x+2). What is the value of A?", options: ["1/3", "1/2", "-1/3", "2/3"], answer: 0, explanation: "Setting 1 = A(x+2) + B(x-1) and substituting x=1: 1 = 3A, giving A = 1/3." },
  { question: "Find the distance between the points (1, 1) and (7, 9).", options: ["8", "9", "10", "12"], answer: 2, explanation: "Distance = √[(7-1)² + (9-1)²] = √(36+64) = √100 = 10." },
  { question: "Find the midpoint of the points (1, 1) and (7, 9).", options: ["(3, 4)", "(4, 5)", "(4, 4)", "(5, 5)"], answer: 1, explanation: "Midpoint = ((1+7)/2, (1+9)/2) = (4, 5)." },
  { question: "Find the equation of a circle with centre (2, -3) and radius 5.", options: ["(x-2)² + (y+3)² = 25", "(x+2)² + (y-3)² = 25", "(x-2)² + (y-3)² = 5", "(x-2)² + (y+3)² = 5"], answer: 0, explanation: "The standard form of a circle's equation is (x-h)² + (y-k)² = r², giving (x-2)² + (y+3)² = 25." },
  { question: "Find the radius of the circle x² + y² - 4x + 6y - 3 = 0.", options: ["3", "4", "5", "6"], answer: 1, explanation: "Completing the square: (x-2)² + (y+3)² = 3 + 4 + 9 = 16, so the radius is 4." },
  { question: "A population grows according to P = 200e^(0.05t). Find the population after 10 years, to the nearest whole number.", options: ["300", "330", "350", "400"], answer: 1, explanation: "P = 200e^0.5 ≈ 200 × 1.6487 ≈ 330." },
  { question: "Find the area enclosed between the curve y = 4 - x² and the x-axis.", options: ["16/3", "8", "32/3", "16"], answer: 2, explanation: "∫₋₂² (4-x²)dx = [4x - x³/3] from -2 to 2 = (8 - 8/3) - (-8 + 8/3) = 16 - 16/3 = 32/3." },
  { question: "What is the Newton-Raphson iterative formula used to find roots of an equation?", options: ["x_(n+1) = x_n - f(x_n)/f'(x_n)", "x_(n+1) = x_n + f(x_n)", "x_(n+1) = f(x_n)/f'(x_n)", "x_(n+1) = x_n × f'(x_n)"], answer: 0, explanation: "The Newton-Raphson method uses this formula to iteratively approximate a root of f(x) = 0." },
  { question: "What does the trapezium rule approximate?", options: ["The area under a curve (a definite integral)", "The gradient of a curve", "The roots of an equation", "The nth term of a sequence"], answer: 0, explanation: "The trapezium rule provides a numerical approximation for the value of a definite integral." },
  { question: "In how many ways can 5 distinct books be arranged on a shelf?", options: ["25", "60", "120", "720"], answer: 2, explanation: "The number of arrangements of 5 distinct items is 5! = 120." },
  { question: "How many ways can you choose 3 items from a set of 8, where order doesn't matter?", options: ["24", "56", "336", "512"], answer: 1, explanation: "This is a combination: C(8,3) = 8!/(3!5!) = 56." },
  { question: "How many ways can you arrange 3 items chosen from a set of 8, where order matters?", options: ["56", "168", "336", "512"], answer: 2, explanation: "This is a permutation: P(8,3) = 8!/5! = 336." },
  { question: "Two independent events A and B have P(A) = 0.4 and P(B) = 0.5. Find P(A ∩ B).", options: ["0.1", "0.2", "0.45", "0.9"], answer: 1, explanation: "For independent events, P(A ∩ B) = P(A) × P(B) = 0.4 × 0.5 = 0.2." },
  { question: "For the previous scenario (P(A)=0.4, P(B)=0.5, independent), find P(A ∪ B).", options: ["0.6", "0.7", "0.9", "1.0"], answer: 1, explanation: "P(A ∪ B) = P(A) + P(B) - P(A∩B) = 0.4 + 0.5 - 0.2 = 0.7." },
  { question: "If P(A ∩ B) = 0.15 and P(B) = 0.3, find P(A|B).", options: ["0.15", "0.3", "0.45", "0.5"], answer: 3, explanation: "P(A|B) = P(A∩B)/P(B) = 0.15/0.3 = 0.5." },
  { question: "Find the discriminant of 3x² + 2x + 5 and state the nature of the roots.", options: ["-56, no real roots", "-56, two real roots", "56, two real roots", "4, two equal roots"], answer: 0, explanation: "Discriminant = b² - 4ac = 4 - 60 = -56, which is negative, meaning there are no real roots." },
  { question: "Solve |2x - 3| = 7.", options: ["x = 5 only", "x = -2 only", "x = 5 or x = -2", "x = 2 or x = -5"], answer: 2, explanation: "Either 2x-3=7 (giving x=5) or 2x-3=-7 (giving x=-2)." },
  { question: "Find the term independent of x in the binomial expansion of (x + 1/x)⁴.", options: ["4", "6", "8", "12"], answer: 1, explanation: "The general term is C(4,k)x^(4-2k). Setting 4-2k=0 gives k=2, and C(4,2) = 6." },
  { question: "Find the sum of the coefficients in the expansion of (2x + 1)⁵ by substituting x = 1.", options: ["81", "125", "243", "729"], answer: 2, explanation: "Substituting x=1 gives (2+1)⁵ = 3⁵ = 243." },
  { question: "A curve satisfies dy/dx = 2x + 3 and passes through (1, 4). Find the equation of the curve.", options: ["y = x² + 3x", "y = x² + 3x + 1", "y = x² + 3", "y = 2x² + 3x"], answer: 0, explanation: "Integrating gives y = x² + 3x + C. Using the point (1,4): 4 = 1 + 3 + C, so C = 0, giving y = x² + 3x." },
  { question: "Find the derivative of y = x²ln(x) using the product rule.", options: ["2x ln(x) + x", "2x ln(x)", "x ln(x) + x", "2 ln(x) + x"], answer: 0, explanation: "Product rule: dy/dx = 2x·ln(x) + x²·(1/x) = 2x ln(x) + x." },
  { question: "Find the second derivative of y = x⁴ - 2x².", options: ["12x² - 4", "4x³ - 4x", "12x - 4", "4x² - 4"], answer: 0, explanation: "First derivative: 4x³-4x. Second derivative: 12x² - 4." },
  { question: "Find the value of x for which the curve y = x³ - 12x has a point of inflection.", options: ["x = -2", "x = 0", "x = 2", "x = 4"], answer: 1, explanation: "y'' = 6x. Setting y''=0 gives x=0, a candidate point of inflection." },
  { question: "Express cos(2x) in terms of sin(x) using a double angle identity.", options: ["1 - 2sin²(x)", "2sin²(x) - 1", "2sin(x) - 1", "sin²(x) - cos²(x)"], answer: 0, explanation: "One form of the double angle identity is cos(2x) = 1 - 2sin²(x)." },
  { question: "Find the equation of the tangent to the curve y = x³ at the point (1, 1).", options: ["y = 3x - 2", "y = 3x + 2", "y = x + 1", "y = 3x - 1"], answer: 0, explanation: "dy/dx = 3x², giving a gradient of 3 at x=1. Using point-slope form: y - 1 = 3(x-1), so y = 3x - 2." }
];

const ALEVEL_CHEMISTRY_QUESTIONS = [
  { question: "What is the electron configuration of a sodium atom (Na, Z=11)?", options: ["1s²2s²2p⁶3s¹", "1s²2s²2p⁶3s²", "1s²2s²2p⁵3s²", "1s²2s²2p⁶3s¹3p¹"], answer: 0, explanation: "Sodium's 11 electrons fill 1s, 2s, 2p completely (10 electrons), with the 11th in the 3s subshell." },
  { question: "What is the electron configuration of a chloride ion, Cl⁻? (Cl, Z=17)", options: ["1s²2s²2p⁶3s²3p⁵", "1s²2s²2p⁶3s²3p⁶", "1s²2s²2p⁶3s²3p⁴", "1s²2s²2p⁶3s¹3p⁶"], answer: 1, explanation: "A chlorine atom (3s²3p⁵) gains one electron to form Cl⁻, filling the 3p subshell to give 3s²3p⁶." },
  { question: "What is the term for the energy required to remove one mole of electrons from one mole of gaseous atoms?", options: ["Electron affinity", "First ionisation energy", "Lattice energy", "Electronegativity"], answer: 1, explanation: "First ionisation energy is defined as the energy needed to remove the outermost electron from each atom in a mole of gaseous atoms." },
  { question: "Which type of intermolecular force is present in all molecules, both polar and non-polar?", options: ["Hydrogen bonding", "Dipole-dipole forces", "London (dispersion) forces", "Ionic bonding"], answer: 2, explanation: "London dispersion forces arise from temporary fluctuations in electron distribution and occur in all molecules." },
  { question: "According to VSEPR theory, what is the shape of a molecule with 4 bonding pairs and 0 lone pairs on the central atom?", options: ["Tetrahedral", "Trigonal pyramidal", "Bent", "Trigonal planar"], answer: 0, explanation: "Four bonding pairs with no lone pairs arrange themselves tetrahedrally to minimise repulsion." },
  { question: "What is the shape of ammonia, NH3, which has 3 bonding pairs and 1 lone pair?", options: ["Tetrahedral", "Trigonal pyramidal", "Bent", "Linear"], answer: 1, explanation: "The lone pair pushes the three N-H bonds into a trigonal pyramidal arrangement." },
  { question: "Calculate the concentration, in mol/dm³, of a solution made by dissolving 0.5 mol of NaOH in 250 cm³ of solution.", options: ["0.5 mol/dm³", "1 mol/dm³", "2 mol/dm³", "4 mol/dm³"], answer: 2, explanation: "c = n/V = 0.5 / 0.25 = 2 mol/dm³." },
  { question: "What volume, in cm³, of 2 mol/dm³ HCl is needed to provide 0.1 mol of HCl?", options: ["25 cm³", "50 cm³", "100 cm³", "200 cm³"], answer: 1, explanation: "V = n/c = 0.1/2 = 0.05 dm³ = 50 cm³." },
  { question: "In the equilibrium N2(g) + 3H2(g) ⇌ 2NH3(g), what happens to the position of equilibrium if pressure is increased?", options: ["Shifts toward reactants", "Shifts toward products", "No change", "Cannot be determined"], answer: 1, explanation: "Increasing pressure favours the side with fewer gas moles; the product side has 2 moles versus 4 on the reactant side, so equilibrium shifts toward products." },
  { question: "For an exothermic reaction at equilibrium, what happens to the position of equilibrium if temperature is increased?", options: ["Shifts toward products", "Shifts toward reactants", "No change", "Equilibrium is destroyed"], answer: 1, explanation: "Increasing temperature favours the endothermic direction, which for an exothermic forward reaction is the reverse direction, shifting equilibrium toward reactants." },
  { question: "For the equilibrium 2SO2(g) + O2(g) ⇌ 2SO3(g), which is the correct expression for Kc?", options: ["[SO3]² / ([SO2]²[O2])", "[SO3] / ([SO2][O2])", "[SO2]²[O2] / [SO3]²", "[SO3]² / ([SO2][O2])"], answer: 0, explanation: "Kc is products over reactants, each raised to their stoichiometric coefficient: [SO3]²/([SO2]²[O2])." },
  { question: "What is the oxidation state of chromium in the dichromate ion, Cr2O7²⁻?", options: ["+3", "+4", "+6", "+7"], answer: 2, explanation: "Setting 2x + 7(-2) = -2 gives 2x = 12, so x = +6." },
  { question: "In the half-equation MnO4⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H2O, what happens to the oxidation state of manganese?", options: ["Increases by 5", "Decreases by 5", "Increases by 2", "Decreases by 2"], answer: 1, explanation: "Manganese goes from +7 in MnO4⁻ to +2 in Mn²⁺, a decrease of 5 (reduction)." },
  { question: "Which mechanism does a primary haloalkane typically undergo when reacting with a hydroxide ion?", options: ["SN1", "SN2", "E1", "E2"], answer: 1, explanation: "Primary haloalkanes favour the SN2 mechanism, where the nucleophile attacks as the leaving group departs in one step." },
  { question: "What is a nucleophile?", options: ["An electron pair donor", "An electron pair acceptor", "A proton donor", "A proton acceptor"], answer: 0, explanation: "A nucleophile is a species that donates a pair of electrons to form a new covalent bond." },
  { question: "Which functional group characterises an aldehyde?", options: ["-OH", "-CHO", "-COOH", "-CO-"], answer: 1, explanation: "Aldehydes are defined by the -CHO functional group at the end of a carbon chain." },
  { question: "Which functional group characterises a ketone?", options: ["-OH", "-CHO", "-COOH", "A carbonyl (C=O) between two carbon groups"], answer: 3, explanation: "Ketones have a carbonyl group bonded to two carbon-containing groups, not at the end of the chain." },
  { question: "What is the general functional group of a carboxylic acid?", options: ["-OH", "-CHO", "-COOH", "-CO-"], answer: 2, explanation: "Carboxylic acids are defined by the -COOH functional group." },
  { question: "Which reagent gives a silver mirror with aldehydes but not ketones?", options: ["Fehling's solution", "Tollens' reagent", "Bromine water", "Universal indicator"], answer: 1, explanation: "Tollens' reagent is reduced by aldehydes, depositing metallic silver as a mirror, but does not react with ketones." },
  { question: "What does Le Chatelier's principle predict?", options: ["Reaction rate only", "How a system at equilibrium responds to changes in concentration, pressure, or temperature", "The colour of a compound", "The mechanism of a reaction"], answer: 1, explanation: "Le Chatelier's principle predicts the direction equilibrium shifts in response to changes in conditions." },
  { question: "What term describes the enthalpy change when one mole of a compound is formed from its elements in their standard states?", options: ["Standard enthalpy of combustion", "Standard enthalpy of formation", "Standard enthalpy of reaction", "Lattice enthalpy"], answer: 1, explanation: "Standard enthalpy of formation refers specifically to forming one mole of a compound from its elements." },
  { question: "Using Hess's Law, if ΔH1 = -200 kJ/mol and ΔH2 = +50 kJ/mol for two steps of a cycle, what is the overall ΔH?", options: ["-250 kJ/mol", "-150 kJ/mol", "150 kJ/mol", "250 kJ/mol"], answer: 1, explanation: "Adding the two enthalpy changes: -200 + 50 = -150 kJ/mol." },
  { question: "What is the rate equation for a reaction that is first order overall, first order in A only?", options: ["rate = k", "rate = k[A]", "rate = k[A]²", "rate = k[A][B]²"], answer: 1, explanation: "A first-order reaction has a rate directly proportional to the concentration of one reactant: rate = k[A]." },
  { question: "What is meant by 'activation energy'?", options: ["The total energy released by a reaction", "The minimum energy required for a reaction to occur", "The energy of the products", "The energy of the reactants"], answer: 1, explanation: "Activation energy is the minimum energy that colliding particles need for a reaction to take place." },
  { question: "Which type of isomerism involves the same molecular formula but a different arrangement of atoms in the structure?", options: ["Geometric isomerism", "Structural isomerism", "Optical isomerism", "None of these"], answer: 1, explanation: "Structural isomers share a molecular formula but differ in how their atoms are bonded together." },
  { question: "What is a mass spectrometer primarily used to determine?", options: ["Relative atomic/molecular mass and isotopic abundance", "The pH of a solution", "The rate of a reaction", "The colour of a compound"], answer: 0, explanation: "Mass spectrometry ionises and detects particles based on their mass-to-charge ratio, revealing mass and isotopic composition." },
  { question: "In mass spectrometry, what does the M+ peak represent?", options: ["The molecular ion peak, showing the mass of the whole molecule minus an electron", "The lightest fragment detected", "The base peak only", "The mass of a single proton"], answer: 0, explanation: "The M+ peak corresponds to the molecule having lost one electron, giving its overall molecular mass." },
  { question: "Chlorine has two isotopes: ³⁵Cl (75% abundance) and ³⁷Cl (25% abundance). Calculate its relative atomic mass.", options: ["35.0", "35.5", "36.0", "36.5"], answer: 1, explanation: "Weighted average: (35×0.75) + (37×0.25) = 26.25 + 9.25 = 35.5." },
  { question: "A large jump between the 2nd and 3rd successive ionisation energies of an element suggests it is most likely in which group?", options: ["Group 1", "Group 2", "Group 3", "Group 7"], answer: 1, explanation: "A large jump after removing 2 electrons indicates the 3rd electron is from a new, closer shell, consistent with Group 2 (2 outer electrons)." },
  { question: "What does the term 'lattice enthalpy' refer to?", options: ["The energy released when 1 mole of an ionic compound forms from its gaseous ions", "The energy needed to melt an ionic solid", "The energy released during combustion", "The energy needed to dissolve a solid"], answer: 0, explanation: "Lattice enthalpy is defined as the enthalpy change when one mole of an ionic solid forms from its constituent gaseous ions." },
  { question: "Which factor increases the magnitude of lattice enthalpy?", options: ["Smaller ionic radius and higher ionic charge", "Larger ionic radius and lower ionic charge", "Larger ionic radius only", "Lower ionic charge only"], answer: 0, explanation: "Smaller, more highly charged ions attract each other more strongly, increasing lattice enthalpy magnitude." },
  { question: "What is a Born-Haber cycle used to calculate?", options: ["Lattice enthalpy indirectly, using Hess's Law", "The rate of a reaction", "The pH of a solution", "The boiling point of a compound"], answer: 0, explanation: "Born-Haber cycles use Hess's Law to calculate lattice enthalpy from other measurable enthalpy changes." },
  { question: "What is the enthalpy change of atomisation?", options: ["The energy needed to form 1 mole of gaseous atoms from an element in its standard state", "The energy released when a compound dissolves", "The energy needed to ionise an atom", "The energy released during a redox reaction"], answer: 0, explanation: "Enthalpy of atomisation is defined per mole of gaseous atoms formed from an element in its standard state." },
  { question: "What is the enthalpy change of hydration?", options: ["The energy released when 1 mole of gaseous ions dissolve in water, forming hydrated ions", "The energy needed to boil water", "The energy released during neutralisation", "The energy needed to break a covalent bond"], answer: 0, explanation: "Hydration enthalpy specifically refers to gaseous ions becoming surrounded by water molecules in solution." },
  { question: "What does Hess's Law state?", options: ["The total enthalpy change for a reaction is independent of the route taken", "Enthalpy always increases during a reaction", "Reactions with negative ΔH cannot occur", "Enthalpy is always conserved exactly at each step"], answer: 0, explanation: "Hess's Law states that the overall enthalpy change depends only on the initial and final states, not the pathway." },
  { question: "Using Hess's Law, if a two-step route has ΔH1 = -100 kJ/mol and ΔH2 = +40 kJ/mol, what is the overall enthalpy change?", options: ["-140 kJ/mol", "-60 kJ/mol", "60 kJ/mol", "140 kJ/mol"], answer: 1, explanation: "Adding the two steps: -100 + 40 = -60 kJ/mol." },
  { question: "For a reaction with negative ΔH and negative ΔS, when is it most likely to be spontaneous?", options: ["At low temperature only", "At high temperature only", "At all temperatures", "Never spontaneous"], answer: 0, explanation: "Since ΔG = ΔH - TΔS, with ΔH negative and ΔS negative, -TΔS becomes increasingly positive at high T, so the reaction is only spontaneous (ΔG<0) at low temperature." },
  { question: "For a rate equation rate = k[A]²[B], what is the overall order of the reaction?", options: ["1", "2", "3", "4"], answer: 2, explanation: "The overall order is the sum of the individual orders: 2 (for A) + 1 (for B) = 3." },
  { question: "If doubling the concentration of A quadruples the reaction rate, what is the order with respect to A?", options: ["Zero order", "First order", "Second order", "Third order"], answer: 2, explanation: "A doubling of concentration causing a 4x (2²) increase in rate indicates second order with respect to A." },
  { question: "If changing the concentration of B has no effect on reaction rate, what is the order with respect to B?", options: ["Zero order", "First order", "Second order", "Third order"], answer: 0, explanation: "A reactant that doesn't affect rate when its concentration changes has an order of zero with respect to that reactant." },
  { question: "What are the units of the rate constant, k, for a first-order reaction?", options: ["s⁻¹", "mol dm⁻³ s⁻¹", "dm³ mol⁻¹ s⁻¹", "dm⁶ mol⁻² s⁻¹"], answer: 0, explanation: "For a first-order reaction, rate = k[A], so k has units of s⁻¹ (per second)." },
  { question: "What are the units of the rate constant, k, for a second-order reaction where rate = k[A]²?", options: ["s⁻¹", "mol dm⁻³ s⁻¹", "dm³ mol⁻¹ s⁻¹", "dm⁶ mol⁻² s⁻¹"], answer: 2, explanation: "For rate = k[A]², solving for k's units gives dm³ mol⁻¹ s⁻¹." },
  { question: "What is the rate-determining step of a reaction?", options: ["The slowest step in a multi-step reaction mechanism", "The fastest step in a reaction mechanism", "The final step of any reaction", "The step involving a catalyst"], answer: 0, explanation: "The rate-determining step is the slowest step, which limits the overall rate of the reaction sequence." },
  { question: "What does Kp represent in equilibrium chemistry?", options: ["An equilibrium constant expressed using partial pressures of gases", "An equilibrium constant only used for solids", "The rate constant of a reaction", "The pH of an equilibrium mixture"], answer: 0, explanation: "Kp is the equilibrium constant expressed in terms of the partial pressures of gaseous reactants and products." },
  { question: "For the equilibrium N2O4(g) ⇌ 2NO2(g), what is the correct expression for Kp?", options: ["(P_NO2)²/P_N2O4", "P_NO2/P_N2O4", "P_N2O4/(P_NO2)²", "P_N2O4 × (P_NO2)²"], answer: 0, explanation: "Kp is products over reactants, using partial pressures raised to their stoichiometric coefficients." },
  { question: "What is a buffer solution designed to resist?", options: ["Changes in pH upon the small addition of acid or base", "Changes in temperature", "Changes in volume", "Changes in colour"], answer: 0, explanation: "A buffer, typically a weak acid and its conjugate base, minimizes pH change when small amounts of acid or base are added." },
  { question: "Using the Henderson-Hasselbalch equation, pH = pKa + log([A⁻]/[HA]), find the pH of a buffer with pKa = 4.76 and equal concentrations of A⁻ and HA.", options: ["0", "4.76", "9.52", "log(4.76)"], answer: 1, explanation: "When [A⁻] = [HA], the log term is log(1) = 0, so pH = pKa = 4.76." },
  { question: "What is the equivalence point in an acid-base titration?", options: ["The point where moles of acid equal moles of base, achieving exact neutralisation", "The starting point of the titration", "The point where the indicator is added", "The midpoint of the titration curve, always at pH 7"], answer: 0, explanation: "The equivalence point is reached when the reacting species have combined in exactly stoichiometric proportions." },
  { question: "For a titration between a strong acid and a strong base, which indicator is generally suitable?", options: ["Phenolphthalein", "No indicator can be used", "Only universal indicator works", "Indicators cannot detect a strong acid-strong base equivalence point"], answer: 0, explanation: "Strong acid-strong base titrations have a very steep pH change at equivalence, so most indicators, including phenolphthalein, work well." },
  { question: "What is the standard electrode potential of a half-cell measured relative to?", options: ["The standard hydrogen electrode (SHE)", "A copper electrode", "Room temperature air", "Any arbitrary reference"], answer: 0, explanation: "By convention, standard electrode potentials are measured relative to the standard hydrogen electrode, defined as 0 V." },
  { question: "A more positive standard electrode potential (E°) indicates what about a species' tendency to be reduced?", options: ["A stronger oxidising agent (greater tendency to be reduced)", "A stronger reducing agent", "No effect on oxidising ability", "A weaker oxidising agent"], answer: 0, explanation: "A more positive E° indicates a greater tendency for the species to gain electrons (be reduced), making it a stronger oxidising agent." },
  { question: "If the overall E°cell for a reaction is positive, what does this indicate?", options: ["The reaction is thermodynamically feasible (spontaneous)", "The reaction is not feasible", "The reaction rate is fast", "The reaction is exothermic"], answer: 0, explanation: "A positive E°cell indicates the reaction is thermodynamically favorable under standard conditions, though it says nothing about reaction rate." },
  { question: "What is disproportionation?", options: ["A reaction in which a single species is simultaneously oxidised and reduced", "A reaction where only oxidation occurs", "A reaction where only reduction occurs", "A reaction with no electron transfer"], answer: 0, explanation: "In disproportionation, the same element in one species undergoes both oxidation and reduction in the same reaction." },
  { question: "The reaction 2Cu⁺ → Cu + Cu²⁺ is an example of what type of reaction?", options: ["Neutralisation", "Disproportionation", "Simple displacement", "Hydrolysis"], answer: 1, explanation: "Copper(I) is simultaneously oxidised to Cu²⁺ and reduced to Cu, making this a disproportionation reaction." },
  { question: "What type of reaction converts a halogenoalkane to an alcohol using aqueous sodium hydroxide?", options: ["Nucleophilic substitution", "Electrophilic addition", "Free radical substitution", "Elimination"], answer: 0, explanation: "The hydroxide ion acts as a nucleophile, substituting the halogen atom to form an alcohol." },
  { question: "Which mechanism is generally favoured for tertiary halogenoalkanes reacting with hydroxide ions?", options: ["SN1", "SN2", "E2 only", "Free radical substitution"], answer: 0, explanation: "Tertiary halogenoalkanes favour SN1 due to the formation of a relatively stable tertiary carbocation intermediate." },
  { question: "Why do tertiary halogenoalkanes favour the SN1 mechanism over SN2?", options: ["A more stable carbocation forms, and steric hindrance disfavours direct SN2 attack", "They have no leaving group", "They cannot react with nucleophiles", "They are always more reactive with weaker nucleophiles"], answer: 0, explanation: "The stability of the tertiary carbocation and steric crowding around the carbon both favour a stepwise SN1 pathway." },
  { question: "What does elimination of a halogenoalkane with hot ethanolic potassium hydroxide typically produce?", options: ["An alkene, water, and a halide ion", "An alcohol only", "A carboxylic acid", "An aldehyde"], answer: 0, explanation: "Under these conditions, hydroxide acts as a base, removing a proton and the halogen to form an alkene." },
  { question: "What functional group characterises an amine?", options: ["-NH2", "-OH", "-COOH", "-CHO"], answer: 0, explanation: "Amines are characterised by the presence of an -NH2 (or substituted nitrogen) functional group." },
  { question: "Which nucleophile is commonly used to convert a halogenoalkane into a primary amine?", options: ["Ammonia (NH3)", "Water", "Hydrogen gas", "Sodium chloride"], answer: 0, explanation: "Ammonia acts as a nucleophile, substituting the halogen to form a primary amine." },
  { question: "What type of isomerism do the cis and trans forms of but-2-ene represent?", options: ["Structural isomerism", "Geometric (E/Z) isomerism", "Optical isomerism", "No isomerism"], answer: 1, explanation: "Cis/trans (E/Z) isomerism arises from restricted rotation around the C=C double bond." },
  { question: "What causes geometric (E/Z) isomerism to occur in alkenes?", options: ["Restricted rotation around the C=C double bond", "Free rotation around single bonds", "The presence of a chiral centre", "Differences in molecular formula"], answer: 0, explanation: "The rigid, planar nature of the C=C double bond prevents free rotation, locking substituents into distinct spatial arrangements." },
  { question: "What are optical isomers?", options: ["Non-superimposable mirror images of each other", "Isomers with different molecular formulas", "Isomers formed by different reaction mechanisms", "Isomers that only differ by their state of matter"], answer: 0, explanation: "Optical isomers (enantiomers) are mirror-image molecules that cannot be superimposed on one another." },
  { question: "What is a chiral centre?", options: ["A carbon atom bonded to four different groups", "Any carbon atom in a molecule", "A carbon involved in a double bond", "A carbon bonded to only hydrogen atoms"], answer: 0, explanation: "A chiral centre is a carbon atom with four different substituents, giving rise to non-superimposable mirror images." },
  { question: "What technique is used to distinguish between optical isomers based on their effect on plane-polarised light?", options: ["Polarimetry", "Mass spectrometry", "Infrared spectroscopy", "Chromatography"], answer: 0, explanation: "Polarimetry measures the rotation of plane-polarised light, which differs between optical isomers." },
  { question: "In infrared (IR) spectroscopy, what does a strong absorption around 1700 cm⁻¹ typically indicate?", options: ["Presence of a C=O (carbonyl) group", "Presence of an O-H group", "Presence of a C-H bond only", "Presence of a C≡C triple bond"], answer: 0, explanation: "A strong, sharp absorption near 1700 cm⁻¹ is characteristic of a carbonyl (C=O) stretch." },
  { question: "In IR spectroscopy, what does a broad absorption around 3200-3550 cm⁻¹ typically indicate?", options: ["A C=O group", "An O-H group (alcohol or carboxylic acid)", "A C-H bond only", "A C≡N group"], answer: 1, explanation: "A broad absorption in this range is characteristic of O-H stretching, found in alcohols and carboxylic acids." },
  { question: "What does proton (¹H) NMR spectroscopy primarily provide information about?", options: ["The different hydrogen environments within a molecule", "The overall molecular mass", "The reaction rate of a compound", "The boiling point of a compound"], answer: 0, explanation: "Proton NMR reveals information about the chemical environment of hydrogen atoms in a molecule." },
  { question: "In proton NMR, what does the number of distinct peaks (signals) indicate?", options: ["The number of different hydrogen environments in the molecule", "The total number of hydrogen atoms", "The molecular mass", "The boiling point"], answer: 0, explanation: "Each distinct signal corresponds to a chemically different type of hydrogen environment in the molecule." },
  { question: "In proton NMR, what does the area under each peak (integration) indicate?", options: ["The relative number of hydrogens in that environment", "The exact chemical shift value", "The molecular formula", "The temperature of the sample"], answer: 0, explanation: "Integration values show the relative ratio of hydrogen atoms contributing to each signal." },
  { question: "In proton NMR, what does the splitting pattern of a signal (the n+1 rule) indicate?", options: ["The number of adjacent, non-equivalent hydrogen atoms", "The exact molecular mass", "The overall charge of the molecule", "The boiling point of the compound"], answer: 0, explanation: "The n+1 rule relates a signal's splitting to the number of neighbouring, non-equivalent hydrogens." },
  { question: "What is mass spectrometry fragmentation data used to help determine?", options: ["The structure of a molecule, based on characteristic mass fragments", "The pH of a solution", "The rate of a reaction", "The colour of a compound"], answer: 0, explanation: "Fragmentation patterns provide clues about a molecule's structure by revealing stable fragment masses." },
  { question: "What is the term for the addition of hydrogen across a C=C double bond?", options: ["Hydrogenation", "Hydrolysis", "Hydration", "Halogenation"], answer: 0, explanation: "Hydrogenation is the addition of H2 across a double bond, typically using a catalyst." },
  { question: "What catalyst is commonly used in the hydrogenation of alkenes?", options: ["Nickel", "Sodium", "Iron(III) chloride", "Sulfuric acid"], answer: 0, explanation: "A nickel catalyst is commonly used to catalyse the addition of hydrogen to alkenes." },
  { question: "What is formed when an alkene reacts with steam in the presence of an acid catalyst (hydration)?", options: ["An alcohol", "An alkane", "A carboxylic acid", "An aldehyde"], answer: 0, explanation: "Hydration adds water across the double bond, forming an alcohol." },
  { question: "What catalyst is used industrially for the hydration of ethene to produce ethanol?", options: ["Phosphoric acid, at high temperature and pressure", "Nickel, at room temperature", "Sodium hydroxide, at low pressure", "Iron, at room temperature"], answer: 0, explanation: "Industrial ethanol production from ethene uses a phosphoric acid catalyst under high temperature and pressure." },
  { question: "What does oxidation of a primary alcohol with acidified potassium dichromate first produce?", options: ["An aldehyde", "A ketone", "An alkene", "An ether"], answer: 0, explanation: "Primary alcohols are first oxidised to aldehydes, which can be further oxidised to carboxylic acids." },
  { question: "What does oxidation of a secondary alcohol with acidified potassium dichromate produce?", options: ["An aldehyde", "A ketone", "A carboxylic acid", "An alkene"], answer: 1, explanation: "Secondary alcohols are oxidised to ketones, which resist further oxidation under these conditions." },
  { question: "Why can't tertiary alcohols be oxidised by acidified potassium dichromate?", options: ["There is no hydrogen on the carbon bonded to the -OH group", "Tertiary alcohols are too reactive", "Tertiary alcohols contain no oxygen", "Dichromate cannot react with alcohols at all"], answer: 0, explanation: "Oxidation of an alcohol requires a hydrogen on the carbon bearing the -OH group, which tertiary alcohols lack." },
  { question: "What colour change is observed when acidified potassium dichromate oxidises a primary or secondary alcohol?", options: ["Orange to green", "Purple to colourless", "Blue to yellow", "Colourless to blue"], answer: 0, explanation: "Dichromate(VI) ions (orange) are reduced to chromium(III) ions (green) during the oxidation reaction." },
  { question: "What is esterification?", options: ["The reaction between an alcohol and a carboxylic acid to form an ester and water", "The reaction between two alcohols", "The addition of hydrogen to a double bond", "The breakdown of an ester into smaller molecules"], answer: 0, explanation: "Esterification combines an alcohol and carboxylic acid, releasing water and forming an ester." },
  { question: "What catalyst is commonly used in esterification reactions?", options: ["Concentrated sulfuric acid", "Nickel", "Sodium hydroxide", "Potassium permanganate"], answer: 0, explanation: "Concentrated sulfuric acid catalyses esterification and helps drive the equilibrium toward the ester product." },
  { question: "What does hydrolysis of an ester under acidic conditions produce?", options: ["A carboxylic acid and an alcohol", "A salt and water only", "An alkene and water", "A ketone and an alcohol"], answer: 0, explanation: "Acidic hydrolysis reverses esterification, regenerating the carboxylic acid and alcohol." },
  { question: "What does hydrolysis of an ester under alkaline conditions (saponification) produce?", options: ["A carboxylate salt and an alcohol", "A carboxylic acid and an alkene", "Only water", "A ketone and an aldehyde"], answer: 0, explanation: "Alkaline hydrolysis of an ester produces a carboxylate salt (rather than the free acid) and an alcohol." },
  { question: "What is the polymer formed by addition polymerisation of ethene called?", options: ["Polyethene (polyethylene)", "Nylon", "PET", "Polylactic acid"], answer: 0, explanation: "Addition polymerisation of many ethene monomers produces polyethene." },
  { question: "What type of polymerisation forms polyesters from a dicarboxylic acid and a diol?", options: ["Addition polymerisation", "Condensation polymerisation", "Radical polymerisation", "Ionic polymerisation"], answer: 1, explanation: "Condensation polymerisation joins monomers with the loss of a small molecule, such as water, forming polyesters." },
  { question: "What is a common example of a condensation polymer formed from two different monomers?", options: ["Polyethene", "Nylon (a polyamide)", "Polypropene", "PVC"], answer: 1, explanation: "Nylon is a classic condensation polymer, formed from a diamine and a dicarboxylic acid (or diacyl chloride)." },
  { question: "What is the general term for a molecule that acts as the repeating building block of a polymer?", options: ["A monomer", "A catalyst", "An isomer", "A ligand"], answer: 0, explanation: "Monomers are the small repeating units that link together to form a polymer chain." },
  { question: "What is the oxidation state of iron in FeO?", options: ["+1", "+2", "+3", "+4"], answer: 1, explanation: "Since oxygen is -2, iron must be +2 to balance the charge in FeO." },
  { question: "What is the oxidation state of iron in Fe2O3?", options: ["+1", "+2", "+3", "+4"], answer: 2, explanation: "With 3 oxygens at -2 each (total -6), the two iron atoms must together be +6, giving each iron a +3 oxidation state." },
  { question: "What electron configuration feature characterises transition metals?", options: ["Partially filled d-orbitals in at least one common oxidation state", "A full outer s-orbital only", "No d-electrons at all", "Only s and p orbitals"], answer: 0, explanation: "Transition metals are defined by having partially filled d-subshells in at least one of their common ions or the element itself." },
  { question: "What property of transition metals makes many of their compounds coloured?", options: ["d-d electron transitions absorbing specific wavelengths of visible light", "Their high melting points", "Their high density", "Their magnetic properties only"], answer: 0, explanation: "Electrons transitioning between split d-orbitals absorb specific visible wavelengths, giving many transition metal compounds colour." },
  { question: "What is a ligand?", options: ["A molecule or ion that donates a lone pair of electrons to a central metal ion, forming a coordinate bond", "A type of catalyst used only in industry", "A synonym for a transition metal", "A type of polymer"], answer: 0, explanation: "Ligands bond to a central metal ion via a dative (coordinate) covalent bond, using a lone pair of electrons." },
  { question: "What is the coordination number of a metal ion surrounded by six ligands in an octahedral complex?", options: ["4", "5", "6", "8"], answer: 2, explanation: "The coordination number equals the number of coordinate bonds to the central metal ion, which is 6 for an octahedral complex." },
  { question: "What is the shape of a complex ion with a coordination number of 4, when the ligands are arranged with 109.5° bond angles?", options: ["Tetrahedral", "Square planar", "Octahedral", "Linear"], answer: 0, explanation: "A coordination number of 4 with 109.5° angles corresponds to a tetrahedral arrangement of ligands." },
  { question: "What is an important use of transition metal catalysts, such as iron in the Haber process?", options: ["Speeding up industrial reactions without being consumed", "Acting as the main reactant", "Preventing any reaction from occurring", "Only changing the colour of the product"], answer: 0, explanation: "Transition metals and their compounds are widely used as catalysts in industrial processes, such as iron in the Haber process." },
  { question: "What is meant by the term 'electrophile'?", options: ["An electron-pair acceptor, often attracted to areas of high electron density", "An electron-pair donor", "A proton acceptor only", "A neutral, unreactive species"], answer: 0, explanation: "An electrophile seeks out and accepts a pair of electrons, often attacking regions of high electron density such as double bonds." },
  { question: "In electrophilic addition, what is the first step when bromine reacts with an alkene?", options: ["The alkene's pi bond attacks the bromine molecule, inducing a dipole", "Bromine attacks the alkene directly with a lone pair", "The alkene loses a proton first", "A radical chain reaction begins immediately"], answer: 0, explanation: "The electron-rich C=C double bond induces a temporary dipole in the non-polar bromine molecule, initiating electrophilic addition." },
  { question: "What is the product when bromine water is added to ethene?", options: ["1,2-dibromoethane", "Bromoethane", "Ethanol", "Ethanoic acid"], answer: 0, explanation: "Electrophilic addition of bromine across the double bond of ethene produces 1,2-dibromoethane." },
  { question: "What visible change occurs when bromine water is added to an alkene?", options: ["The orange bromine water decolourises", "The solution turns blue", "A white precipitate forms immediately", "The solution bubbles vigorously"], answer: 0, explanation: "As bromine reacts with and adds across the C=C double bond, the characteristic orange colour of bromine water fades." }
];

const ALEVEL_PHYSICS_QUESTIONS = [
  { question: "What is the equation for kinetic energy?", options: ["mv²", "½mv²", "mv", "2mv²"], answer: 1, explanation: "Kinetic energy = ½ × mass × velocity²." },
  { question: "A car of mass 1000 kg travels at 20 m/s. Find its kinetic energy.", options: ["20 kJ", "100 kJ", "200 kJ", "400 kJ"], answer: 2, explanation: "KE = ½(1000)(20²) = ½(1000)(400) = 200,000 J = 200 kJ." },
  { question: "What is the equation for momentum?", options: ["p = mv", "p = mv²", "p = m/v", "p = ma"], answer: 0, explanation: "Momentum equals mass multiplied by velocity." },
  { question: "According to the principle of conservation of momentum, what is true in a closed system with no external forces?", options: ["Momentum is only conserved in elastic collisions", "Total momentum before a collision equals total momentum after", "Momentum always increases", "Momentum is destroyed in collisions"], answer: 1, explanation: "In an isolated system, total momentum is always conserved, in both elastic and inelastic collisions." },
  { question: "What best describes the difference between elastic and inelastic collisions?", options: ["Kinetic energy is conserved in elastic collisions but not inelastic collisions", "Momentum is conserved in elastic collisions but not inelastic collisions", "Kinetic energy is conserved in both types", "Neither type conserves momentum"], answer: 0, explanation: "Both types conserve momentum, but only elastic collisions also conserve total kinetic energy." },
  { question: "What is the equation for centripetal force?", options: ["F = mv²/r", "F = mv/r", "F = mr²/v", "F = mv²r"], answer: 0, explanation: "Centripetal force equals mass times velocity squared, divided by the radius of the circular path." },
  { question: "What does Hooke's Law state?", options: ["F = kx, force is proportional to extension within the elastic limit", "F = ma", "F = mv", "Ep = ½kx²"], answer: 0, explanation: "Hooke's Law states that the extension of a spring is directly proportional to the applied force, within its elastic limit." },
  { question: "What is the equation for elastic potential energy stored in a spring?", options: ["kx", "½kx", "½kx²", "kx²"], answer: 2, explanation: "Elastic potential energy = ½ × spring constant × extension²." },
  { question: "What is the term for the maximum displacement of a wave from its equilibrium position?", options: ["Wavelength", "Frequency", "Amplitude", "Period"], answer: 2, explanation: "Amplitude is the maximum displacement of a point on a wave from its rest (equilibrium) position." },
  { question: "What is the equation relating the period and frequency of a wave?", options: ["T = 1/f", "T = f", "T = 2f", "T = f²"], answer: 0, explanation: "Period and frequency are reciprocals of each other: T = 1/f." },
  { question: "What is the de Broglie wavelength formula?", options: ["λ = h/p", "λ = hp", "λ = p/h", "λ = hv"], answer: 0, explanation: "The de Broglie wavelength is given by Planck's constant divided by momentum: λ = h/p." },
  { question: "What is the photoelectric effect?", options: ["The emission of electrons from a metal surface when light of sufficient frequency shines on it", "The bending of light through a prism", "The reflection of light off a mirror", "The absorption of light by a black body"], answer: 0, explanation: "The photoelectric effect describes electrons being ejected from a metal surface when illuminated by light above a threshold frequency." },
  { question: "According to Einstein's photoelectric equation, what determines whether electrons are emitted from a metal?", options: ["The intensity of light alone", "The frequency of light exceeding the threshold frequency", "The wavelength being red", "The colour of the metal"], answer: 1, explanation: "Photoemission occurs only if incident photons have a frequency (and thus energy) at or above the metal's threshold frequency." },
  { question: "What is the equation for the energy of a photon?", options: ["E = hf", "E = h/f", "E = mc²", "E = hf²"], answer: 0, explanation: "The energy of a photon equals Planck's constant multiplied by its frequency." },
  { question: "What does Coulomb's Law calculate?", options: ["Gravitational force", "The electrostatic force between two point charges", "Magnetic force", "Nuclear force"], answer: 1, explanation: "Coulomb's Law gives the electrostatic force between two point charges." },
  { question: "What is the formula for electric field strength due to a point charge?", options: ["E = kQ/r²", "E = kQ/r", "E = kQr²", "E = kQ²/r"], answer: 0, explanation: "Electric field strength from a point charge follows an inverse-square law: E = kQ/r²." },
  { question: "What is the SI unit of magnetic flux density?", options: ["Weber", "Tesla", "Henry", "Gauss"], answer: 1, explanation: "Magnetic flux density is measured in tesla (T) in the SI system." },
  { question: "What is the formula for the force on a current-carrying wire in a magnetic field (wire perpendicular to field)?", options: ["F = BIL", "F = BI/L", "F = B/IL", "F = BIL²"], answer: 0, explanation: "The force on a current-carrying conductor equals magnetic flux density × current × length." },
  { question: "What is the term for the phenomenon where a changing magnetic field induces an EMF?", options: ["Electromagnetic induction", "Electrostatic induction", "Magnetic resonance", "Electrolysis"], answer: 0, explanation: "Electromagnetic induction is the generation of an EMF due to a changing magnetic flux." },
  { question: "According to Faraday's Law, the induced EMF is proportional to what?", options: ["The magnetic field strength alone", "The rate of change of magnetic flux", "The resistance of the circuit", "The area of the coil alone"], answer: 1, explanation: "Faraday's Law states that induced EMF is proportional to the rate of change of magnetic flux linkage." },
  { question: "What is radioactive half-life?", options: ["The time for half the radioactive nuclei in a sample to decay", "The total time for all nuclei to decay", "The time for the sample to double", "The time for a single nucleus to decay"], answer: 0, explanation: "Half-life is the time taken for the number of undecayed nuclei in a sample to fall to half its original value." },
  { question: "A radioactive isotope has a half-life of 10 years. What fraction of the original sample remains after 30 years?", options: ["1/2", "1/4", "1/8", "1/16"], answer: 2, explanation: "30 years is 3 half-lives, so the remaining fraction is (1/2)³ = 1/8." },
  { question: "What is the equation for gravitational potential energy near Earth's surface?", options: ["mgh", "mg/h", "m/gh", "mgh²"], answer: 0, explanation: "Near Earth's surface, gravitational potential energy is approximated as mass × gravitational field strength × height." },
  { question: "What is the equation for the orbital speed of a satellite in a circular orbit, derived by equating gravitational force to centripetal force?", options: ["v = √(GM/r)", "v = GM/r", "v = √(GM/r²)", "v = GM/r²"], answer: 0, explanation: "Setting GMm/r² = mv²/r and solving for v gives v = √(GM/r)." },
  { question: "What does 'specific heat capacity' refer to?", options: ["The energy needed to raise the temperature of 1 kg of a substance by 1°C", "The energy needed to melt 1 kg of a substance", "The total heat energy in an object", "The energy needed to raise the temperature of 1 g of a substance by 1°C"], answer: 0, explanation: "Specific heat capacity is defined per kilogram, per degree Celsius (or kelvin) of temperature change." },
  { question: "What is the equation for stress?", options: ["stress = force/area", "stress = force × area", "stress = extension/length", "stress = force/extension"], answer: 0, explanation: "Stress is defined as force applied per unit cross-sectional area." },
  { question: "What is the equation for strain?", options: ["strain = extension/original length", "strain = force/area", "strain = original length/extension", "strain = force × extension"], answer: 0, explanation: "Strain is defined as the extension of a material divided by its original length, and is dimensionless." },
  { question: "What is Young's modulus?", options: ["Stress divided by strain, within the elastic limit", "Force divided by extension", "The maximum stress a material can withstand", "The energy stored per unit volume"], answer: 0, explanation: "Young's modulus is the ratio of stress to strain for a material behaving elastically." },
  { question: "A material has a stress of 2×10⁷ Pa and a strain of 0.001. Find its Young's modulus.", options: ["2×10⁴ Pa", "2×10⁷ Pa", "2×10¹⁰ Pa", "2×10¹³ Pa"], answer: 2, explanation: "Young's modulus = stress/strain = (2×10⁷)/0.001 = 2×10¹⁰ Pa." },
  { question: "What does the area under a stress-strain graph represent?", options: ["The energy stored per unit volume of the material", "The material's density", "The material's mass", "The material's temperature"], answer: 0, explanation: "The area under a stress-strain graph gives the strain energy stored per unit volume." },
  { question: "What is the elastic limit of a material?", options: ["The point beyond which the material will not return to its original shape", "The point at which the material breaks", "The maximum stress a material can experience", "The point at which strain becomes zero"], answer: 0, explanation: "Beyond the elastic limit, a material undergoes permanent (plastic) deformation." },
  { question: "What is a stationary (standing) wave formed by?", options: ["The superposition of two waves of the same frequency traveling in opposite directions", "A single wave reflecting off a fixed point", "Two waves of different frequencies combining", "A wave traveling through a vacuum"], answer: 0, explanation: "Stationary waves result from the interference of two identical waves traveling in opposite directions." },
  { question: "What is a node in a stationary wave?", options: ["A point of zero displacement (amplitude)", "A point of maximum displacement", "The source of the wave", "The midpoint of the wave"], answer: 0, explanation: "Nodes are points on a stationary wave where destructive interference always occurs, giving zero displacement." },
  { question: "What is an antinode in a stationary wave?", options: ["A point of maximum displacement (amplitude)", "A point of zero displacement", "The source of the wave", "A point where the wave stops"], answer: 0, explanation: "Antinodes are points where constructive interference always occurs, giving maximum displacement." },
  { question: "What is the distance between adjacent nodes in a stationary wave?", options: ["Half a wavelength", "A full wavelength", "A quarter wavelength", "Two wavelengths"], answer: 0, explanation: "Adjacent nodes in a stationary wave are separated by half a wavelength." },
  { question: "What equation gives the fundamental frequency of a stretched string fixed at both ends?", options: ["f = v/2L", "f = 2vL", "f = v/L", "f = vL/2"], answer: 0, explanation: "The fundamental mode has a wavelength of 2L, so f = v/λ = v/2L." },
  { question: "A string of length 0.5 m has a wave speed of 200 m/s. Find its fundamental frequency.", options: ["100 Hz", "200 Hz", "400 Hz", "800 Hz"], answer: 1, explanation: "f = v/2L = 200/(2×0.5) = 200 Hz." },
  { question: "What is a diffraction grating used to do?", options: ["Split light into its component wavelengths via interference", "Reflect all light at the same angle", "Absorb specific wavelengths of light", "Polarise light completely"], answer: 0, explanation: "A diffraction grating uses many closely spaced slits to produce sharp interference patterns that separate wavelengths." },
  { question: "What is the diffraction grating equation?", options: ["dsinθ = nλ", "dsinθ = λ/n", "d/sinθ = nλ", "nsinθ = dλ"], answer: 0, explanation: "The diffraction grating equation relates slit spacing d, angle θ, order n, and wavelength λ." },
  { question: "Using dsinθ = nλ, if d = 2×10⁻⁶ m and λ = 500 nm, find sinθ for the first order maximum (n=1).", options: ["0.1", "0.25", "0.5", "0.75"], answer: 1, explanation: "sinθ = nλ/d = (500×10⁻⁹)/(2×10⁻⁶) = 0.25." },
  { question: "What is the Doppler effect?", options: ["The apparent change in frequency due to relative motion between a source and an observer", "The bending of waves around obstacles", "The reflection of waves off a surface", "The absorption of waves by a medium"], answer: 0, explanation: "The Doppler effect describes how observed frequency changes when a wave source and observer move relative to each other." },
  { question: "If a sound source moves toward a stationary observer, what happens to the observed frequency?", options: ["It increases", "It decreases", "It stays the same", "It becomes zero"], answer: 0, explanation: "As the source moves closer, wavefronts bunch together in front of it, increasing the observed frequency." },
  { question: "Calculate the energy of a photon with frequency 5×10¹⁴ Hz. (h = 6.63×10⁻³⁴ Js)", options: ["1.33×10⁻¹⁹ J", "3.32×10⁻¹⁹ J", "6.63×10⁻¹⁹ J", "1.33×10⁻¹⁸ J"], answer: 1, explanation: "E = hf = (6.63×10⁻³⁴)(5×10¹⁴) ≈ 3.32×10⁻¹⁹ J." },
  { question: "What is the work function of a metal?", options: ["The minimum energy needed to remove an electron from its surface", "The total energy of all electrons in the metal", "The energy released when light strikes the metal", "The maximum kinetic energy of emitted electrons"], answer: 0, explanation: "The work function is the minimum energy threshold required to liberate an electron from a metal surface." },
  { question: "In Einstein's photoelectric equation, hf = Φ + KE_max, what does Φ represent?", options: ["The work function", "The photon frequency", "The maximum kinetic energy", "Planck's constant"], answer: 0, explanation: "Φ represents the work function, the minimum energy needed to release an electron." },
  { question: "What is the threshold frequency in the photoelectric effect?", options: ["The minimum frequency of light needed to cause electron emission", "The maximum frequency a metal can absorb", "The frequency at which all electrons are emitted", "The frequency of red light only"], answer: 0, explanation: "Below the threshold frequency, no photoelectrons are emitted regardless of light intensity." },
  { question: "What does wave-particle duality refer to?", options: ["The concept that particles and waves both exhibit wave-like and particle-like properties", "The idea that only light behaves as a wave", "The idea that only electrons behave as particles", "A theory that has been fully disproven"], answer: 0, explanation: "Wave-particle duality describes how entities like light and electrons show both wave and particle characteristics depending on the experiment." },
  { question: "What assumptions does the kinetic theory make about an ideal gas, regarding molecular volume and intermolecular forces?", options: ["Negligible molecular volume and no intermolecular forces except during collisions", "Large molecular volume and strong intermolecular forces", "Negligible molecular volume but strong attractive forces", "Large molecular volume and no forces at all"], answer: 0, explanation: "Ideal gas theory assumes point-like particles with negligible volume and no forces except during elastic collisions." },
  { question: "What is the ideal gas equation?", options: ["pV = nRT", "pV = nR/T", "p = nRT/V²", "pV = RT/n"], answer: 0, explanation: "The ideal gas law relates pressure, volume, moles, the gas constant, and temperature." },
  { question: "Using pV = nRT, find the volume of 2 mol of gas at 300 K and 100,000 Pa. (R = 8.31 J/mol K)", options: ["0.025 m³", "0.05 m³", "0.075 m³", "0.1 m³"], answer: 1, explanation: "V = nRT/p = (2×8.31×300)/100,000 ≈ 0.05 m³." },
  { question: "What does the kinetic theory of gases relate?", options: ["Microscopic particle motion to macroscopic properties like pressure and temperature", "Only the colour of a gas to its temperature", "The chemical formula of a gas to its density", "The boiling point to atmospheric pressure only"], answer: 0, explanation: "Kinetic theory connects the random motion of individual gas particles to observable bulk properties." },
  { question: "What is absolute zero, expressed in Kelvin?", options: ["0 K", "100 K", "-100 K", "273 K"], answer: 0, explanation: "Absolute zero, the theoretical minimum temperature, is defined as 0 K." },
  { question: "Convert 25°C to Kelvin.", options: ["248 K", "273 K", "298 K", "323 K"], answer: 2, explanation: "K = °C + 273, so 25°C = 298 K." },
  { question: "What is the mean kinetic energy of a gas molecule proportional to?", options: ["Absolute temperature", "Pressure only", "Volume only", "The mass of the container"], answer: 0, explanation: "According to kinetic theory, the average kinetic energy of gas particles is directly proportional to absolute temperature." },
  { question: "What is binding energy in nuclear physics?", options: ["The energy required to separate a nucleus into its individual protons and neutrons", "The energy released during chemical bonding", "The energy that holds electrons in orbit", "The kinetic energy of a moving nucleus"], answer: 0, explanation: "Binding energy is the energy needed to completely separate all the nucleons in a nucleus." },
  { question: "What does mass defect refer to?", options: ["The difference between a nucleus's mass and the sum of its individual nucleon masses", "The mass lost when an atom ionises", "The mass gained during nuclear fusion", "The mass of an electron"], answer: 0, explanation: "Mass defect is the 'missing' mass converted into binding energy when nucleons combine into a nucleus." },
  { question: "According to E = mc², what does mass defect correspond to?", options: ["The binding energy of the nucleus", "The kinetic energy of the nucleus", "The charge of the nucleus", "The half-life of the nucleus"], answer: 0, explanation: "Mass defect, via E=mc², is equivalent to the binding energy released when a nucleus forms." },
  { question: "What happens to binding energy per nucleon as you move from light nuclei up toward iron?", options: ["It increases", "It decreases", "It stays constant", "It becomes negative"], answer: 0, explanation: "Binding energy per nucleon generally increases with mass number up to iron, the most stable nucleus." },
  { question: "What happens to binding energy per nucleon for nuclei heavier than iron?", options: ["It increases", "It decreases", "It stays constant", "It becomes negative"], answer: 1, explanation: "Beyond iron, binding energy per nucleon gradually decreases as nuclei get heavier." },
  { question: "Why is iron-56 considered one of the most stable nuclei?", options: ["It has the highest binding energy per nucleon", "It has the most neutrons", "It has the largest mass number of any element", "It is radioactive"], answer: 0, explanation: "Iron-56 sits at the peak of the binding energy per nucleon curve, making it exceptionally stable." },
  { question: "What is a quark?", options: ["A fundamental particle that combines to form hadrons, such as protons and neutrons", "A type of lepton", "A synonym for an electron", "A particle only found in stars"], answer: 0, explanation: "Quarks are fundamental particles that combine in groups (usually threes) to form hadrons like protons and neutrons." },
  { question: "How many quarks make up a proton?", options: ["2", "3", "4", "6"], answer: 1, explanation: "A proton consists of three quarks: two up quarks and one down quark." },
  { question: "What is a lepton?", options: ["A fundamental particle not made of quarks, such as an electron or neutrino", "A particle made of three quarks", "A type of photon", "A particle found only in the nucleus"], answer: 0, explanation: "Leptons, including electrons and neutrinos, are fundamental particles that do not experience the strong nuclear force." },
  { question: "What is the charge of an up quark, in terms of elementary charge e?", options: ["+2/3 e", "-1/3 e", "+1 e", "-2/3 e"], answer: 0, explanation: "The up quark carries a charge of +2/3 of the elementary charge." },
  { question: "What is the charge of a down quark, in terms of elementary charge e?", options: ["+2/3 e", "-1/3 e", "+1 e", "-2/3 e"], answer: 1, explanation: "The down quark carries a charge of -1/3 of the elementary charge." },
  { question: "What is an antiparticle?", options: ["A particle with the same mass but opposite charge (and other quantum numbers) to its corresponding particle", "A particle with negative mass", "A particle that cannot interact with matter", "A synonym for a photon"], answer: 0, explanation: "Every particle has a corresponding antiparticle with identical mass but opposite charge and certain other properties." },
  { question: "What happens when a particle and its antiparticle collide?", options: ["They annihilate, producing energy, often as photons", "They combine to form a heavier stable particle", "They pass through each other unaffected", "They repel each other permanently"], answer: 0, explanation: "Particle-antiparticle collisions result in mutual annihilation, converting their mass into energy." },
  { question: "What force is responsible for holding protons and neutrons together in the nucleus?", options: ["The strong nuclear force", "The weak nuclear force", "The electromagnetic force", "Gravity"], answer: 0, explanation: "The strong nuclear force overcomes electrostatic repulsion between protons, binding nucleons together." },
  { question: "What is the range of the strong nuclear force?", options: ["Very short range, on the scale of femtometres", "Infinite range", "The range of the entire solar system", "The range of an atom's electron shells"], answer: 0, explanation: "The strong nuclear force acts only over extremely short distances, comparable to the size of a nucleus." },
  { question: "What occurs during beta-minus decay?", options: ["A neutron transforms into a proton, emitting an electron and an antineutrino", "A proton transforms into a neutron, emitting a positron", "A nucleus splits into two smaller nuclei", "Two nuclei fuse together"], answer: 0, explanation: "In beta-minus decay, a neutron converts to a proton within the nucleus, releasing an electron and an antineutrino." },
  { question: "What occurs during beta-plus decay?", options: ["A proton transforms into a neutron, emitting a positron and a neutrino", "A neutron transforms into a proton, emitting an electron", "A nucleus captures an electron", "Two protons fuse together"], answer: 0, explanation: "In beta-plus decay, a proton converts to a neutron, releasing a positron and an electron neutrino." },
  { question: "What is a capacitor used to do?", options: ["Store electrical charge (and energy) in an electric field", "Generate a magnetic field permanently", "Convert AC to DC directly", "Amplify an electric current"], answer: 0, explanation: "A capacitor stores electrical energy by accumulating charge on its plates, creating an electric field between them." },
  { question: "What is the equation for capacitance?", options: ["C = Q/V", "C = QV", "C = V/Q", "C = Q + V"], answer: 0, explanation: "Capacitance is defined as the charge stored per unit potential difference." },
  { question: "A capacitor stores 6×10⁻⁴ C of charge at 12 V. Find its capacitance.", options: ["5 μF", "20 μF", "50 μF", "500 μF"], answer: 2, explanation: "C = Q/V = (6×10⁻⁴)/12 = 5×10⁻⁵ F = 50 μF." },
  { question: "What is the equation for energy stored in a capacitor?", options: ["E = ½QV", "E = QV", "E = Q/V", "E = 2QV"], answer: 0, explanation: "The energy stored in a charged capacitor is given by E = ½QV (equivalently ½CV²)." },
  { question: "Find the energy stored in a 50 μF capacitor charged to 12 V.", options: ["1.8 mJ", "3.6 mJ", "7.2 mJ", "14.4 mJ"], answer: 1, explanation: "E = ½CV² = ½(50×10⁻⁶)(12²) = ½(50×10⁻⁶)(144) ≈ 3.6×10⁻³ J = 3.6 mJ." },
  { question: "What happens to the time constant of an RC discharge circuit if resistance increases?", options: ["It increases, so the capacitor discharges more slowly", "It decreases, so the capacitor discharges faster", "It stays the same", "It becomes zero"], answer: 0, explanation: "Since the time constant τ = RC, increasing resistance increases τ, slowing the discharge." },
  { question: "What is the time constant, τ, of an RC circuit?", options: ["τ = RC, the time for charge to fall to 1/e of its initial value", "τ = R/C", "τ = R + C", "τ = C/R²"], answer: 0, explanation: "The time constant τ = RC represents the time taken for charge or voltage to decay to about 37% (1/e) of its initial value." },
  { question: "What is the equation for gravitational field strength due to a point mass?", options: ["g = GM/r²", "g = GM/r", "g = GMr", "g = GM/r³"], answer: 0, explanation: "Gravitational field strength follows an inverse-square relationship with distance from the mass." },
  { question: "What is the equation for gravitational potential?", options: ["V = -GM/r", "V = GM/r²", "V = GMr", "V = -GM/r²"], answer: 0, explanation: "Gravitational potential is defined as V = -GM/r, taking the zero reference point at infinity." },
  { question: "Why is gravitational potential defined as negative?", options: ["Because potential energy is taken as zero at infinity, and work is needed to move away from a mass", "Because gravity always repels", "Because mass is a negative quantity", "It is simply a convention with no physical meaning"], answer: 0, explanation: "Since gravitational potential energy increases (toward zero) as you move away from a mass, values closer to the mass are negative." },
  { question: "What is escape velocity?", options: ["The minimum speed needed for an object to escape a gravitational field without further propulsion", "The maximum speed an object can travel in a gravitational field", "The speed of light in a vacuum", "The orbital speed of a satellite"], answer: 0, explanation: "Escape velocity is the minimum launch speed required to overcome a gravitational field entirely." },
  { question: "What is the formula for escape velocity?", options: ["v = √(2GM/r)", "v = √(GM/r)", "v = GM/r", "v = 2GM/r"], answer: 0, explanation: "Escape velocity is derived by equating kinetic energy to gravitational potential energy, giving v = √(2GM/r)." },
  { question: "What does electric field strength represent?", options: ["Force per unit positive charge", "Charge per unit force", "Energy per unit charge", "Charge per unit area"], answer: 0, explanation: "Electric field strength is defined as the force experienced by a unit positive test charge placed in the field." },
  { question: "What is the equation for electric potential due to a point charge?", options: ["V = kQ/r", "V = kQ/r²", "V = kQr", "V = kQ²/r"], answer: 0, explanation: "Electric potential due to a point charge follows V = kQ/r, similar in form to gravitational potential." },
  { question: "What is the principle of superposition, as applied to waves?", options: ["When two or more waves overlap, the resultant displacement is the sum of the individual displacements", "Waves always cancel each other out when they meet", "Only waves of the same amplitude can combine", "Waves cannot pass through each other"], answer: 0, explanation: "The principle of superposition states that overlapping waves combine by adding their displacements at each point." },
  { question: "For constructive interference, what condition must the path difference satisfy?", options: ["A whole number of wavelengths (nλ)", "A whole number plus a half wavelength", "Any random value", "Exactly zero only"], answer: 0, explanation: "Constructive interference occurs when waves arrive in phase, requiring a path difference of a whole number of wavelengths." },
  { question: "For destructive interference, what condition must the path difference satisfy?", options: ["A whole number plus a half wavelength ((n+½)λ)", "A whole number of wavelengths", "Exactly zero", "Any random value"], answer: 0, explanation: "Destructive interference occurs when waves arrive exactly out of phase, requiring a path difference of (n+½)λ." },
  { question: "In Young's double slit experiment, what factors does fringe spacing depend on?", options: ["Wavelength, slit separation, and distance to the screen", "Only the colour of the light source", "Only the power of the light source", "Only the material of the slits"], answer: 0, explanation: "Fringe spacing is determined by the relationship w = λD/a, involving wavelength, screen distance, and slit separation." },
  { question: "What is the equation for fringe spacing in Young's double slit experiment?", options: ["w = λD/a", "w = λa/D", "w = Da/λ", "w = λ/(Da)"], answer: 0, explanation: "Fringe spacing w equals wavelength × distance to screen, divided by slit separation." },
  { question: "What does it mean for two light sources to be 'coherent'?", options: ["They have a constant phase difference and the same frequency", "They have different frequencies but the same amplitude", "They are both extremely bright", "They travel at different speeds"], answer: 0, explanation: "Coherent sources maintain a constant phase relationship, which is necessary to produce a stable interference pattern." },
  { question: "What is the critical angle in total internal reflection?", options: ["The angle of incidence above which light is totally internally reflected", "The angle at which light always refracts", "The angle at which all light is absorbed", "The angle equal to 90° in every medium"], answer: 0, explanation: "Beyond the critical angle, light traveling into a less dense medium is entirely reflected back rather than refracted." },
  { question: "What is the equation relating critical angle (C) and refractive index (n)?", options: ["sinC = 1/n", "sinC = n", "cosC = 1/n", "sinC = n²"], answer: 0, explanation: "The critical angle satisfies sinC = 1/n, where n is the refractive index of the denser medium." },
  { question: "What is a common application of total internal reflection?", options: ["Optical fibres, used in fibre optic communication", "Standard household mirrors", "Ordinary window glass", "Sound insulation"], answer: 0, explanation: "Optical fibres rely on total internal reflection to transmit light signals over long distances with minimal loss." },
  { question: "What is the equation for refractive index in terms of the speed of light?", options: ["n = c/v", "n = v/c", "n = cv", "n = c - v"], answer: 0, explanation: "Refractive index is the ratio of the speed of light in a vacuum to its speed in the medium." },
  { question: "What is the equation for the de Broglie wavelength of a particle?", options: ["λ = h/p", "λ = hp", "λ = p/h", "λ = h/m"], answer: 0, explanation: "The de Broglie wavelength relates a particle's wavelength to its momentum via Planck's constant." },
  { question: "What is meant by the 'principal quantum number' of an electron in an atom?", options: ["An integer describing the electron's main energy level (shell)", "The exact position of the electron", "The electron's spin direction", "The number of protons in the nucleus"], answer: 0, explanation: "The principal quantum number indicates which energy shell an electron occupies within an atom." },
  { question: "What happens to an electron when it transitions from a higher to a lower energy level in an atom?", options: ["It emits a photon with energy equal to the difference between the levels", "It absorbs a photon", "It gains mass", "Nothing observable happens"], answer: 0, explanation: "Dropping to a lower energy level releases energy as a photon, with energy exactly matching the level difference." },
  { question: "What is meant by 'line spectra' produced by excited atoms?", options: ["Discrete wavelengths of light emitted, corresponding to specific electron transitions", "A continuous range of all wavelengths", "A single wavelength only, regardless of the element", "Random noise with no pattern"], answer: 0, explanation: "Line spectra consist of discrete bright lines, each corresponding to a specific electron energy transition unique to that element." },
  { question: "What does the term 'absolute magnitude' (in a general physics sense of comparing quantities) usually refer to when measuring vector quantities?", options: ["The size of the quantity, ignoring direction", "The direction of the quantity only", "Zero, regardless of the vector", "The vector's units only"], answer: 0, explanation: "Magnitude refers to the numerical size of a vector quantity, independent of its direction." }
];

const ALEVEL_BIOLOGY_QUESTIONS = [
  { question: "What is the role of DNA polymerase during DNA replication?", options: ["It synthesises new DNA strands by adding complementary nucleotides", "It unwinds the DNA double helix", "It joins Okazaki fragments", "It degrades RNA primers"], answer: 0, explanation: "DNA polymerase adds nucleotides complementary to the template strand to build a new DNA strand." },
  { question: "What is the role of DNA helicase?", options: ["Synthesises new DNA strands", "Unwinds the DNA double helix", "Joins DNA fragments together", "Removes RNA primers"], answer: 1, explanation: "DNA helicase unwinds and separates the two strands of the DNA double helix during replication." },
  { question: "What is a codon?", options: ["A sequence of three nucleotides that codes for a specific amino acid", "A single nucleotide", "A type of protein", "A sequence of three amino acids"], answer: 0, explanation: "A codon is a triplet of mRNA nucleotides that specifies a particular amino acid during translation." },
  { question: "What is the process by which mRNA is synthesised from a DNA template called?", options: ["Translation", "Transcription", "Replication", "Splicing"], answer: 1, explanation: "Transcription is the synthesis of mRNA using a DNA template strand." },
  { question: "What is the process by which a protein is synthesised from mRNA at the ribosome called?", options: ["Translation", "Transcription", "Replication", "Splicing"], answer: 0, explanation: "Translation is the process of converting an mRNA sequence into a chain of amino acids (protein)." },
  { question: "What is the term for a segment of DNA that does not code for protein and is removed during mRNA processing?", options: ["Exon", "Intron", "Codon", "Promoter"], answer: 1, explanation: "Introns are non-coding sequences removed from pre-mRNA before translation." },
  { question: "What is the term for the coding sequences of a gene that remain in the mature mRNA?", options: ["Exon", "Intron", "Codon", "Promoter"], answer: 0, explanation: "Exons are the coding regions retained in the final mRNA transcript." },
  { question: "What is an enzyme's active site?", options: ["The region where the substrate binds and the reaction occurs", "The entire enzyme molecule", "A region that inhibits the enzyme", "A cofactor binding site only"], answer: 0, explanation: "The active site is the specific region of an enzyme where substrate binding and catalysis occur." },
  { question: "What is competitive inhibition?", options: ["An inhibitor binds to the active site, competing with the substrate", "An inhibitor binds elsewhere and changes the enzyme's shape", "Substrate concentration has no effect on inhibition", "The enzyme is permanently denatured"], answer: 0, explanation: "In competitive inhibition, the inhibitor resembles the substrate and competes for the active site." },
  { question: "What is non-competitive inhibition?", options: ["An inhibitor binds to a site other than the active site, changing the enzyme's shape", "An inhibitor binds directly to the active site", "It only occurs at high temperatures", "It has no effect on enzyme activity"], answer: 0, explanation: "Non-competitive inhibitors bind elsewhere on the enzyme, altering its shape and reducing activity, regardless of substrate concentration." },
  { question: "What is the primary role of mitochondria?", options: ["Photosynthesis", "Aerobic respiration and ATP production", "Protein synthesis", "DNA replication"], answer: 1, explanation: "Mitochondria are the site of aerobic respiration, producing most of a cell's ATP." },
  { question: "What is the process by which a cell divides to produce four genetically different haploid daughter cells?", options: ["Mitosis", "Meiosis", "Binary fission", "Budding"], answer: 1, explanation: "Meiosis produces four genetically varied haploid cells, essential for sexual reproduction." },
  { question: "What is the term for different versions of the same gene?", options: ["Genotypes", "Alleles", "Phenotypes", "Loci"], answer: 1, explanation: "Alleles are alternative forms of the same gene, occupying the same locus on a chromosome." },
  { question: "In a genetic cross between two heterozygous parents (Aa × Aa), where A is dominant, what is the expected phenotypic ratio?", options: ["1:1", "1:2:1", "3:1", "9:3:3:1"], answer: 2, explanation: "A monohybrid cross between two heterozygotes produces a 3:1 ratio of dominant to recessive phenotypes." },
  { question: "What is the term for the physical location of a gene on a chromosome?", options: ["Allele", "Locus", "Genotype", "Phenotype"], answer: 1, explanation: "A locus is the specific physical position of a gene on a chromosome." },
  { question: "What is natural selection?", options: ["The process by which better-adapted organisms tend to survive and reproduce more successfully", "Random mutation without any selective pressure", "Artificial breeding carried out by humans", "The extinction of all species in an ecosystem"], answer: 0, explanation: "Natural selection favours individuals whose traits improve survival and reproductive success in their environment." },
  { question: "What is the term for the evolutionary process where two species evolve in response to changes in each other?", options: ["Convergent evolution", "Coevolution", "Divergent evolution", "Speciation"], answer: 1, explanation: "Coevolution describes reciprocal evolutionary change between two closely interacting species." },
  { question: "In mammals, what mainly regulates homeostasis?", options: ["Positive feedback only", "Negative feedback mechanisms involving the nervous and endocrine systems", "Entirely random processes", "The digestive system alone"], answer: 1, explanation: "Homeostasis is chiefly maintained through negative feedback loops coordinated by the nervous and endocrine systems." },
  { question: "What is the role of the hormone glucagon?", options: ["Lowers blood glucose levels", "Raises blood glucose levels by stimulating glycogen breakdown", "Regulates water balance", "Controls heart rate"], answer: 1, explanation: "Glucagon raises blood glucose by promoting the breakdown of glycogen to glucose in the liver." },
  { question: "What is the role of insulin?", options: ["Raises blood glucose levels", "Lowers blood glucose levels by promoting glucose uptake into cells", "Regulates water balance", "Controls heart rate"], answer: 1, explanation: "Insulin lowers blood glucose by stimulating cells to take up and store glucose." },
  { question: "What is the term for the maintenance of a constant internal water potential in the body?", options: ["Thermoregulation", "Osmoregulation", "General homeostasis", "Excretion"], answer: 1, explanation: "Osmoregulation specifically refers to controlling water and solute balance in the body." },
  { question: "Which structure in the nephron is responsible for the initial filtration of blood?", options: ["Loop of Henle", "Glomerulus", "Collecting duct", "Distal tubule"], answer: 1, explanation: "The glomerulus, within the Bowman's capsule, is where blood is initially filtered under pressure." },
  { question: "What is the role of antidiuretic hormone (ADH)?", options: ["Increases urine volume", "Increases water reabsorption, reducing urine volume", "Decreases blood pressure only", "Has no effect on the kidneys"], answer: 1, explanation: "ADH increases the permeability of the collecting duct to water, increasing reabsorption and reducing urine volume." },
  { question: "What is the term for a population's genetic composition changing over successive generations?", options: ["Mutation", "Evolution", "Adaptation", "Selection"], answer: 1, explanation: "Evolution describes the change in allele frequencies within a population over generations." },
  { question: "What is the term for two populations that cannot interbreed to produce fertile offspring?", options: ["The same species", "Reproductively isolated (different species)", "Hybrids", "Clones"], answer: 1, explanation: "Under the biological species concept, reproductive isolation — the inability to produce fertile offspring — defines separate species." },
  { question: "What is the monomer of proteins?", options: ["Amino acids", "Monosaccharides", "Nucleotides", "Fatty acids"], answer: 0, explanation: "Proteins are polymers built from amino acid monomers joined by peptide bonds." },
  { question: "What type of bond links amino acids together in a protein?", options: ["Glycosidic bond", "Peptide bond", "Ester bond", "Hydrogen bond"], answer: 1, explanation: "Amino acids join via peptide bonds, formed between the amine group of one and the carboxyl group of the next." },
  { question: "What reaction forms a peptide bond between two amino acids?", options: ["A condensation reaction, releasing water", "A hydrolysis reaction, absorbing water", "An oxidation reaction", "A reduction reaction"], answer: 0, explanation: "Peptide bond formation is a condensation reaction, releasing a water molecule as the bond forms." },
  { question: "What is the primary structure of a protein?", options: ["The sequence of amino acids in the polypeptide chain", "The folding into alpha helices and beta sheets", "The 3D shape of a single polypeptide", "The arrangement of multiple polypeptide subunits"], answer: 0, explanation: "Primary structure refers simply to the linear order of amino acids in the chain." },
  { question: "What is the secondary structure of a protein?", options: ["The folding of the polypeptide into alpha helices or beta pleated sheets", "The linear sequence of amino acids", "The 3D shape stabilised by R group interactions", "The combination of multiple polypeptide chains"], answer: 0, explanation: "Secondary structure describes local folding patterns, stabilised by hydrogen bonds along the polypeptide backbone." },
  { question: "What stabilises the tertiary structure of a protein?", options: ["Interactions between R groups, including hydrogen bonds, ionic bonds, disulfide bridges, and hydrophobic interactions", "Only peptide bonds", "Only glycosidic bonds", "Only hydrogen bonds between bases"], answer: 0, explanation: "Tertiary structure, the overall 3D shape of a polypeptide, is held together by various R group interactions." },
  { question: "What is the quaternary structure of a protein?", options: ["The arrangement of multiple polypeptide subunits into one functional protein", "The primary sequence of one chain", "The folding of a single chain into a helix", "A synonym for the primary structure"], answer: 0, explanation: "Quaternary structure applies to proteins made of more than one polypeptide chain, describing how the subunits are arranged." },
  { question: "Which protein is a well-known example of a molecule with quaternary structure?", options: ["Haemoglobin", "Amylase", "Insulin (as a monomer)", "Collagen (single strand)"], answer: 0, explanation: "Haemoglobin consists of four polypeptide subunits, making it a classic example of quaternary structure." },
  { question: "What type of bond links monosaccharides together to form larger carbohydrates?", options: ["Peptide bond", "Glycosidic bond", "Ester bond", "Ionic bond"], answer: 1, explanation: "Monosaccharides are linked by glycosidic bonds, formed through condensation reactions." },
  { question: "What three components make up a nucleotide?", options: ["A phosphate group, a pentose sugar, and a nitrogenous base", "An amino acid, a sugar, and a phosphate", "Two sugars and a phosphate", "A fatty acid, glycerol, and a phosphate"], answer: 0, explanation: "Nucleotides, the building blocks of nucleic acids, consist of a phosphate group, a pentose sugar, and a nitrogenous base." },
  { question: "What holds the two strands of the DNA double helix together?", options: ["Hydrogen bonds between complementary base pairs", "Peptide bonds", "Glycosidic bonds", "Ionic bonds between phosphates"], answer: 0, explanation: "Hydrogen bonding between complementary bases (A-T and C-G) holds the two DNA strands together." },
  { question: "How many hydrogen bonds form between adenine and thymine in DNA?", options: ["1", "2", "3", "4"], answer: 1, explanation: "Adenine and thymine are held together by 2 hydrogen bonds." },
  { question: "How many hydrogen bonds form between guanine and cytosine in DNA?", options: ["1", "2", "3", "4"], answer: 2, explanation: "Guanine and cytosine are held together by 3 hydrogen bonds, making this pairing stronger than A-T." },
  { question: "What is the basic structure of a triglyceride lipid?", options: ["One glycerol molecule bonded to three fatty acid chains", "Two glycerol molecules bonded to one fatty acid", "A chain of amino acids", "A ring of sugar molecules"], answer: 0, explanation: "Triglycerides consist of a glycerol backbone esterified with three fatty acid chains." },
  { question: "What type of bond links glycerol to fatty acids in a triglyceride?", options: ["Peptide bond", "Glycosidic bond", "Ester bond", "Hydrogen bond"], answer: 2, explanation: "Ester bonds form between the hydroxyl groups of glycerol and the carboxyl groups of fatty acids." },
  { question: "What model describes the structure of the cell surface membrane?", options: ["The fluid mosaic model", "The rigid lattice model", "The static bilayer model", "The porous sheet model"], answer: 0, explanation: "The fluid mosaic model describes the membrane as a fluid phospholipid bilayer with embedded, mobile proteins." },
  { question: "What role does cholesterol play in the cell membrane?", options: ["It regulates membrane fluidity", "It transports oxygen across the membrane", "It forms the primary structural backbone", "It has no significant role"], answer: 0, explanation: "Cholesterol molecules sit within the phospholipid bilayer, moderating its fluidity across a range of temperatures." },
  { question: "What is facilitated diffusion?", options: ["Passive movement of molecules across a membrane through protein channels or carriers, down a concentration gradient", "Active movement requiring ATP", "Movement of water only", "Movement against a concentration gradient"], answer: 0, explanation: "Facilitated diffusion uses membrane proteins to help specific molecules diffuse passively down their concentration gradient." },
  { question: "What is active transport?", options: ["Movement of molecules across a membrane against their concentration gradient, using ATP", "Passive movement down a concentration gradient", "Movement of water only, via osmosis", "Movement that never requires a protein carrier"], answer: 0, explanation: "Active transport moves substances against their gradient, requiring energy from ATP hydrolysis." },
  { question: "What is co-transport (symport)?", options: ["The simultaneous movement of two different molecules across a membrane via a shared transport protein", "The transport of a single molecule using two different proteins", "A synonym for simple diffusion", "The movement of only water molecules"], answer: 0, explanation: "Co-transport couples the movement of one substance (often down its gradient) with another (often against its gradient) through a shared carrier protein." },
  { question: "What is the role of the Golgi apparatus?", options: ["Modifying, sorting, and packaging proteins and lipids for secretion or use within the cell", "Synthesising ATP", "Storing genetic material", "Producing ribosomes"], answer: 0, explanation: "The Golgi apparatus processes and packages molecules received from the endoplasmic reticulum." },
  { question: "What is the role of the rough endoplasmic reticulum?", options: ["Synthesis and folding of proteins, aided by attached ribosomes", "Synthesis of lipids and steroids", "Breakdown of waste materials", "Storage of water"], answer: 0, explanation: "The rough ER has ribosomes attached to its surface, where proteins are synthesised and folded." },
  { question: "What is the role of the smooth endoplasmic reticulum?", options: ["Synthesis of lipids and steroids", "Synthesis of proteins", "Digestion of waste materials", "Production of ATP"], answer: 0, explanation: "The smooth ER lacks ribosomes and specialises in lipid and steroid synthesis." },
  { question: "What is the role of lysosomes?", options: ["Contain digestive enzymes to break down waste materials and pathogens", "Store genetic material", "Produce ATP through respiration", "Synthesise proteins directly"], answer: 0, explanation: "Lysosomes contain hydrolytic enzymes that digest waste, debris, and engulfed pathogens." },
  { question: "Where does the electron transport chain occur within the mitochondria?", options: ["On the inner mitochondrial membrane", "In the mitochondrial matrix", "In the outer mitochondrial membrane", "In the cytoplasm"], answer: 0, explanation: "The electron transport chain consists of protein complexes embedded in the inner mitochondrial membrane." },
  { question: "What occurs during the link reaction of respiration?", options: ["Pyruvate is converted to acetyl-CoA, releasing carbon dioxide", "Glucose is broken down into pyruvate", "ATP is produced via chemiosmosis", "Water is split, releasing oxygen"], answer: 0, explanation: "The link reaction converts pyruvate into acetyl-CoA in the mitochondrial matrix, releasing CO2 as a byproduct." },
  { question: "What is oxidative phosphorylation?", options: ["The production of ATP using energy from the electron transport chain, coupled with chemiosmosis", "The breakdown of glucose in the cytoplasm", "The conversion of pyruvate to lactate", "The synthesis of glucose from carbon dioxide"], answer: 0, explanation: "Oxidative phosphorylation generates the majority of a cell's ATP, using the proton gradient created by the electron transport chain." },
  { question: "What is chemiosmosis?", options: ["The movement of protons down their concentration gradient through ATP synthase, driving ATP synthesis", "The diffusion of oxygen into cells", "The active transport of glucose", "The splitting of water during photosynthesis"], answer: 0, explanation: "Chemiosmosis uses the proton gradient generated by electron transport to power ATP synthase and produce ATP." },
  { question: "What is the anaerobic respiration pathway in yeast, producing ethanol and carbon dioxide, known as?", options: ["Alcoholic fermentation", "Lactic acid fermentation", "Oxidative phosphorylation", "The Krebs cycle"], answer: 0, explanation: "Yeast undergoes alcoholic fermentation under anaerobic conditions, producing ethanol and CO2." },
  { question: "What are the light-dependent reactions of photosynthesis primarily responsible for producing?", options: ["ATP and reduced NADP (with oxygen as a byproduct)", "Glucose directly", "Carbon dioxide", "Only water"], answer: 0, explanation: "The light-dependent reactions capture light energy to produce ATP and reduced NADP, releasing oxygen from water splitting." },
  { question: "What is photolysis?", options: ["The splitting of water molecules by light energy, releasing oxygen, protons, and electrons", "The breakdown of glucose using light", "A synonym for the Calvin cycle", "The absorption of carbon dioxide by chlorophyll"], answer: 0, explanation: "Photolysis is the light-driven splitting of water within the light-dependent reactions of photosynthesis." },
  { question: "What is the first stable product of the Calvin cycle?", options: ["Glycerate 3-phosphate (GP)", "Glucose", "Ribulose bisphosphate (RuBP)", "Pyruvate"], answer: 0, explanation: "Carbon dioxide combines with RuBP to form an unstable 6-carbon compound that immediately splits into two molecules of GP." },
  { question: "What enzyme catalyses the fixation of carbon dioxide in the Calvin cycle?", options: ["RuBisCO", "ATP synthase", "DNA polymerase", "Amylase"], answer: 0, explanation: "RuBisCO catalyses the reaction between carbon dioxide and RuBP, the first step of carbon fixation." },
  { question: "What is a limiting factor in photosynthesis?", options: ["A factor, such as light intensity or CO2 concentration, that restricts the rate when in short supply", "A factor that always increases the rate of photosynthesis", "A factor unrelated to photosynthetic rate", "A byproduct of the Calvin cycle"], answer: 0, explanation: "Limiting factors — light intensity, CO2 concentration, or temperature — cap the rate of photosynthesis when they are in short supply." },
  { question: "What is gene expression?", options: ["The process by which information from a gene is used to synthesise a functional product, usually a protein", "The physical location of a gene on a chromosome", "The process of DNA replication only", "A synonym for mutation"], answer: 0, explanation: "Gene expression encompasses transcription and translation, converting genetic information into a functional protein." },
  { question: "What is a point mutation?", options: ["A mutation affecting a single nucleotide base, through substitution, insertion, or deletion", "A mutation affecting an entire chromosome", "A mutation that only occurs in gametes", "A mutation that always causes a disease"], answer: 0, explanation: "Point mutations involve a change at a single base position in the DNA sequence." },
  { question: "What is a frameshift mutation?", options: ["An insertion or deletion that shifts the reading frame, altering all subsequent codons", "A substitution that changes only one amino acid", "A mutation that has no effect on the protein", "A mutation only found in bacteria"], answer: 0, explanation: "Because codons are read in fixed groups of three, an insertion or deletion (not in multiples of three) shifts every subsequent codon." },
  { question: "What is a silent mutation?", options: ["A mutation that does not change the resulting amino acid sequence, due to the degenerate genetic code", "A mutation that always halts protein synthesis", "A mutation only found in non-coding DNA", "A synonym for a frameshift mutation"], answer: 0, explanation: "Because multiple codons can code for the same amino acid, some base changes don't alter the protein produced." },
  { question: "What does it mean that the genetic code is 'degenerate'?", options: ["Most amino acids are coded for by more than one codon", "Each amino acid has exactly one codon", "The code varies randomly between organisms", "The code cannot be read by ribosomes"], answer: 0, explanation: "Degeneracy refers to the redundancy in the genetic code, where several codons can specify the same amino acid." },
  { question: "What is a nonsense mutation?", options: ["A mutation that results in a premature stop codon", "A mutation that has no effect", "A mutation that only affects introns", "A synonym for a silent mutation"], answer: 0, explanation: "A nonsense mutation changes a codon into a stop codon, truncating the protein prematurely." },
  { question: "What enzyme is used to cut DNA at specific sequences in genetic engineering?", options: ["Restriction endonuclease", "DNA ligase", "DNA polymerase", "RNA polymerase"], answer: 0, explanation: "Restriction endonucleases (restriction enzymes) recognise and cut DNA at specific base sequences." },
  { question: "What enzyme is used to join DNA fragments together in genetic engineering?", options: ["Restriction endonuclease", "DNA ligase", "DNA polymerase", "Reverse transcriptase"], answer: 1, explanation: "DNA ligase seals DNA fragments together by forming phosphodiester bonds." },
  { question: "What is a vector, in the context of genetic engineering?", options: ["A vehicle, such as a plasmid or virus, used to transfer foreign DNA into a host cell", "A type of enzyme that cuts DNA", "A synonym for a gene", "A type of mutation"], answer: 0, explanation: "Vectors like plasmids carry the desired gene into a host cell for expression." },
  { question: "What is a plasmid?", options: ["A small circular piece of DNA found in bacteria, separate from the main chromosome", "A type of virus", "A protein found in the nucleus", "A synonym for a chromosome"], answer: 0, explanation: "Plasmids are small, circular DNA molecules commonly found in bacteria, often used as vectors in genetic engineering." },
  { question: "What enzyme is essential for PCR, due to its heat stability?", options: ["Taq polymerase", "DNA ligase", "Restriction endonuclease", "RNA polymerase"], answer: 0, explanation: "Taq polymerase, from a heat-tolerant bacterium, withstands the repeated high temperatures used in PCR cycling." },
  { question: "What are the three main steps of a PCR cycle, in order?", options: ["Denaturation, annealing, extension", "Extension, annealing, denaturation", "Annealing, denaturation, extension", "Denaturation, extension, annealing"], answer: 0, explanation: "Each PCR cycle proceeds through denaturation (separating strands), annealing (primer binding), and extension (new strand synthesis)." },
  { question: "What happens during the annealing step of PCR?", options: ["Primers bind to complementary sequences on the single-stranded DNA", "The DNA is heated to separate the strands", "New DNA strands are synthesised", "The DNA sample is centrifuged"], answer: 0, explanation: "During annealing, the temperature is lowered so primers can bind to their complementary target sequences." },
  { question: "What is gene therapy?", options: ["The introduction of genetic material into cells to treat or prevent disease", "A method for sequencing an entire genome", "A technique for measuring gene expression levels", "A synonym for selective breeding"], answer: 0, explanation: "Gene therapy aims to correct or compensate for faulty genes by introducing functional genetic material." },
  { question: "What is the term for the frequency of a particular allele within a population's gene pool?", options: ["Allele frequency", "Genotype frequency", "Mutation rate", "Gene flow"], answer: 0, explanation: "Allele frequency measures how common a specific allele is relative to all alleles for that gene in the population." },
  { question: "What does the Hardy-Weinberg equation, p² + 2pq + q² = 1, describe?", options: ["The predicted genotype frequencies in a non-evolving population", "The rate of mutation in a population", "The rate of natural selection", "The process of speciation"], answer: 0, explanation: "This equation predicts the proportions of homozygous dominant, heterozygous, and homozygous recessive genotypes at equilibrium." },
  { question: "If the frequency of a recessive allele (q) is 0.3, find q² (the frequency of homozygous recessive individuals).", options: ["0.03", "0.09", "0.3", "0.6"], answer: 1, explanation: "q² = 0.3² = 0.09." },
  { question: "In which type of population is genetic drift most significant?", options: ["Small populations", "Large populations", "Populations with no genetic variation", "Populations undergoing no reproduction"], answer: 0, explanation: "Random chance events have a proportionally larger effect on allele frequencies in small populations." },
  { question: "What is stabilising selection?", options: ["Natural selection that favours the average phenotype, reducing variation", "Selection favouring one extreme phenotype", "Selection favouring both extreme phenotypes", "A type of selection performed only in labs"], answer: 0, explanation: "Stabilising selection reduces variation by favouring individuals near the population's average trait value." },
  { question: "What is directional selection?", options: ["Natural selection that favours one extreme phenotype, shifting the population's mean", "Selection that favours the average phenotype", "Selection that favours both extremes", "Selection with no effect on allele frequency"], answer: 0, explanation: "Directional selection shifts a population's trait distribution toward one extreme, often in response to changing conditions." },
  { question: "What is disruptive selection?", options: ["Natural selection that favours both extreme phenotypes over the intermediate", "Selection that favours only the average phenotype", "Selection that only occurs in plants", "Selection with no genetic consequence"], answer: 0, explanation: "Disruptive selection favours both extremes over intermediates, potentially driving a population toward two distinct forms." },
  { question: "What is allopatric speciation?", options: ["Speciation occurring due to geographic isolation of populations", "Speciation occurring without any geographic separation", "A synonym for genetic drift", "Speciation that always occurs within a single generation"], answer: 0, explanation: "Allopatric speciation arises when populations are physically separated, preventing gene flow and allowing them to diverge." },
  { question: "What is sympatric speciation?", options: ["Speciation occurring without geographic isolation, often through reproductive or behavioural barriers", "Speciation requiring physical separation by a barrier", "A synonym for the founder effect", "Speciation that never actually occurs in nature"], answer: 0, explanation: "Sympatric speciation occurs within the same geographic area, driven by factors like reproductive timing or habitat preference." },
  { question: "What is intraspecific competition?", options: ["Competition between individuals of the same species for resources", "Competition between individuals of different species", "Cooperation between different species", "A synonym for predation"], answer: 0, explanation: "Intraspecific competition occurs among members of the same species competing for the same limited resources." },
  { question: "What is interspecific competition?", options: ["Competition between individuals of different species for resources", "Competition between individuals of the same species", "A synonym for mutualism", "A type of genetic drift"], answer: 0, explanation: "Interspecific competition occurs between different species competing for shared, limited resources." },
  { question: "What is the term for the total genetic material of an organism?", options: ["Genome", "Genotype", "Phenotype", "Proteome"], answer: 0, explanation: "The genome refers to the complete set of genetic material (DNA) within an organism." },
  { question: "What is a genome-wide association study (GWAS) used for?", options: ["Identifying genetic variants associated with particular traits or diseases across many individuals", "Sequencing a single gene in one individual", "Measuring protein concentration in blood", "Cloning an entire organism"], answer: 0, explanation: "GWAS scans genomes from many individuals to find genetic variants statistically linked to specific traits or conditions." },
  { question: "What is epigenetics?", options: ["The study of heritable changes in gene expression that do not involve changes to the DNA sequence", "The study of mutations in DNA sequences", "A synonym for genetic engineering", "The study of chromosome structure only"], answer: 0, explanation: "Epigenetic changes affect how genes are expressed without altering the underlying genetic code itself." },
  { question: "What is DNA methylation, an epigenetic mechanism?", options: ["The addition of methyl groups to DNA, often silencing gene expression", "The removal of a gene from the genome", "A type of point mutation", "The unwinding of the DNA double helix"], answer: 0, explanation: "Methylation typically occurs at specific DNA sites and generally represses (silences) gene expression." },
  { question: "What is a stem cell?", options: ["An undifferentiated cell capable of developing into specialised cell types", "A fully differentiated cell that cannot divide", "A cell found only in plants", "A synonym for a gamete"], answer: 0, explanation: "Stem cells retain the ability to differentiate into various specialised cell types." },
  { question: "What is the key difference between totipotent and pluripotent stem cells?", options: ["Totipotent cells can become any cell type including extra-embryonic tissue; pluripotent cells cannot form extra-embryonic tissue", "Pluripotent cells can only become blood cells", "Totipotent cells cannot divide at all", "There is no meaningful difference"], answer: 0, explanation: "Totipotent cells have the broadest potential, including forming placental tissue, while pluripotent cells can form almost any body cell type but not extra-embryonic tissue." },
  { question: "What is apoptosis?", options: ["Programmed cell death", "Uncontrolled cell death due to injury", "The process of cell division", "A type of mutation"], answer: 0, explanation: "Apoptosis is a controlled, genetically regulated process by which cells trigger their own death." },
  { question: "How does necrosis differ from apoptosis?", options: ["Necrosis is uncontrolled cell death from injury, often triggering inflammation, unlike the controlled process of apoptosis", "Necrosis is a synonym for apoptosis", "Necrosis only occurs in plants", "Necrosis never affects surrounding tissue"], answer: 0, explanation: "Unlike the tidy, programmed process of apoptosis, necrosis results from damage and can cause inflammation in surrounding tissue." },
  { question: "What is the role of telomeres?", options: ["Protective caps at the ends of chromosomes that prevent DNA damage during replication", "Regions of DNA that code for essential proteins", "The site where transcription begins", "A type of RNA molecule"], answer: 0, explanation: "Telomeres protect the ends of chromosomes from degradation and fusion with neighbouring chromosomes." },
  { question: "What generally happens to telomeres with each round of cell division?", options: ["They shorten", "They lengthen", "They remain exactly the same length", "They disappear entirely after one division"], answer: 0, explanation: "Telomeres progressively shorten with each cell division, eventually contributing to cellular ageing." },
  { question: "What is the role of the enzyme telomerase?", options: ["It extends telomeres, and is active in some cells like stem cells and cancer cells", "It shortens telomeres deliberately", "It repairs mutations in coding DNA", "It has no known biological role"], answer: 0, explanation: "Telomerase adds repetitive sequences to telomeres, counteracting their shortening in certain cell types." },
  { question: "What is a tumour suppressor gene?", options: ["A gene that regulates cell division and can prevent uncontrolled growth when functioning normally", "A gene that always causes cancer when active", "A gene found only in cancer cells", "A synonym for an oncogene"], answer: 0, explanation: "Tumour suppressor genes normally restrain cell division; their loss of function can contribute to cancer." },
  { question: "What is a proto-oncogene?", options: ["A normal gene that can become cancer-causing (an oncogene) through mutation", "A gene that always suppresses tumours", "A gene found only in viruses", "A non-functional segment of DNA"], answer: 0, explanation: "Proto-oncogenes normally regulate cell growth but can become oncogenes, promoting cancer, if mutated." },
  { question: "What is metastasis?", options: ["The spread of cancer cells from the original site to other parts of the body", "The initial formation of a tumour", "A type of chemotherapy", "The process of apoptosis in cancer cells"], answer: 0, explanation: "Metastasis occurs when cancer cells break away from the primary tumour and establish growths elsewhere in the body." },
  { question: "What is the role of ATP hydrolysis in active transport?", options: ["It provides the energy needed to drive carrier proteins moving molecules against their concentration gradient", "It has no role in active transport", "It only powers passive diffusion", "It breaks down the cell membrane"], answer: 0, explanation: "Active transport proteins use energy released from ATP hydrolysis to move substances against their concentration gradient." },
  { question: "What is the term for enzymes that are only produced when their substrate is present, allowing efficient use of cellular resources?", options: ["Inducible enzymes", "Constitutive enzymes", "Allosteric enzymes", "Cofactor enzymes"], answer: 0, explanation: "Inducible enzymes are synthesised in response to the presence of their specific substrate, rather than being produced continuously." }
];

const ALEVEL_COMPUTERSCIENCE_QUESTIONS = [
  { question: "What is the time complexity of binary search on a sorted array of n elements?", options: ["O(n)", "O(log n)", "O(n log n)", "O(n²)"], answer: 1, explanation: "Binary search halves the search space each step, giving logarithmic time complexity." },
  { question: "What is the time complexity of bubble sort in the worst case?", options: ["O(n)", "O(n log n)", "O(n²)", "O(log n)"], answer: 2, explanation: "Bubble sort compares and swaps adjacent elements repeatedly, giving quadratic worst-case time complexity." },
  { question: "Which data structure operates on a Last-In-First-Out (LIFO) basis?", options: ["Queue", "Stack", "Array", "Tree"], answer: 1, explanation: "A stack removes the most recently added item first, following LIFO order." },
  { question: "Which data structure operates on a First-In-First-Out (FIFO) basis?", options: ["Stack", "Queue", "Tree", "Graph"], answer: 1, explanation: "A queue removes the item that has been waiting the longest first, following FIFO order." },
  { question: "What is the term for a data structure in which each node has at most two children?", options: ["Linked list", "Binary tree", "Graph", "Hash table"], answer: 1, explanation: "A binary tree restricts each node to a maximum of two child nodes." },
  { question: "What is recursion in programming?", options: ["A function that calls itself to solve smaller instances of a problem", "A loop that never terminates", "A type of data structure", "A way to sort data only"], answer: 0, explanation: "Recursion involves a function calling itself, typically breaking a problem into smaller subproblems." },
  { question: "What is the purpose of a base case in a recursive function?", options: ["To stop the recursion and prevent infinite calls", "To increase recursion depth", "To slow down the program", "To store variables"], answer: 0, explanation: "The base case provides a stopping condition, preventing infinite recursive calls." },
  { question: "What does Big O notation describe?", options: ["The efficiency of an algorithm as input size grows", "The exact runtime of a program in seconds", "The number of lines of code", "The memory address of a variable"], answer: 0, explanation: "Big O notation expresses how an algorithm's time or space requirements scale with input size." },
  { question: "What is a hash table primarily used for?", options: ["Sorting data", "Fast data lookup using key-value pairs", "Storing data sequentially only", "Encrypting data"], answer: 1, explanation: "Hash tables use a hash function to enable near-constant-time lookup of values via keys." },
  { question: "What is the purpose of normalisation in database design?", options: ["To reduce data redundancy and improve data integrity", "To increase data redundancy", "To encrypt the database", "To speed up all queries regardless of design"], answer: 0, explanation: "Normalisation organises data to minimise redundancy and maintain consistency across tables." },
  { question: "What does SQL stand for?", options: ["Structured Query Language", "Sequential Query Language", "Simple Query Language", "Standard Query Logic"], answer: 0, explanation: "SQL stands for Structured Query Language, used to manage relational databases." },
  { question: "In SQL, which command is used to retrieve data from a database?", options: ["SELECT", "INSERT", "UPDATE", "DELETE"], answer: 0, explanation: "The SELECT statement retrieves data from one or more database tables." },
  { question: "What is a primary key in a database table?", options: ["A field that uniquely identifies each record in the table", "A field that can contain duplicate values", "A field used only for foreign relationships", "A field that stores passwords"], answer: 0, explanation: "A primary key uniquely identifies each row in a database table, and its values cannot repeat." },
  { question: "What is a foreign key used for?", options: ["Linking one table to another by referencing its primary key", "Encrypting data", "Sorting a table alphabetically", "Automatically deleting records"], answer: 0, explanation: "A foreign key establishes a relationship between two tables by referring to a primary key in another table." },
  { question: "What is the term for converting source code into machine code all at once, before execution?", options: ["Interpretation", "Compilation", "Assembly", "Debugging"], answer: 1, explanation: "Compilation translates the entire source code into machine code before the program runs." },
  { question: "What is the term for translating and executing source code line-by-line?", options: ["Compilation", "Interpretation", "Assembly", "Linking"], answer: 1, explanation: "Interpretation translates and executes code one line at a time, rather than compiling it all beforehand." },
  { question: "What is the fetch-execute cycle in a CPU?", options: ["The repeated process of fetching, decoding, and executing an instruction", "The process of compiling code", "The process of formatting a hard drive", "The process of rendering graphics"], answer: 0, explanation: "The fetch-execute cycle describes how a CPU continuously retrieves, decodes, and carries out instructions." },
  { question: "What is the purpose of the Arithmetic Logic Unit (ALU) in a CPU?", options: ["To perform arithmetic and logical operations", "To store data permanently", "To manage input/output devices", "To compile source code"], answer: 0, explanation: "The ALU carries out arithmetic calculations and logical comparisons within the CPU." },
  { question: "What is cache memory used for?", options: ["Storing frequently accessed data close to the CPU for faster access", "Permanently storing the operating system", "Connecting to the internet", "Cooling down the CPU"], answer: 0, explanation: "Cache memory is small, fast memory that stores frequently used data to reduce access time." },
  { question: "What is an abstract data type (ADT)?", options: ["A data type defined by its behaviour rather than its implementation", "A data type that cannot store any values", "A synonym for an array", "A type only used in object-oriented programming"], answer: 0, explanation: "An ADT specifies what operations are possible on data, without dictating how it is implemented internally." },
  { question: "What is polymorphism in object-oriented programming?", options: ["The ability of different classes to be treated as instances of a shared superclass", "The ability to create multiple copies of a variable", "A type of loop structure", "A database normalisation technique"], answer: 0, explanation: "Polymorphism allows objects of different subclasses to be handled through a common superclass interface, often via method overriding." },
  { question: "What is encapsulation in object-oriented programming?", options: ["Bundling data and methods within a class, restricting direct access to some components", "Splitting a program into multiple files", "A type of sorting algorithm", "A networking protocol"], answer: 0, explanation: "Encapsulation hides an object's internal state and requires interaction through defined methods." },
  { question: "What is the purpose of an operating system's scheduler?", options: ["To determine which processes run on the CPU and when", "To manage file names", "To design user interfaces", "To compile programs"], answer: 0, explanation: "The scheduler decides the order and timing in which processes are given CPU time." },
  { question: "What is a deadlock in operating systems?", options: ["A situation where processes are stuck waiting for resources held by each other", "A process that runs indefinitely fast", "A type of memory leak", "A successful process completion"], answer: 0, explanation: "A deadlock occurs when two or more processes each hold a resource the other needs, so none can proceed." },
  { question: "What is the purpose of an IP address in networking?", options: ["To uniquely identify a device on a network", "To encrypt data being sent", "To compile code remotely", "To store website content"], answer: 0, explanation: "An IP address uniquely identifies a device so data can be correctly routed to and from it on a network." },
  { question: "What is the time complexity of merge sort?", options: ["O(n)", "O(n log n)", "O(n²)", "O(log n)"], answer: 1, explanation: "Merge sort's divide-and-conquer approach gives it a time complexity of O(n log n) in all cases." },
  { question: "What is the average-case time complexity of quicksort?", options: ["O(n)", "O(n log n)", "O(n²)", "O(log n)"], answer: 1, explanation: "Quicksort has an average-case time complexity of O(n log n), though its worst case is worse." },
  { question: "What is the worst-case time complexity of quicksort?", options: ["O(n)", "O(n log n)", "O(n²)", "O(log n)"], answer: 2, explanation: "Quicksort's worst case, occurring with poor pivot choices, degrades to O(n²)." },
  { question: "Which sorting algorithm uses a divide-and-conquer approach, splitting the list into halves, sorting each, then merging them?", options: ["Bubble sort", "Merge sort", "Linear search", "Binary search"], answer: 1, explanation: "Merge sort recursively divides the list, sorts each half, and merges the sorted halves back together." },
  { question: "What is a stable sorting algorithm?", options: ["One that preserves the relative order of equal elements", "One that always runs in O(n) time", "One that never uses recursion", "One that only works on sorted data"], answer: 0, explanation: "A stable sort guarantees that elements with equal keys retain their original relative order after sorting." },
  { question: "What data structure follows a first-in, first-out (FIFO) principle?", options: ["Stack", "Queue", "Binary tree", "Hash table"], answer: 1, explanation: "A queue serves elements in the order they were added, following FIFO." },
  { question: "What is a priority queue?", options: ["A queue where elements with higher priority are served before lower-priority elements", "A queue that only stores integers", "A queue with a fixed maximum size", "A synonym for a stack"], answer: 0, explanation: "In a priority queue, elements are dequeued based on priority rather than strictly on arrival order." },
  { question: "What is a binary search tree?", options: ["A tree where each node's left subtree contains smaller values and right subtree contains larger values", "A tree where every node has exactly two children", "A tree with no order to its nodes", "A synonym for a linked list"], answer: 0, explanation: "Binary search trees maintain an ordering property that allows for efficient searching." },
  { question: "What is the time complexity of searching a balanced binary search tree?", options: ["O(1)", "O(log n)", "O(n)", "O(n²)"], answer: 1, explanation: "A balanced BST allows searches to eliminate half the remaining nodes at each step, giving O(log n) complexity." },
  { question: "What happens to a binary search tree's search performance if it becomes highly unbalanced?", options: ["It stays at O(log n)", "It can degrade to O(n)", "It becomes O(1)", "It has no effect on performance"], answer: 1, explanation: "An unbalanced tree (e.g., resembling a linked list) loses its logarithmic search advantage, degrading to O(n)." },
  { question: "What is a heap data structure primarily used for?", options: ["Efficiently finding the maximum or minimum element (e.g., in priority queues)", "Storing data in alphabetical order only", "Encrypting data", "Compiling source code"], answer: 0, explanation: "Heaps maintain a specific ordering property that allows fast access to the maximum or minimum element." },
  { question: "What is the difference between a min-heap and a max-heap?", options: ["In a min-heap, the smallest element is at the root; in a max-heap, the largest is at the root", "A min-heap only stores negative numbers", "A max-heap can only have one child per node", "There is no functional difference"], answer: 0, explanation: "Min-heaps and max-heaps differ in which extreme value is maintained at the root of the structure." },
  { question: "What is a graph, in data structure terms?", options: ["A collection of nodes (vertices) connected by edges", "A type of sorted array", "A synonym for a binary tree", "A structure that can only store numbers"], answer: 0, explanation: "Graphs consist of vertices (nodes) and edges representing connections or relationships between them." },
  { question: "What is the difference between a directed and undirected graph?", options: ["Directed graph edges have a direction; undirected graph edges do not", "Directed graphs cannot contain cycles", "Undirected graphs cannot have weighted edges", "There is no meaningful difference"], answer: 0, explanation: "In a directed graph, each edge points from one vertex to another; in an undirected graph, edges have no direction." },
  { question: "What algorithm is commonly used to find the shortest path between nodes in a weighted graph?", options: ["Dijkstra's algorithm", "Bubble sort", "Binary search", "Merge sort"], answer: 0, explanation: "Dijkstra's algorithm efficiently finds the shortest path from a source node to all other nodes in a weighted graph." },
  { question: "Which graph traversal algorithm explores level by level, typically using a queue?", options: ["Breadth-first search (BFS)", "Depth-first search (DFS)", "Binary search", "Quicksort"], answer: 0, explanation: "BFS explores all neighbours at the current depth before moving to nodes at the next depth level, using a queue." },
  { question: "Which graph traversal algorithm explores as far as possible along a branch before backtracking, typically using a stack?", options: ["Breadth-first search (BFS)", "Depth-first search (DFS)", "Binary search", "Merge sort"], answer: 1, explanation: "DFS follows one path deeply before backtracking, commonly implemented with a stack or recursion." },
  { question: "What is a Turing machine?", options: ["A theoretical computational model that manipulates symbols on a tape according to rules", "A physical computer built in the 1950s", "A type of modern CPU", "A programming language"], answer: 0, explanation: "The Turing machine is an abstract model used to formally define computation and algorithms." },
  { question: "What is the significance of the Turing machine in computer science?", options: ["It provides a formal definition of what is computable", "It was the first commercially sold computer", "It only applies to quantum computing", "It has no theoretical significance"], answer: 0, explanation: "The Turing machine underpins the Church-Turing thesis, formalising the concept of computability." },
  { question: "What is a finite state machine (FSM)?", options: ["A model of computation with a finite number of states and transitions between them", "A type of unlimited-memory computer", "A synonym for a Turing machine with infinite states", "A physical computer chip"], answer: 0, explanation: "FSMs model systems that can be in one of a limited number of states, moving between them based on inputs." },
  { question: "What is a regular expression primarily used for?", options: ["Matching patterns within text", "Compiling source code", "Managing computer memory", "Designing circuit diagrams"], answer: 0, explanation: "Regular expressions define search patterns used to find, validate, or manipulate text." },
  { question: "What is the halting problem?", options: ["The problem of determining whether a given program will halt or run forever, proven undecidable", "A common bug found in all programs", "A hardware fault in older computers", "A type of memory leak"], answer: 0, explanation: "The halting problem, famously proven undecidable by Turing, shows no general algorithm can determine this for all possible programs." },
  { question: "What does it mean for a problem to be 'undecidable'?", options: ["No algorithm can be constructed that always produces a correct yes-or-no answer", "The problem has never been attempted", "The problem is always solvable with enough time", "The problem only applies to hardware"], answer: 0, explanation: "Undecidable problems have been proven to have no general algorithmic solution." },
  { question: "What is the difference between P and NP problems in computational complexity theory?", options: ["P problems can be solved in polynomial time; NP problems can be verified in polynomial time", "P problems cannot be solved at all; NP problems can", "NP problems are always faster to solve than P problems", "There is no meaningful difference"], answer: 0, explanation: "P is the class of problems solvable quickly; NP is the class of problems whose solutions can be verified quickly, even if not necessarily found quickly." },
  { question: "What is an NP-complete problem?", options: ["A problem that is both in NP and as hard as any other problem in NP", "A problem that has already been fully solved", "A problem outside of computer science", "A problem with no known applications"], answer: 0, explanation: "NP-complete problems represent the hardest problems within NP, and a fast solution to one would solve all NP problems quickly." },
  { question: "What does an inner join in SQL do?", options: ["Combines rows from two tables where there is a match in both", "Returns all rows from one table regardless of matches", "Deletes unmatched rows permanently", "Creates a new empty table"], answer: 0, explanation: "An inner join returns only the rows where the joined columns match in both tables." },
  { question: "What does a left join in SQL do?", options: ["Returns all rows from the left table, with matched rows from the right table (or nulls if no match)", "Returns only matching rows from both tables", "Returns all rows from the right table only", "Deletes non-matching data"], answer: 0, explanation: "A left join keeps every row from the left table, filling in nulls for any unmatched right-table columns." },
  { question: "What is database normalization used to achieve?", options: ["Reducing data redundancy and improving data integrity", "Increasing data redundancy for backup purposes", "Encrypting all stored data", "Automatically deleting old records"], answer: 0, explanation: "Normalization organizes data across related tables to minimize duplication and maintain consistency." },
  { question: "What does First Normal Form (1NF) require of a database table?", options: ["Each column contains atomic (indivisible) values, and each record is unique", "Every table must have at least three columns", "All data must be numeric", "Tables cannot have a primary key"], answer: 0, explanation: "1NF eliminates repeating groups and requires that each field hold only a single, indivisible value." },
  { question: "What does Second Normal Form (2NF) require, in addition to 1NF?", options: ["No partial dependency — all non-key attributes must depend on the whole primary key", "All columns must be text-based", "Tables must have no primary key", "Data must be duplicated across tables"], answer: 0, explanation: "2NF removes partial dependencies, ensuring non-key attributes rely on the entire composite primary key, not just part of it." },
  { question: "What does Third Normal Form (3NF) require, in addition to 2NF?", options: ["No transitive dependency — non-key attributes should depend only on the primary key", "Tables must contain duplicate data", "All fields must be foreign keys", "Tables cannot be related to each other"], answer: 0, explanation: "3NF removes transitive dependencies, where a non-key attribute depends on another non-key attribute rather than the primary key directly." },
  { question: "What does the OSI model describe?", options: ["The seven layers of network communication functions", "The internal architecture of a CPU", "A type of database structure", "A programming paradigm"], answer: 0, explanation: "The OSI model is a conceptual framework describing how data moves through seven distinct network layers." },
  { question: "Which OSI layer is responsible for routing data between different networks?", options: ["Physical layer", "Network layer", "Session layer", "Presentation layer"], answer: 1, explanation: "The Network layer handles logical addressing and routing of data packets across networks." },
  { question: "Which OSI layer is responsible for reliable end-to-end data transmission?", options: ["Data Link layer", "Network layer", "Transport layer", "Application layer"], answer: 2, explanation: "The Transport layer manages reliable delivery, including error checking and flow control, between end systems." },
  { question: "What is TCP (Transmission Control Protocol) primarily responsible for?", options: ["Reliable, ordered, and error-checked delivery of data between applications", "Assigning IP addresses to devices", "Encrypting all internet traffic", "Rendering web pages"], answer: 0, explanation: "TCP establishes a connection and ensures data arrives completely, in order, and without errors." },
  { question: "How does UDP (User Datagram Protocol) differ from TCP?", options: ["UDP is faster and connectionless, without guaranteed delivery or ordering", "UDP guarantees delivery better than TCP", "UDP is only used for encrypted traffic", "UDP requires a persistent connection like TCP"], answer: 0, explanation: "UDP sacrifices reliability guarantees for speed, making it suitable for applications like streaming where some data loss is tolerable." },
  { question: "What is packet switching?", options: ["Breaking data into packets that are routed independently across a network", "A method of physically switching network cables", "A type of data encryption", "A hardware component in routers only"], answer: 0, explanation: "Packet switching divides data into discrete packets, each routed independently and reassembled at the destination." },
  { question: "What does the Software Development Life Cycle (SDLC) describe?", options: ["A structured process for planning, creating, testing, and deploying software", "A single programming language's syntax rules", "A type of hardware architecture", "A method for compressing files"], answer: 0, explanation: "SDLC outlines the stages software typically passes through, from initial planning to deployment and maintenance." },
  { question: "What characterises the waterfall model of software development?", options: ["A linear, sequential approach where each phase must complete before the next begins", "Continuous, iterative cycles with frequent stakeholder feedback", "No formal planning phase at all", "Development without any testing phase"], answer: 0, explanation: "The waterfall model progresses through fixed, sequential stages, with limited ability to revisit earlier phases." },
  { question: "What characterises agile software development?", options: ["Iterative development, flexibility, and close collaboration with stakeholders", "A strict, unchangeable plan set at the very start", "Development with no communication with the client", "Testing only at the very end of the project"], answer: 0, explanation: "Agile methodologies emphasize adaptability, incremental delivery, and ongoing stakeholder involvement." },
  { question: "What is a 'sprint' in Scrum, an agile framework?", options: ["A fixed, short time period during which a specific set of work is completed", "The final release of a finished product", "A synonym for the entire project timeline", "A type of software bug"], answer: 0, explanation: "Sprints are short, time-boxed periods (often 1-4 weeks) in which a team completes a defined chunk of work." },
  { question: "What is a use case diagram used for in software design?", options: ["Illustrating interactions between users (actors) and a system", "Showing the physical wiring of a network", "Displaying database table relationships only", "Representing binary data"], answer: 0, explanation: "Use case diagrams visually map out how different users interact with a system's functionality." },
  { question: "What is the purpose of unit testing?", options: ["Testing individual components or functions of a program in isolation", "Testing the entire finished system as a whole", "Testing only the user interface", "Testing network speed"], answer: 0, explanation: "Unit tests verify that small, isolated pieces of code (like individual functions) behave correctly." },
  { question: "What is the purpose of integration testing?", options: ["Testing how different modules or components work together", "Testing a single function in isolation", "Testing only the database schema", "Testing the hardware only"], answer: 0, explanation: "Integration testing checks that separately developed modules interact correctly when combined." },
  { question: "What characterises von Neumann architecture?", options: ["A single memory space storing both instructions and data", "Completely separate memory for instructions and data", "No memory at all, only registers", "Memory located exclusively on external drives"], answer: 0, explanation: "Von Neumann architecture uses one shared memory space for both program instructions and data." },
  { question: "What characterises Harvard architecture, as distinct from von Neumann?", options: ["Separate memory spaces for instructions and data", "A single shared memory for everything", "No use of registers", "The complete absence of a CPU"], answer: 0, explanation: "Harvard architecture uses distinct memory pathways for instructions and data, allowing simultaneous access to both." },
  { question: "What is pipelining in CPU design?", options: ["Overlapping the execution of multiple instructions to improve throughput", "Running only one instruction at a time, very slowly", "A method for cooling the CPU", "A type of network cable"], answer: 0, explanation: "Pipelining breaks instruction execution into stages that can overlap, increasing the CPU's overall instruction throughput." },
  { question: "What is a cache hit?", options: ["When requested data is found in the cache, avoiding a slower memory access", "When the cache is completely empty", "When data is permanently deleted from cache", "When a program crashes"], answer: 0, explanation: "A cache hit occurs when the CPU finds needed data already stored in the fast cache memory." },
  { question: "What is a cache miss?", options: ["When requested data is not found in the cache, requiring a slower fetch from main memory", "When the cache overflows with too much data", "A synonym for a cache hit", "A hardware malfunction"], answer: 0, explanation: "A cache miss forces the CPU to retrieve data from slower main memory instead of the fast cache." },
  { question: "What is virtual memory?", options: ["A memory management technique using disk space to extend the apparent amount of RAM", "A type of memory that doesn't physically exist anywhere", "RAM used exclusively for graphics", "A synonym for cache memory"], answer: 0, explanation: "Virtual memory allows a system to use disk space as an extension of physical RAM, supporting larger or more programs than RAM alone." },
  { question: "What is a page fault?", options: ["When a program accesses a memory page not currently in physical memory, requiring it to be loaded from disk", "A syntax error in code", "A hardware failure in the CPU", "A network connection error"], answer: 0, explanation: "A page fault triggers the operating system to retrieve the needed page from disk (in virtual memory systems) into physical RAM." },
  { question: "What is multithreading?", options: ["The ability of a CPU or program to execute multiple threads concurrently", "Running only a single process at a time", "A method for compressing files", "A type of database structure"], answer: 0, explanation: "Multithreading allows multiple sequences of instructions (threads) to run concurrently, improving efficiency for suitable tasks." },
  { question: "What is the purpose of a semaphore in concurrent programming?", options: ["Controlling access to shared resources to prevent conflicts", "Compiling code faster", "Encrypting network traffic", "Displaying error messages to users"], answer: 0, explanation: "Semaphores coordinate access to shared resources among multiple threads or processes, preventing race conditions." },
  { question: "What is a race condition?", options: ["A situation where the outcome of a program depends on the unpredictable timing of concurrent processes", "A competition between two computers to finish first", "A type of hardware fault", "A synonym for a syntax error"], answer: 0, explanation: "Race conditions occur when concurrent operations access shared data in ways that produce inconsistent or unexpected results depending on timing." },
  { question: "What characterises functional programming?", options: ["Treating computation as the evaluation of mathematical functions, avoiding changing state and mutable data", "Relying exclusively on global variables", "Requiring all code to be written in machine language", "Prohibiting the use of any functions"], answer: 0, explanation: "Functional programming emphasizes pure functions and immutability, avoiding side effects wherever possible." },
  { question: "What is a 'pure function' in functional programming?", options: ["A function that always produces the same output for the same input and has no side effects", "A function that modifies global variables", "A function with no parameters", "A function that always returns null"], answer: 0, explanation: "Pure functions are deterministic and free of side effects, making them predictable and easier to test." },
  { question: "What technique is often used instead of loops in functional programming?", options: ["Recursion", "GOTO statements", "Manual memory management", "Assembly language instructions"], answer: 0, explanation: "Functional programming commonly favours recursion over iterative loops for repeated operations." },
  { question: "What is Boolean algebra used for in computing?", options: ["Simplifying and analysing logic circuits", "Compressing image files", "Managing network traffic", "Formatting hard drives"], answer: 0, explanation: "Boolean algebra provides the mathematical foundation for designing and simplifying digital logic circuits." },
  { question: "According to De Morgan's law, what is NOT(A AND B) equivalent to?", options: ["(NOT A) OR (NOT B)", "(NOT A) AND (NOT B)", "A OR B", "A AND B"], answer: 0, explanation: "De Morgan's law states that the negation of a conjunction equals the disjunction of the negations." },
  { question: "According to De Morgan's law, what is NOT(A OR B) equivalent to?", options: ["(NOT A) OR (NOT B)", "(NOT A) AND (NOT B)", "A OR B", "A AND B"], answer: 1, explanation: "De Morgan's law states that the negation of a disjunction equals the conjunction of the negations." },
  { question: "What is a NAND gate?", options: ["A gate that outputs 0 only when all inputs are 1 (the inverse of AND)", "A gate that always outputs 1", "A gate identical to an OR gate", "A gate with no inputs"], answer: 0, explanation: "NAND is the negation of AND, outputting 0 only in the single case where every input is 1." },
  { question: "What is a NOR gate?", options: ["A gate that outputs 1 only when all inputs are 0 (the inverse of OR)", "A gate identical to an AND gate", "A gate that always outputs 0", "A gate with no logical function"], answer: 0, explanation: "NOR is the negation of OR, outputting 1 only in the single case where every input is 0." },
  { question: "What is a half adder circuit used for?", options: ["Adding two single binary digits, producing a sum and carry output", "Adding three binary digits including a carry-in", "Subtracting binary numbers", "Multiplying binary numbers"], answer: 0, explanation: "A half adder takes two single-bit inputs and produces a sum bit and a carry bit, but cannot handle a carry-in." },
  { question: "What is a full adder circuit used for, as distinct from a half adder?", options: ["Adding two binary digits plus a carry-in, producing a sum and carry-out", "Only adding two digits with no carry handling", "Dividing binary numbers", "Storing binary data permanently"], answer: 0, explanation: "A full adder extends the half adder by also accepting a carry-in bit, enabling multi-bit binary addition." },
  { question: "What ethical issue can arise from algorithms trained on biased data?", options: ["The algorithm may perpetuate or amplify existing biases in its decisions", "The algorithm will always run faster", "The algorithm becomes immune to errors", "The algorithm requires less computing power"], answer: 0, explanation: "Machine learning systems trained on biased datasets can reproduce or worsen those biases in their outputs and decisions." },
  { question: "What is the purpose of data protection legislation, such as GDPR?", options: ["To protect individuals' personal data and regulate its collection, storage, and use", "To ban all forms of data collection entirely", "To speed up internet connections", "To standardize programming languages"], answer: 0, explanation: "Data protection laws set rules for how organizations may collect, store, process, and share personal data." },
  { question: "What does intellectual property refer to, in the context of software?", options: ["Legal rights protecting creations such as code, algorithms, and designs", "The physical hardware a program runs on", "A synonym for open-source licensing", "The memory used by a running program"], answer: 0, explanation: "Intellectual property law grants creators certain rights over their original works, including software and code." },
  { question: "What does open-source software licensing typically allow?", options: ["Users to view, modify, and distribute the source code, often under certain conditions", "Only the original developer to ever view the code", "Users to sell the software without any restrictions whatsoever", "The complete prohibition of any code sharing"], answer: 0, explanation: "Open-source licenses grant users rights to inspect, modify, and redistribute source code, typically with some conditions attached." },
  { question: "What is the purpose of a checksum in data transmission?", options: ["To detect errors that may have occurred during transmission", "To compress the data being sent", "To encrypt the data completely", "To speed up transmission automatically"], answer: 0, explanation: "A checksum is a calculated value sent alongside data, allowing the receiver to detect if errors occurred in transit." },
  { question: "What is parity checking used for?", options: ["Detecting single-bit errors in transmitted data by adding an extra bit", "Compressing large files", "Encrypting sensitive data", "Speeding up data transfer rates"], answer: 0, explanation: "Parity checking adds a bit to make the total number of 1s odd or even, allowing simple detection of single-bit transmission errors." },
  { question: "In terms of file recovery, what is the key difference between lossy and lossless compression?", options: ["Lossless compression allows the original file to be perfectly reconstructed; lossy does not", "Lossy compression always creates larger files", "Lossless compression cannot be reversed at all", "There is no meaningful difference"], answer: 0, explanation: "Lossless compression preserves all original data exactly; lossy compression permanently discards some data to save space." },
  { question: "What is a distributed system?", options: ["A system in which networked components communicate and coordinate by passing messages", "A single computer with multiple hard drives", "A program that only runs on one machine", "A type of database index"], answer: 0, explanation: "Distributed systems consist of multiple independent computers working together, appearing to users as a single coherent system." },
  { question: "What is cloud computing?", options: ["The delivery of computing services, such as storage and processing, over the internet on demand", "A method of predicting weather using computers", "A synonym for a local area network", "A type of programming language"], answer: 0, explanation: "Cloud computing provides on-demand access to computing resources hosted remotely and delivered via the internet." },
  { question: "What is the purpose of an API (Application Programming Interface)?", options: ["To allow different software applications to communicate with each other according to defined rules", "To physically connect computer hardware", "To design a website's visual layout", "To permanently store user passwords"], answer: 0, explanation: "APIs define a set of rules that let separate software systems request and exchange data or functionality." },
  { question: "What is the purpose of version control systems, such as Git?", options: ["To track changes to code over time and support collaboration between developers", "To compile code into an executable", "To design a database schema", "To render a graphical user interface"], answer: 0, explanation: "Version control tracks the history of code changes, enabling collaboration and the ability to revert to earlier states." }
];

